    "explanation": "**[풀이]**\n\n**핵심 개념:** 서로 다른 $n$개를 일렬로 나열하는 경우의 수는 $n!$ (팩토리얼)입니다.\n$$n! = n \\times (n-1) \\times (n-2) \\times \\cdots \\times 1$$\n\n**Step 1. 순열 판별**\n서로 다른 5개의 공을 **모두** 사용하여 일렬로 나열하는 문제입니다. '일렬로 나열'이므로 순서가 중요하고, 이는 순열(Permutation)에 해당합니다.\n\n**Step 2. 각 자리에 올 수 있는 공의 수 세기 (곱의 법칙)**\n자리를 왼쪽부터 채워 나갑니다.\n- 첫 번째 자리: 5개의 공 중 아무거나 → **5가지**\n- 두 번째 자리: 하나를 사용했으므로 남은 → **4가지**\n- 세 번째 자리: **3가지**\n- 네 번째 자리: **2가지**\n- 다섯 번째 자리: 남은 1개 → **1가지**\n\n**Step 3. 곱의 법칙으로 전체 경우의 수 계산**\n각 자리의 선택은 독립적이므로 곱의 법칙을 적용합니다.\n$$5! = 5 \\times 4 \\times 3 \\times 2 \\times 1 = 120$$\n\n**Step 4. 검증**\n만약 공이 3개였다면 $3! = 6$가지, 4개였다면 $4! = 24$가지입니다. 5개일 때 120가지는 합리적인 결과입니다. ✓\n\n**∴ 답: 120**\n\n**💡 포인트:** '서로 다른 n개를 모두 일렬로' → $n!$을 바로 적용하면 됩니다. 순열의 가장 기본 공식이므로 반드시 익혀 두세요.",
