    "explanation": "**[풀이]**\n\n**핵심 개념:** $n$명을 원형으로 배열하는 **원순열**의 공식은 $(n-1)!$입니다.\n$$\\text{원순열} = (n-1)!$$\n\n**Step 1. 왜 원순열인가?**\n원형 탁자에서는 회전하여 같아지는 배열을 하나로 봅니다. 예를 들어 일렬에서 ABCDEF와 BCDEFA는 서로 다른 배열이지만, 원형 탁자에서는 모든 사람의 상대적 위치가 같으므로 동일한 배열입니다. 이러한 회전 중복을 제거해야 합니다.\n\n**Step 2. 기준점 고정 방법**\n한 사람(예: A)을 기준으로 자리에 고정합니다. 그러면 나머지 $(n-1)$명을 일렬로 배열하는 것과 같아집니다.\n6명 중 1명을 고정하면 나머지 5명을 배열합니다.\n$$(6-1)! = 5!$$\n\n**Step 3. 계산**\n$$5! = 5 \\times 4 \\times 3 \\times 2 \\times 1 = 120$$\n\n**Step 4. 왜 $6!$이 아닌지 검증**\n일렬 순열 $6! = 720$가지 중에서, 원형에서는 6자리를 회전하면 같은 배열이 6가지씩 생기므로:\n$$\\frac{6!}{6} = \\frac{720}{6} = 120$$\n이것은 $(6-1)! = 120$과 정확히 일치합니다. ✓\n\n**∴ 답: ③ 120**\n\n⑤ 720은 일렬 순열 $6!$을 구한 경우로, 원형 배열의 회전 중복을 고려하지 않은 오답입니다.\n\n**💡 포인트:** 원형 배열 → $(n-1)!$, 일렬 배열 → $n!$을 구분하세요. 원순열은 일렬 순열을 $n$으로 나눈 것과 같습니다.",
