    "explanation": "**[풀이]**\n\n**핵심 개념:** 특정 사람들이 **이웃(인접)**해야 할 때는, 그들을 하나의 묶음으로 취급하는 **묶음 순열**을 사용합니다.\n$$\\text{(전체 배열)} = (\\text{묶음 포함 배열}) \\times (\\text{묶음 내부 배열})$$\n\n**Step 1. 묶음 만들기**\n여학생 2명을 하나의 묶음 [여여]로 취급합니다.\n그러면 배열할 대상은: [여여 묶음], 남1, 남2, 남3 → **총 4개**입니다.\n\n**Step 2. 묶음을 포함한 일렬 배열**\n4개의 대상을 일렬로 나열하는 경우의 수를 구합니다:\n$$4! = 4 \\times 3 \\times 2 \\times 1 = 24$$\n\n**Step 3. 묶음 내부 배열**\n묶음 안에서 여학생 2명의 자리를 서로 바꿀 수 있습니다 (여1-여2 또는 여2-여1):\n$$2! = 2$$\n\n**Step 4. 곱의 법칙으로 최종 답 계산**\n묶음 배열과 내부 배열은 독립적인 선택이므로 곱합니다:\n$$4! \\times 2! = 24 \\times 2 = 48$$\n\n**Step 5. 검증**\n전체 5명의 일렬 배열은 $5! = 120$가지이고, 여학생이 이웃하는 경우 48가지는 전체의 40%입니다. 5자리 중 이웃한 2칸을 차지하는 비율로 보면 합리적입니다. ✓\n\n**∴ 답: ③ 48**\n\n② 36은 어디에도 해당하지 않는 잘못된 계산이고, ① 24는 묶음 내부 배열($2!$)을 빠뜨린 경우입니다.\n\n**💡 포인트:** '이웃하다' → 묶음으로 묶고 → (전체 배열) × (묶음 내부 배열)로 계산합니다.",
