    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건에 따라 홀수와 짝수를 **지정된 자리에만** 배치하므로, 각 그룹을 독립적으로 배열한 뒤 **곱의 법칙**을 적용합니다.\n$$\\text{(전체 경우의 수)} = (\\text{홀수 배열}) \\times (\\text{짝수 배열})$$\n\n**Step 1. 자리 분석**\n일곱 자리 수의 각 자리를 번호로 표시하면:\n- 홀수 번째 자리: 1번째, 3번째, 5번째, 7번째 → **4자리**\n- 짝수 번째 자리: 2번째, 4번째, 6번째 → **3자리**\n\n**Step 2. 숫자를 홀짝으로 분류**\n$\\{1, 2, 3, 4, 5, 6, 7\\}$에서:\n- 홀수: $\\{1, 3, 5, 7\\}$ → **4개** (홀수 번째 4자리에 배치)\n- 짝수: $\\{2, 4, 6\\}$ → **3개** (짝수 번째 3자리에 배치)\n홀수 4개와 홀수 자리 4개, 짝수 3개와 짝수 자리 3개가 정확히 일치하므로 빈자리 없이 채울 수 있습니다.\n\n**Step 3. 홀수 배치**\n홀수 4개를 홀수 번째 4자리에 배열합니다:\n$$4! = 4 \\times 3 \\times 2 \\times 1 = 24$$\n\n**Step 4. 짝수 배치**\n짝수 3개를 짝수 번째 3자리에 배열합니다:\n$$3! = 3 \\times 2 \\times 1 = 6$$\n\n**Step 5. 곱의 법칙으로 최종 답**\n홀수 배치와 짝수 배치는 서로 독립이므로:\n$$4! \\times 3! = 24 \\times 6 = 144$$\n\n**∴ 답: 144**\n\n**💡 포인트:** 자리에 조건이 있을 때는 각 조건 그룹의 배열 수를 따로 구해 곱합니다. 숫자 개수와 자리 수가 맞는지 먼저 확인하세요.",
