    "explanation": "**[풀이]**\n\n**핵심 개념:** 순서 없이 $n$개에서 $r$개를 선택하는 **조합** 공식:\n$$_nC_r = \\frac{n!}{r!(n-r)!}$$\n\n**Step 1. 순열 vs 조합 판별**\n'대표를 뽑는다'는 것은 뽑힌 사람들의 **순서가 상관없다**는 의미입니다. 예를 들어 {A, B, C}를 뽑는 것과 {B, C, A}를 뽑는 것은 같은 결과입니다.\n따라서 순열이 아닌 **조합(Combination)**을 사용합니다.\n\n**Step 2. 조합 공식 적용**\n10명에서 3명을 순서 없이 선택하므로:\n$$_{10}C_3 = \\frac{10!}{3! \\times 7!}$$\n분자에서 $7!$이 약분되어 간단해집니다:\n$$= \\frac{10 \\times 9 \\times 8}{3 \\times 2 \\times 1}$$\n\n**Step 3. 분자와 분모를 각각 계산**\n분자: $10 \\times 9 \\times 8 = 720$\n분모: $3 \\times 2 \\times 1 = 6$\n$$\\frac{720}{6} = 120$$\n\n**Step 4. 순열과의 비교 (검증)**\n만약 순서가 있는 순열이었다면 $_{10}P_3 = 10 \\times 9 \\times 8 = 720$이 됩니다.\n조합은 순열을 $r! = 3! = 6$으로 나눈 것이므로 $\\frac{720}{6} = 120$으로 일치합니다. ✓\n\n**∴ 답: 120**\n\n**💡 포인트:** '뽑다', '선택하다', '고르다' → 순서 무관 → 조합 $_nC_r$을 사용합니다. 순열과 조합의 차이를 정확히 구분하세요.",
