    "problem": "평면 위에 어느 세 점도 한 직선 위에 있지 않은 8개의 점이 있다. 이 점들 중 2개를 이어 만들 수 있는 선분의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 28,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 두 점을 이어 선분을 만들므로, 8개 중 2개를 **순서 없이** 선택하는 조합을 사용합니다.\n$$_nC_2 = \\frac{n(n-1)}{2}$$\n\n**Step 1. 문제 해석 — 왜 조합인가?**\n선분 AB와 선분 BA는 같은 선분입니다. 즉, 두 점의 **순서가 상관없으므로** 순열이 아닌 조합을 사용합니다.\n\n**Step 2. 어느 세 점도 일직선 위에 없는 조건 확인**\n이 조건 덕분에 어떤 두 점을 선택해도 유일한 선분이 만들어집니다. 만약 3개 이상의 점이 일직선 위에 있다면 같은 직선 위의 선분이 겹치게 되지만, 이 문제에서는 그런 경우가 없습니다.\n\n**Step 3. 조합 공식 적용**\n8개의 점에서 2개를 순서 없이 선택합니다:\n$$_8C_2 = \\frac{8!}{2! \\times 6!} = \\frac{8 \\times 7}{2 \\times 1}$$\n\n**Step 4. 계산**\n$$\\frac{8 \\times 7}{2} = \\frac{56}{2} = 28$$\n\n**Step 5. 관련 문제 확장**\n같은 8개의 점으로 삼각형을 만든다면 $_8C_3 = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1} = 56$개가 됩니다.\n\n**∴ 답: 28**\n\n**💡 포인트:** 선분 = 2점 선택 → $_nC_2$, 삼각형 = 3점 선택 → $_nC_3$. 기하 도형의 수를 구할 때는 조합을 사용합니다.",
