    "explanation": "**[풀이]**\n\n**핵심 개념:** 서로 다른 그룹에서 독립적으로 선택할 때는 각 그룹의 조합을 구한 뒤 **곱의 법칙**을 적용합니다.\n$$\\text{(전체)} = _5C_2 \\times _4C_2$$\n\n**Step 1. 남학생 선택**\n남학생 5명 중 2명을 순서 없이 선택합니다:\n$$_5C_2 = \\frac{5!}{2! \\times 3!} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n**Step 2. 여학생 선택**\n여학생 4명 중 2명을 순서 없이 선택합니다:\n$$_4C_2 = \\frac{4!}{2! \\times 2!} = \\frac{4 \\times 3}{2 \\times 1} = 6$$\n\n**Step 3. 곱의 법칙 적용**\n남학생 선택과 여학생 선택은 서로 독립적인 사건이므로 곱합니다:\n$$_5C_2 \\times _4C_2 = 10 \\times 6 = 60$$\n\n**Step 4. 왜 $_9C_4$가 아닌지 확인**\n전체 9명에서 4명을 뽑으면 $_9C_4 = 126$이지만, 이 경우 '남 2, 여 2'라는 조건을 만족시키지 않는 조합(예: 남 3, 여 1)도 포함됩니다. 따라서 조건별로 그룹을 나누어 따로 계산해야 합니다.\n\n**∴ 답: ④ 60**\n\n① 30은 $_5C_2 \\times _4C_1 = 10 \\times 3$처럼 여학생 1명만 뽑은 경우이고, ⑤ 70은 $_8C_4 = 70$으로 남녀 구분 없이 뽑은 경우입니다.\n\n**💡 포인트:** 각 그룹에서 정해진 수만큼 뽑을 때는 그룹별 조합을 따로 구해 곱합니다.",
