    "explanation": "**[풀이]**\n\n**핵심 개념:** 삼각형은 3개의 꼭짓점으로 결정됩니다. 어느 세 점도 일직선 위에 없으므로 $_nC_3$을 바로 적용합니다.\n$$_nC_3 = \\frac{n(n-1)(n-2)}{3!}$$\n\n**Step 1. 삼각형의 조건 확인**\n삼각형이 되려면 3개의 점이 한 직선 위에 있지 않아야 합니다.\n문제에서 '어느 세 점도 한 직선 위에 있지 않다'고 했으므로, 어떤 3개의 점을 골라도 반드시 삼각형이 됩니다. 따라서 제외할 경우가 없습니다.\n\n**Step 2. 조합 공식 적용**\n10개의 점에서 3개를 순서 없이 선택합니다:\n$$_{10}C_3 = \\frac{10!}{3! \\times 7!} = \\frac{10 \\times 9 \\times 8}{3 \\times 2 \\times 1}$$\n\n**Step 3. 분자와 분모를 각각 계산**\n분자: $10 \\times 9 \\times 8 = 720$\n분모: $3 \\times 2 \\times 1 = 6$\n$$\\frac{720}{6} = 120$$\n\n**Step 4. 만약 일직선 조건이 없다면?**\n예를 들어 10개의 점 중 4개가 한 직선 위에 있다면, 그 4개에서 만드는 $_4C_3 = 4$개의 '삼각형'은 실제로 삼각형이 아니므로 빼야 합니다:\n$_{10}C_3 - _4C_3 = 120 - 4 = 116$개\n이 문제에서는 그런 경우가 없으므로 120이 최종 답입니다.\n\n**∴ 답: ④ 120**\n\n① 45는 $_{10}C_2 = 45$로 선분의 수이고, ⑤ 150은 잘못된 계산입니다.\n\n**💡 포인트:** 삼각형 = 3점 선택 → $_nC_3$. 단, 일직선 위의 점이 있으면 그 조합을 빼야 합니다.",
