    "explanation": "**[풀이]**\n\n**핵심 개념:** 같은 크기의 **비구별 조**로 나눌 때는, 순서대로 나눈 뒤 **같은 크기 조의 수!**로 나누어 중복을 제거합니다.\n\n**Step 1. 순서대로 조 만들기**\n먼저 9명에서 첫째 조 3명을 뽑고, 남은 6명에서 둘째 조 3명을 뽑고, 나머지가 셋째 조입니다:\n$$_9C_3 \\times _6C_3 \\times _3C_3 = 84 \\times 20 \\times 1 = 1680$$\n\n**Step 2. 조의 구별 여부 확인**\n세 조에 이름(A조, B조, C조)이 없으므로 조끼리 구별하지 않습니다.\n예: {1,2,3}, {4,5,6}, {7,8,9}와 {4,5,6}, {1,2,3}, {7,8,9}는 같은 분할입니다.\n\n**Step 3. 중복 제거**\n같은 크기(3명)인 조가 3개이므로 $3! = 6$가지 순서가 중복됩니다:\n$$\\frac{1680}{3!} = \\frac{1680}{6} = 280$$\n\n**Step 4. 검증**\n만약 조에 이름이 있었다면 답은 1680이 되지만, 비구별 조이므로 280이 맞습니다. ✓\n\n**∴ 답: ① 280**\n\n⑤ 1680은 조에 이름이 있는 경우(구별하는 경우)로, 이 문제에서는 오답입니다.\n\n**💡 포인트:** 같은 크기 $k$개 조로 나누면 $k!$로 나누어야 합니다. 조에 이름이 있으면 나누지 않습니다.",
