    "answer": 34650,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 조 나누기 + 배정 문제에서, 코트(이름)가 배정되면 결국 조가 구별되므로 $k!$로 나눌 필요가 없습니다.\n\n**Step 1. 12명을 4명씩 3조로 나누기 (비구별)**\n$$\\frac{_{12}C_4 \\times _8C_4 \\times _4C_4}{3!}$$\n\n각 조합값 계산:\n$$_{12}C_4 = \\frac{12 \\times 11 \\times 10 \\times 9}{4!} = 495$$\n$$_8C_4 = \\frac{8 \\times 7 \\times 6 \\times 5}{4!} = 70$$\n$$_4C_4 = 1$$\n\n비구별 분할: $\\frac{495 \\times 70 \\times 1}{6} = \\frac{34650}{6} = 5775$\n\n**Step 2. 코트 배정**\n3개 팀에 A, B, C 코트를 배정하므로:\n$$3! = 6$$\n\n**Step 3. 최종 계산**\n$$5775 \\times 6 = 34650$$\n\n**Step 4. 더 빠른 풀이 (핵심 통찰)**\n코트 배정($3!$)과 중복 제거($\\div 3!$)가 상쇄됩니다!\n따라서 처음부터 조를 구별하여 계산하면:\n$$_{12}C_4 \\times _8C_4 \\times _4C_4 = 495 \\times 70 \\times 1 = 34650$$\n\n**Step 5. 검증**\n두 방법 모두 34650으로 일치합니다. ✓\n\n**∴ 답: 34650**\n\n**💡 포인트:** 조를 나눈 뒤 이름(코트, 방 등)을 배정하면 $\\div k!$과 $\\times k!$이 상쇄되어, 처음부터 구별 조합으로 계산해도 됩니다.",
