    "type": "조합",
    "problem": "정십이각형의 꼭짓점 12개 중 4개를 선택하여 만들 수 있는 사각형 중에서, 정십이각형과 변을 공유하지 않는 사각형의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 105,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 원 위의 $n$개 점에서 $k$개를 선택하되 인접한 점이 없는 경우의 수 공식:\n$$\\frac{n}{n-k} \\binom{n-k}{k}$$\n\n**Step 1. 문제 해석**\n정십이각형의 변을 공유하지 않는 사각형이란, 선택한 4개의 꼭짓점 중 원 위에서 **인접한 쌍이 하나도 없는** 것을 의미합니다.\n\n**Step 2. 공식 확인**\n원 위의 $n$개 점에서 $k$개를 택하되, 어떤 두 점도 인접하지 않게 선택하는 경우의 수는:\n$$\\frac{n}{n-k} \\binom{n-k}{k}$$\n여기서 $n = 12$, $k = 4$입니다.\n\n**Step 3. 대입 및 계산**\n$$\\frac{12}{12-4} \\binom{12-4}{4} = \\frac{12}{8} \\binom{8}{4}$$\n\n$\\binom{8}{4}$를 계산합니다:\n$$\\binom{8}{4} = \\frac{8 \\times 7 \\times 6 \\times 5}{4 \\times 3 \\times 2 \\times 1} = 70$$\n\n따라서:\n$$\\frac{12}{8} \\times 70 = \\frac{3}{2} \\times 70 = 105$$\n\n**Step 4. 검증**\n전체 사각형 수: $_{12}C_4 = 495$개\n인접 꼭짓점 쌍을 포함하는 사각형: $495 - 105 = 390$개\n비율적으로 약 21%만 변을 공유하지 않으므로 합리적입니다. ✓\n\n**Step 5. 공식의 직관적 이해**\n12개 점을 원에 배치하고, 4개를 고르되 이웃하지 않게 고르는 것은 12칸 원형 배열에서 4칸을 비연속으로 택하는 것과 같습니다.\n\n**∴ 답: 105**\n\n**💡 포인트:** 원 위에서 인접하지 않게 선택하는 문제는 전용 공식 $\\frac{n}{n-k}\\binom{n-k}{k}$를 기억하세요.",
