    "explanation": "**[풀이]**\n\n**핵심 개념:** $X$에서 $Y$로의 함수는 $X$의 각 원소에 $Y$의 원소를 하나씩 대응시키는 것이므로, **중복순열** $|Y|^{|X|}$입니다.\n$$f: X \\to Y \\text{의 함수의 수} = |Y|^{|X|}$$\n\n**Step 1. 함수의 의미 이해**\n함수 $f: X \\to Y$에서 $X$의 각 원소는 $Y$의 원소 중 **정확히 하나**에 대응됩니다.\n같은 $Y$의 원소에 여러 $X$의 원소가 대응될 수 있습니다(중복 허용). 예를 들어 $f(1) = 2, f(2) = 2, f(3) = 2$도 하나의 유효한 함수입니다.\n\n**Step 2. 각 원소별 선택**\n$X$의 각 원소에 대해 $Y$의 원소를 독립적으로 선택합니다:\n- $f(1)$: $Y = \\{1, 2, 3, 4\\}$ 중 택 1 → **4가지**\n- $f(2)$: $Y = \\{1, 2, 3, 4\\}$ 중 택 1 → **4가지**\n- $f(3)$: $Y = \\{1, 2, 3, 4\\}$ 중 택 1 → **4가지**\n\n**Step 3. 곱의 법칙 적용**\n각 선택이 서로 독립이므로 경우의 수를 모두 곱합니다:\n$$4 \\times 4 \\times 4 = 4^3 = 64$$\n\n**Step 4. 참고 — 일대일 함수와의 차이**\n만약 일대일 함수(같은 값에 대응 불가)를 구한다면 $_4P_3 = 4 \\times 3 \\times 2 = 24$가지입니다. 이 문제는 일대일 조건이 없으므로 중복을 허용하여 $4^3 = 64$가 됩니다.\n\n**∴ 답: 64**\n\n**💡 포인트:** $X$에서 $Y$로의 함수의 수 = $|Y|^{|X|}$ (공역의 크기를 정의역의 크기만큼 거듭제곱)입니다.",
