    "explanation": "**[풀이]**\n\n**핵심 개념:** 서로 다른 주사위를 던지면 각 주사위의 결과를 구별하므로, **중복순열** $6^n$을 사용합니다.\n$$\\text{서로 다른 주사위 } n\\text{개의 경우의 수} = 6^n$$\n\n**Step 1. 각 주사위의 경우의 수**\n각 주사위에서 나올 수 있는 눈: $\\{1, 2, 3, 4, 5, 6\\}$ → **6가지**\n같은 눈이 여러 주사위에서 나올 수 있으므로 중복이 허용됩니다.\n\n**Step 2. 서로 다른 주사위이므로 구별**\n주사위 A, B, C는 서로 구별됩니다. 예를 들어 (A=1, B=2, C=3)과 (A=2, B=1, C=3)은 서로 다른 경우입니다.\n따라서 순서가 있는 **중복순열**에 해당합니다.\n\n**Step 3. 곱의 법칙 적용**\n주사위 A의 눈: 6가지, 주사위 B의 눈: 6가지, 주사위 C의 눈: 6가지\n각 선택이 독립이므로:\n$$6 \\times 6 \\times 6 = 6^3 = 216$$\n\n**Step 4. 참고 — 같은 주사위(구별 안 함)면?**\n만약 주사위를 구별하지 않는다면 중복조합 $_6H_3 = _8C_3 = 56$가지가 됩니다. 이 문제에서는 '서로 다른' 주사위이므로 구별하여 $6^3 = 216$이 맞습니다.\n\n**∴ 답: ④ 216**\n\n② 36은 주사위 2개일 때의 경우의 수($6^2$)이고, ① 18은 $6 \\times 3$으로 잘못 계산한 경우입니다.\n\n**💡 포인트:** '서로 다른' → 구별 → 중복순열 $m^n$, '같은 종류' → 구별 안 함 → 중복조합 $_mH_n$입니다.",
