    "explanation": "**[풀이]**\n\n**핵심 개념:** 양의 정수 조건($x \\geq 1$)은 치환을 통해 음이 아닌 정수 조건($x' \\geq 0$)으로 변환한 후 중복조합을 적용합니다.\n\n**Step 1. 양의 정수 조건 처리 (치환)**\n$x \\geq 1, y \\geq 1, z \\geq 1$이므로 각각에서 1을 빼는 치환을 합니다:\n$$x' = x - 1, \\quad y' = y - 1, \\quad z' = z - 1$$\n이제 $x', y', z' \\geq 0$ (음이 아닌 정수)입니다.\n\n**Step 2. 새로운 방정식 구하기**\n원래 방정식에 대입합니다:\n$$(x'+1) + (y'+1) + (z'+1) = 7$$\n$$x' + y' + z' = 4$$\n\n**Step 3. 중복조합 적용**\n3개의 음이 아닌 정수 변수의 합이 4인 해의 수:\n$$_3H_4 = _{3+4-1}C_4 = _6C_4 = _6C_2 = \\frac{6 \\times 5}{2} = 15$$\n\n**∴ 답: ② 15**\n\n④ 21은 치환 없이 $_3H_7 = _9C_2$을 계산한 경우로, 양의 정수 조건을 무시한 오답입니다.\n\n**💡 포인트:** $x \\geq 1$ → $x' = x - 1 \\geq 0$으로 치환하여 합을 줄인 후 중복조합을 적용하세요.",
