    "problem": "방정식 $x + y + z = 10$을 만족시키는 $1 \\leq x \\leq 4$, $y \\geq 2$, $z \\geq 3$인 정수 순서쌍 $(x, y, z)$의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 14,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 변수에 **상한과 하한**이 모두 있으면, 먼저 하한을 치환으로 제거하고 상한이 있는 변수는 **경우 분류**로 처리합니다.\n\n**Step 1. 하한 치환**\n$y \\geq 2$, $z \\geq 3$이므로 치환합니다:\n$$y' = y - 2 \\geq 0, \\quad z' = z - 3 \\geq 0$$\n원래 방정식에 대입: $x + (y'+2) + (z'+3) = 10$\n$$x + y' + z' = 5 \\quad (1 \\leq x \\leq 4, \\; y' \\geq 0, \\; z' \\geq 0)$$\n\n**Step 2. $x$값별 경우 분류**\n$x$에 상한이 있으므로 가능한 $x$값마다 $y' + z'$의 해의 수를 구합니다.\n$y' + z' = k$ ($y', z' \\geq 0$)의 해의 수는 $k + 1$개입니다.\n\n- $x = 1$: $y' + z' = 4$ → $4 + 1 = 5$가지\n- $x = 2$: $y' + z' = 3$ → $3 + 1 = 4$가지\n- $x = 3$: $y' + z' = 2$ → $2 + 1 = 3$가지\n- $x = 4$: $y' + z' = 1$ → $1 + 1 = 2$가지\n\n**Step 3. 합산**\n$$5 + 4 + 3 + 2 = 14$$\n\n**Step 4. 검증**\n$x = 5$이면 $y' + z' = 0$이지만 $x \\leq 4$ 조건에 위배되므로 포함하지 않습니다. ✓\n\n**∴ 답: 14**\n\n**💡 포인트:** 상한이 있는 변수는 가능한 값을 하나씩 대입하는 경우 분류가 가장 확실한 방법입니다.",
