    "explanation": "**[풀이]**\n\n**핵심 개념:** 모든 변수가 **짝수**라는 조건은 $x = 2a$로 치환하면 일반적인 중복조합 문제로 변환됩니다.\n$$_nH_r = _{n+r-1}C_r$$\n\n**Step 1. 짝수 조건 치환**\n모든 변수가 음이 아닌 짝수이므로 $x, y, z, w \\in \\{0, 2, 4, 6, \\ldots\\}$입니다. 각각을 2로 나누어 새 변수를 도입합니다:\n$$x = 2a, \\quad y = 2b, \\quad z = 2c, \\quad w = 2d$$\n여기서 $a, b, c, d \\geq 0$ (음이 아닌 정수)입니다.\n\n**Step 2. 새로운 방정식 유도**\n원래 방정식 $x + y + z + w = 12$에 대입합니다:\n$$2a + 2b + 2c + 2d = 12$$\n양변을 2로 나누면:\n$$a + b + c + d = 6$$\n\n**Step 3. 중복조합 적용**\n4개의 음이 아닌 정수 변수의 합이 6인 순서쌍의 수를 구합니다:\n$$_4H_6 = _{4+6-1}C_6 = _9C_6 = _9C_3$$\n\n**Step 4. 계산**\n$$_9C_3 = \\frac{9 \\times 8 \\times 7}{3 \\times 2 \\times 1} = \\frac{504}{6} = 84$$\n\n**Step 5. 검증 — 경계값 확인**\n가능한 순서쌍의 예: $(0, 0, 0, 12)$, $(2, 4, 6, 0)$, $(4, 4, 2, 2)$ 등이 모두 조건을 만족합니다. ✓\n\n**∴ 답: 84**\n\n**💡 포인트:** 짝수/홀수/배수 조건이 있으면 적절한 치환($x = 2a$ 등)으로 계수를 나눈 후, 기본 중복조합 문제로 변환하세요.",
