    "problem": "부등식 $x_1 + x_2 + x_3 + x_4 \\leq 15$를 만족시키는 음이 아닌 정수 순서쌍 $(x_1, x_2, x_3, x_4)$의 개수를 구하시오.",
    "answerType": "short",
