    "type": "중복순열·중복조합",
    "problem": "집합 $A = \\{1, 2, 3, 4, 5\\}$에서 집합 $B = \\{1, 2, 3, 4, 5\\}$로의 함수 $f$ 중에서 $f(1) \\leq f(2) \\leq f(3) \\leq f(4) \\leq f(5)$를 만족시키는 함수 $f$의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 126,
    "explanation": "**[풀이]**\n\n**핵심 개념:** $f(1) \\leq f(2) \\leq \\cdots \\leq f(n)$을 만족시키는 함수는 $B$에서 중복을 허용하여 $n$개를 **비내림차순**으로 선택하는 것과 같으며, 이는 **중복조합** $_mH_n$입니다.\n\n**Step 1. 핵심 통찰**\n조건 $f(1) \\leq f(2) \\leq f(3) \\leq f(4) \\leq f(5)$는 함숫값이 비내림차순이라는 뜻입니다.\n순서가 정해져 있으므로, 어떤 5개의 값을 선택하느냐만 결정하면 배열이 자동으로 결정됩니다.\n\n**Step 2. 중복조합으로 해석**\n$B = \\{1, 2, 3, 4, 5\\}$에서 중복을 허용하여 5개를 선택하면, 비내림차순으로 나열하는 방법은 정확히 1가지입니다.\n따라서 이 문제는 5종류에서 5개를 중복 허용하여 선택하는 **중복조합**입니다.\n\n**Step 3. 중복조합 공식 적용**\n$$_5H_5 = _{5+5-1}C_5 = _9C_5 = _9C_4$$\n\n**Step 4. 계산**\n$$_9C_4 = \\frac{9 \\times 8 \\times 7 \\times 6}{4 \\times 3 \\times 2 \\times 1} = \\frac{3024}{24} = 126$$\n\n**Step 5. 검증**\n예를 들어 $f(1)=f(2)=f(3)=f(4)=f(5)=3$도 조건을 만족하고, $f(1)=1, f(2)=2, f(3)=3, f(4)=4, f(5)=5$도 만족합니다. 126가지에 이런 다양한 경우가 모두 포함됩니다. ✓\n\n**∴ 답: 126**\n\n**💡 포인트:** 비내림차순 함수의 수 = 중복조합. $f(1) \\leq f(2) \\leq \\cdots$ → $_mH_n$ ($m$: 공역의 크기, $n$: 정의역의 크기)입니다.",
