    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항정리에서 $(a+b)^n$의 일반항은 다음과 같습니다:\n$$_nC_r \\cdot a^{n-r} \\cdot b^r \\quad (r = 0, 1, 2, \\ldots, n)$$\n\n**Step 1. 일반항 세우기**\n$(x+2)^5$에서 $a = x$, $b = 2$, $n = 5$로 놓으면 일반항은:\n$$_5C_r \\cdot x^{5-r} \\cdot 2^r$$\n\n**Step 2. $x^3$이 되는 $r$ 값 찾기**\n$x$의 지수가 3이 되려면 $5 - r = 3$이어야 합니다:\n$$5 - r = 3 \\quad \\Rightarrow \\quad r = 2$$\n$r = 2$는 $0 \\leq r \\leq 5$ 범위 안에 있으므로 유효합니다. ✓\n\n**Step 3. $_5C_2$ 계산**\n$$_5C_2 = \\frac{5!}{2! \\times 3!} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n**Step 4. $x^3$의 계수 계산**\n$r = 2$를 일반항에 대입합니다:\n$$_5C_2 \\cdot 2^2 = 10 \\times 4 = 40$$\n\n**Step 5. 검증 — 전개식의 일부 확인**\n$(x+2)^5$의 전개식에서 처음 몇 항을 확인합니다:\n$r=0$: $_5C_0 \\cdot x^5 \\cdot 2^0 = x^5$\n$r=1$: $_5C_1 \\cdot x^4 \\cdot 2^1 = 10x^4$\n$r=2$: $_5C_2 \\cdot x^3 \\cdot 2^2 = 40x^3$ ✓\n\n**∴ 답: 40**\n\n**💡 포인트:** 이항정리에서 특정 차수의 계수를 구하려면, 일반항에서 원하는 차수의 $r$값을 먼저 찾고, 이항계수와 상수의 거듭제곱을 곱합니다.",
