    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** $(1+x)^n$의 전개식에서 $x^r$의 계수는 $_nC_r$입니다.\n$$(1+x)^n = \\sum_{r=0}^{n} _nC_r \\cdot x^r = _nC_0 + _nC_1 x + _nC_2 x^2 + \\cdots + _nC_n x^n$$\n\n**Step 1. 일반항 확인**\n$(1+x)^n$에서 $a = 1$, $b = x$로 놓으면 일반항은:\n$$_nC_r \\cdot 1^{n-r} \\cdot x^r = _nC_r \\cdot x^r$$\n$1^{n-r} = 1$이므로 계수는 간단히 $_nC_r$이 됩니다.\n\n**Step 2. 조건 대입**\n$x^3$의 계수를 구해야 하므로 $n = 8$, $r = 3$입니다:\n$$_8C_3 = \\frac{8!}{3! \\times 5!} = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1}$$\n\n**Step 3. 분자와 분모 각각 계산**\n분자: $8 \\times 7 \\times 6 = 336$\n분모: $3 \\times 2 \\times 1 = 6$\n$$\\frac{336}{6} = 56$$\n\n**Step 4. 검증 — 파스칼 삼각형으로 확인**\n$n = 8$일 때 이항계수는: 1, 8, 28, **56**, 70, 56, 28, 8, 1\n$r = 3$에 해당하는 값이 56으로 일치합니다. ✓\n\n**∴ 답: ③ 56**\n\n① 28은 $_8C_2$(=$x^2$의 계수)이고, ④ 70은 $_8C_4$(=$x^4$의 계수)로, $r$ 값을 잘못 선택한 경우입니다.\n\n**💡 포인트:** $(1+x)^n$에서 $x^k$의 계수 = $_nC_k$. 이항정리의 가장 기본 형태이므로 반드시 기억하세요.",
