    "answer": 20,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 일반항에서 $x$의 지수를 정리한 후, 지수가 0이 되는 조건을 찾으면 상수항을 구할 수 있습니다.\n$$\\text{상수항} \\Leftrightarrow x\\text{의 지수} = 0$$\n\n**Step 1. 일반항 세우기**\n$a = x$, $b = \\frac{1}{x} = x^{-1}$, $n = 6$으로 놓고 이항정리를 적용합니다:\n$$_6C_r \\cdot x^{6-r} \\cdot (x^{-1})^r$$\n\n**Step 2. 지수법칙으로 $x$의 지수 정리**\n$$_6C_r \\cdot x^{6-r} \\cdot x^{-r} = _6C_r \\cdot x^{(6-r)+(-r)} = _6C_r \\cdot x^{6-2r}$$\n\n**Step 3. 상수항 조건 (지수 = 0)**\n상수항은 $x$의 지수가 0인 항이므로:\n$$6 - 2r = 0 \\quad \\Rightarrow \\quad 2r = 6 \\quad \\Rightarrow \\quad r = 3$$\n$r = 3$은 $0 \\leq r \\leq 6$ 범위 안에 있으므로 유효합니다. ✓\n\n**Step 4. 상수항 계산**\n$r = 3$을 대입합니다. $b = \\frac{1}{x}$에 상수 계수가 없으므로 이항계수만 남습니다:\n$$_6C_3 = \\frac{6 \\times 5 \\times 4}{3 \\times 2 \\times 1} = \\frac{120}{6} = 20$$\n\n**Step 5. 참고 — 다른 항의 지수 확인**\n$r = 0$이면 $x^6$, $r = 1$이면 $x^4$, $r = 2$이면 $x^2$, $r = 3$이면 $x^0$(상수), $r = 4$이면 $x^{-2}$, ...\n이처럼 지수가 2씩 줄어들며, 상수항은 $r = 3$일 때 유일하게 나타납니다.\n\n**∴ 답: 20**\n\n**💡 포인트:** $x$와 $\\frac{1}{x}$가 함께 있으면 일반항의 $x$ 지수를 하나의 식으로 정리한 후, 원하는 지수를 만드는 $r$을 찾습니다.",
