    "explanation": "**[풀이]**\n\n**핵심 개념:** $(a+b)^n$에서 $a = 2x$, $b = -1$로 놓으면 부호와 계수를 모두 포함한 일반항을 구할 수 있습니다.\n\n**Step 1. 일반항 세우기**\n$a = 2x$, $b = -1$, $n = 4$로 놓으면:\n$$_4C_r \\cdot (2x)^{4-r} \\cdot (-1)^r = _4C_r \\cdot 2^{4-r} \\cdot (-1)^r \\cdot x^{4-r}$$\n\n**Step 2. $x^2$ 조건**\n$x$의 지수가 2가 되려면:\n$$4 - r = 2 \\quad \\Rightarrow \\quad r = 2$$\n\n**Step 3. 계수 계산**\n$r = 2$를 대입합니다:\n$$_4C_2 \\cdot 2^{4-2} \\cdot (-1)^2 = 6 \\times 2^2 \\times 1 = 6 \\times 4 \\times 1 = 24$$\n\n$(-1)^2 = 1$이므로 부호는 양수입니다.\n\n**∴ 답: ③ 24**\n\n② 16은 $_4C_2 \\cdot 2^2$에서 $(-1)^r$ 부분을 빼먹거나 다른 계산 실수를, ④ 32는 $2^5 = 32$로 착각한 경우입니다.\n\n**💡 포인트:** $(ax + b)^n$ 형태에서는 $a$의 거듭제곱과 $(-1)^r$의 부호를 반드시 함께 고려하세요.",
