    "explanation": "**[풀이]**\n\n**핵심 개념:** $a = x^2$, $b = x^{-1}$로 놓으면 일반항의 $x$ 지수는 $2(n-r) + (-1)(r)$로 정리됩니다.\n\n**Step 1. 일반항 세우기**\n$a = x^2$, $b = \\frac{1}{x} = x^{-1}$, $n = 6$으로 놓으면:\n$$_6C_r \\cdot (x^2)^{6-r} \\cdot (x^{-1})^r = _6C_r \\cdot x^{2(6-r)} \\cdot x^{-r}$$\n\n**Step 2. $x$의 지수 정리**\n$$x^{2(6-r) + (-r)} = x^{12-2r-r} = x^{12-3r}$$\n\n**Step 3. $x^3$ 조건**\n$$12 - 3r = 3 \\quad \\Rightarrow \\quad 3r = 9 \\quad \\Rightarrow \\quad r = 3$$\n\n$r = 3$은 $0 \\leq r \\leq 6$ 범위 안에 있으므로 유효합니다. ✓\n\n**Step 4. 계수 계산**\n$$_6C_3 = \\frac{6 \\times 5 \\times 4}{3 \\times 2 \\times 1} = 20$$\n\n**∴ 답: ④ 20**\n\n③ 15는 $_6C_2 = 15$로 $r$을 잘못 구한 경우이고, ① 6은 $_6C_1$입니다.\n\n**💡 포인트:** $x^a$와 $x^b$가 결합된 이항식에서는 일반항의 지수를 하나의 $r$에 대한 식으로 정리하는 것이 핵심입니다.",
