    "explanation": "**[풀이]**\n\n**핵심 개념:** $(1+x)^n$에서 $x^k$의 계수는 $_nC_k$이고, 이웃한 이항계수의 비는 $\\frac{_nC_{k+1}}{_nC_k} = \\frac{n-k}{k+1}$입니다.\n\n**Step 1. $x^4$의 계수 구하기**\n$$_{10}C_4 = \\frac{10 \\times 9 \\times 8 \\times 7}{4 \\times 3 \\times 2 \\times 1} = \\frac{5040}{24} = 210$$\n\n**Step 2. $x^5$의 계수 구하기**\n$$_{10}C_5 = \\frac{10 \\times 9 \\times 8 \\times 7 \\times 6}{5 \\times 4 \\times 3 \\times 2 \\times 1} = \\frac{30240}{120} = 252$$\n\n**Step 3. 비를 가장 간단한 정수비로 나타내기**\n$$210 : 252$$\n최대공약수를 구합니다: $\\gcd(210, 252)$\n$210 = 2 \\times 3 \\times 5 \\times 7$, $252 = 2^2 \\times 3^2 \\times 7$\n$\\gcd = 2 \\times 3 \\times 7 = 42$\n$$\\frac{210}{42} : \\frac{252}{42} = 5 : 6$$\n\n**Step 4. 최종 답 계산**\n$$a + b = 5 + 6 = 11$$\n\n**∴ 답: 11**\n\n**💡 포인트:** 이웃한 이항계수의 비 $\\frac{_nC_{k+1}}{_nC_k} = \\frac{n-k}{k+1}$을 사용하면 빠르게 풀 수 있습니다. 여기서는 $\\frac{10-4}{4+1} = \\frac{6}{5}$이므로 비는 $5:6$입니다.",
