    "answerType": "short",
    "choices": null,
    "answer": 266,
    "explanation": "**[풀이]**\n\n**핵심 개념:** $(1 + x + x^2)^n$처럼 항이 3개인 다항식의 거듭제곱은 **다항계수(Multinomial Coefficient)** $\\frac{n!}{a!b!c!}$를 사용합니다.\n\n**Step 1. 문제 해석**\n$(1 + x + x^2)^8$에서 8개의 인수 각각으로부터 $1$, $x$, $x^2$ 중 하나를 선택하여 곱합니다.\n$x$의 지수의 합이 4가 되는 경우를 모두 찾아야 합니다.\n\n**Step 2. 조건 방정식 세우기**\n8개 인수 중 $1$(=$x^0$)을 $a$개, $x$(=$x^1$)를 $b$개, $x^2$를 $c$개 선택한다고 하면:\n- 인수의 수: $a + b + c = 8$\n- $x$의 지수 합: $0 \\cdot a + 1 \\cdot b + 2 \\cdot c = b + 2c = 4$\n\n**Step 3. 가능한 $(a, b, c)$ 찾기**\n$b + 2c = 4$와 $a = 8 - b - c$를 만족시키는 음이 아닌 정수해:\n- $c = 0$: $b = 4, a = 4$ → $(4, 4, 0)$\n- $c = 1$: $b = 2, a = 5$ → $(5, 2, 1)$\n- $c = 2$: $b = 0, a = 6$ → $(6, 0, 2)$\n\n**Step 4. 각 경우의 다항계수 계산**\n- $(4, 4, 0)$: $\\frac{8!}{4! \\cdot 4! \\cdot 0!} = \\frac{40320}{24 \\times 24 \\times 1} = 70$\n- $(5, 2, 1)$: $\\frac{8!}{5! \\cdot 2! \\cdot 1!} = \\frac{40320}{120 \\times 2 \\times 1} = 168$\n- $(6, 0, 2)$: $\\frac{8!}{6! \\cdot 0! \\cdot 2!} = \\frac{40320}{720 \\times 1 \\times 2} = 28$\n\n**Step 5. 합산**\n$$70 + 168 + 28 = 266$$\n\n**∴ 답: 266**\n\n**💡 포인트:** 항이 3개 이상인 다항식의 거듭제곱에서 특정 차수의 계수를 구할 때는 다항계수 $\\frac{n!}{a!b!c!}$을 사용합니다.",
