    "answer": 11,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이웃한 이항계수의 비 공식: $\\frac{_nC_{k+1}}{_nC_k} = \\frac{n-k}{k+1}$\n\n**Step 1. 계수를 이항계수로 표현**\n$(1+x)^n$에서:\n- $x^2$의 계수: $_nC_2$\n- $x^3$의 계수: $_nC_3$\n\n**Step 2. 조건 방정식 세우기**\n'$x^3$의 계수가 $x^2$의 계수의 3배'이므로:\n$$_nC_3 = 3 \\cdot _nC_2$$\n\n**Step 3. 이항계수의 비 공식 적용**\n$$\\frac{_nC_3}{_nC_2} = \\frac{n-2}{3} = 3$$\n\n이 비 공식은 $_nC_{k+1} = _nC_k \\times \\frac{n-k}{k+1}$에서 나옵니다.\n\n**Step 4. $n$ 구하기**\n$$n - 2 = 9 \\quad \\Rightarrow \\quad n = 11$$\n\n**Step 5. 검증**\n$_{11}C_2 = \\frac{11 \\times 10}{2} = 55$\n$_{11}C_3 = \\frac{11 \\times 10 \\times 9}{6} = 165$\n$165 = 3 \\times 55$ ✓\n\n**∴ 답: 11**\n\n**💡 포인트:** 이항계수 사이의 관계를 묻는 문제에서는 비 공식 $\\frac{_nC_{r+1}}{_nC_r} = \\frac{n-r}{r+1}$을 활용하면 빠르게 풀 수 있습니다.",
