    "answer": 3,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 확률의 기본 공식 (수학적 확률):\n$$P(A) = \\frac{n(A)}{n(S)} = \\frac{\\text{사건 A에 해당하는 경우의 수}}{\\text{전체 경우의 수}}$$\n\n**Step 1. 표본공간 정의**\n주사위 하나를 던질 때 나올 수 있는 모든 경우를 표본공간이라 합니다.\n$$S = \\{1, 2, 3, 4, 5, 6\\}, \\quad n(S) = 6$$\n\n**Step 2. 사건 정의 — '3 이상'의 범위**\n'3 이상'은 3을 **포함**합니다. 따라서:\n$$A = \\{3, 4, 5, 6\\}, \\quad n(A) = 4$$\n주의: '3 초과'라면 $\\{4, 5, 6\\}$으로 3개가 됩니다.\n\n**Step 3. 확률 계산**\n$$P(A) = \\frac{n(A)}{n(S)} = \\frac{4}{6}$$\n\n**Step 4. 약분하여 기약분수로 만들기**\n$\\gcd(4, 6) = 2$이므로 분자와 분모를 2로 나눕니다:\n$$\\frac{4}{6} = \\frac{2}{3}$$\n\n**∴ 답: ④ $\\frac{2}{3}$**\n\n③ $\\frac{1}{2}$은 '3 이상'을 $\\{3, 4, 5\\}$로 잘못 세어 $\\frac{3}{6}$을 구한 경우이고, ⑤ $\\frac{5}{6}$은 '3 미만이 아닌 것'을 잘못 계산한 경우입니다.\n\n**💡 포인트:** '이상/이하'는 해당 수를 포함하고, '초과/미만'은 해당 수를 포함하지 않습니다. 범위를 정확히 파악하는 것이 확률 계산의 첫걸음입니다.",
