    "explanation": "**[풀이]**\n\n**핵심 개념:** '또는'이 있으면 **확률의 덧셈정리**: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n\n**Step 1. 각 사건의 원소 나열**\n- $A$(3의 배수): $\\{3, 6, 9, 12, 15, 18\\}$ → $n(A) = 6$\n- $B$(5의 배수): $\\{5, 10, 15, 20\\}$ → $n(B) = 4$\n- $A \\cap B$(3과 5의 공배수 = 15의 배수): $\\{15\\}$ → $n(A \\cap B) = 1$\n\n**Step 2. 덧셈정리 적용**\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n$$= \\frac{6}{20} + \\frac{4}{20} - \\frac{1}{20}$$\n\n**Step 3. 계산**\n$$= \\frac{6 + 4 - 1}{20} = \\frac{9}{20}$$\n\n$P(A \\cap B)$를 빼주는 이유는 15가 3의 배수이면서 동시에 5의 배수이므로 두 번 세어졌기 때문입니다.\n\n**∴ 답: ④ $\\frac{9}{20}$**\n\n⑤ $\\frac{1}{2}$은 $P(A \\cap B)$를 빼지 않고 $\\frac{10}{20}$으로 계산한 경우입니다.\n\n**💡 포인트:** 'A 또는 B' → 덧셈정리. 반드시 $P(A \\cap B)$를 빼서 중복을 제거하세요.",
