    "problem": "주머니에 흰 공 4개, 검은 공 3개가 들어 있다. 2개의 공을 동시에 꺼낼 때, 2개 모두 흰 공일 확률을 구하시오. (기약분수의 분자와 분모의 합을 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[풀이]**\n\n**핵심 개념:** '동시에 꺼내는' 경우의 수는 조합 $_nC_r$로 구하고, 확률은 다음과 같이 계산합니다.\n$$P = \\frac{\\text{유리한 경우의 수}}{\\text{전체 경우의 수}} = \\frac{_4C_2}{_7C_2}$$\n\n**Step 1. 전체 경우의 수**\n주머니에 흰 공 4개, 검은 공 3개로 총 7개의 공이 있습니다.\n7개에서 2개를 동시에 꺼내는 경우의 수:\n$$_7C_2 = \\frac{7 \\times 6}{2 \\times 1} = \\frac{42}{2} = 21$$\n\n**Step 2. 유리한 경우의 수 (2개 모두 흰 공)**\n흰 공 4개에서 2개를 선택하는 경우의 수:\n$$_4C_2 = \\frac{4 \\times 3}{2 \\times 1} = \\frac{12}{2} = 6$$\n\n**Step 3. 확률 계산**\n$$P = \\frac{_4C_2}{_7C_2} = \\frac{6}{21}$$\n\n**Step 4. 기약분수로 약분**\n$\\gcd(6, 21) = 3$이므로 분자, 분모를 3으로 나누어 약분합니다:\n$$\\frac{6}{21} = \\frac{6 \\div 3}{21 \\div 3} = \\frac{2}{7}$$\n\n**Step 5. 분자 + 분모 구하기**\n기약분수 $\\frac{2}{7}$에서:\n$$\\text{분자} + \\text{분모} = 2 + 7 = 9$$\n\n**∴ 답: 9**\n\n**💡 포인트:** '동시에 꺼내기' = 순서 없는 선택 = 조합. 확률을 구한 후 반드시 약분하여 기약분수로 만드세요. 분자+분모를 묻는 문제에서는 약분 실수에 특히 주의합니다.",
