    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건부 확률 공식\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n**Step 1. 조건부 확률 공식 확인하기**\n\"A가 일어났을 때 B가 일어날 확률\"은 $P(B|A)$이며, A와 B가 동시에 일어날 확률을 A가 일어날 확률로 나누면 됩니다.\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n**Step 2. 주어진 값 대입하기**\n$P(A) = \\frac{1}{2}$, $P(A \\cap B) = \\frac{1}{5}$를 대입합니다.\n$$P(B|A) = \\frac{\\frac{1}{5}}{\\frac{1}{2}}$$\n\n**Step 3. 분수의 나눗셈 계산하기**\n분수의 나눗셈은 뒤의 분수를 뒤집어서 곱합니다.\n$$P(B|A) = \\frac{1}{5} \\times \\frac{2}{1} = \\frac{2}{5}$$\n\n**∴ 답: ③ $\\frac{2}{5}$**\n\n① $\\frac{1}{5}$는 $P(A \\cap B)$를 그대로 쓴 경우이고, ④ $\\frac{1}{2}$는 $P(A)$를 그대로 쓴 경우입니다.\n\n**💡 포인트:** 조건부 확률은 \"교집합 ÷ 조건 사건의 확률\"로 구합니다.",
