    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립사건의 교집합과 합사건 공식\n$$P(A \\cap B) = P(A) \\cdot P(B), \\quad P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n**Step 1. 독립사건의 교집합 확률 구하기**\nA와 B가 독립이면, 두 사건이 동시에 일어날 확률은 각각의 확률을 곱하면 됩니다.\n$$P(A \\cap B) = P(A) \\cdot P(B) = \\frac{1}{3} \\times \\frac{1}{4} = \\frac{1}{12}$$\n\n**Step 2. 합사건의 확률 구하기 (덧셈정리)**\nA 또는 B가 일어날 확률은 덧셈정리를 사용합니다. 겹치는 부분을 한 번 빼줍니다.\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n**Step 3. 통분하여 계산하기**\n분모를 12로 통분합니다.\n$$P(A \\cup B) = \\frac{1}{3} + \\frac{1}{4} - \\frac{1}{12} = \\frac{4}{12} + \\frac{3}{12} - \\frac{1}{12} = \\frac{6}{12} = \\frac{1}{2}$$\n\n**∴ 답: ③ $\\frac{1}{2}$**\n\n④ $\\frac{7}{12}$은 $P(A) + P(B)$만 더하고 $P(A \\cap B)$를 빼지 않은 경우입니다.\n\n**💡 포인트:** 독립이면 $P(A \\cap B) = P(A) \\cdot P(B)$, 이것을 덧셈정리에 대입하세요.",
