    "type": "조건부 확률",
    "problem": "두 사건 A, B에 대하여 $P(A) = \\frac{2}{5}$, $P(B|A) = \\frac{1}{3}$, $P(B|A^c) = \\frac{2}{3}$일 때, $P(B)$의 값을 구하시오. (기약분수의 분자를 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 8,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 전확률 공식 (Law of Total Probability)\n$$P(B) = P(B|A) \\cdot P(A) + P(B|A^c) \\cdot P(A^c)$$\n\n**Step 1. 여사건의 확률 구하기**\nA가 일어나지 않을 확률 $P(A^c)$를 먼저 구합니다.\n$$P(A^c) = 1 - P(A) = 1 - \\frac{2}{5} = \\frac{3}{5}$$\n\n**Step 2. 전확률 공식 적용하기**\nB가 일어나는 경우를 \"A를 경유하는 경우\"와 \"A가 아닌 것을 경유하는 경우\"로 나눕니다.\n$$P(B) = P(B|A) \\cdot P(A) + P(B|A^c) \\cdot P(A^c)$$\n\n**Step 3. 각 항 계산하기**\n첫째 항: A가 일어나고 그 안에서 B가 일어나는 확률\n$$P(B|A) \\cdot P(A) = \\frac{1}{3} \\times \\frac{2}{5} = \\frac{2}{15}$$\n둘째 항: A가 일어나지 않고 그 안에서 B가 일어나는 확률\n$$P(B|A^c) \\cdot P(A^c) = \\frac{2}{3} \\times \\frac{3}{5} = \\frac{6}{15}$$\n\n**Step 4. 합산하여 최종 답 구하기**\n$$P(B) = \\frac{2}{15} + \\frac{6}{15} = \\frac{8}{15}$$\n분자는 $8$입니다.\n\n**∴ 답: 8**\n\n**💡 포인트:** 전확률 공식은 \"경우를 나눠서 합산\"하는 기법입니다. 나무그림(tree diagram)을 그리면 직관적으로 이해할 수 있습니다.",
