    "_type": "cond_prob",
    "type": "조건부 확률",
    "problem": "어느 공장에서 A 기계는 전체 제품의 60%, B 기계는 40%를 생산한다. A 기계의 불량률은 3%, B 기계의 불량률은 5%이다. 임의로 선택한 제품이 불량품일 때, 그것이 A 기계에서 생산되었을 확률을 구하시오. (기약분수의 분자를 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 베이즈 정리 (Bayes' Theorem)\n$$P(A|D) = \\frac{P(D|A) \\cdot P(A)}{P(D)}$$\n\n**Step 1. 주어진 정보 정리하기**\n- $P(A) = 0.6$ (A 기계 생산 비율 60%)\n- $P(B) = 0.4$ (B 기계 생산 비율 40%)\n- $P(D|A) = 0.03$ (A 기계의 불량률 3%)\n- $P(D|B) = 0.05$ (B 기계의 불량률 5%)\n\n**Step 2. 전체 불량률 $P(D)$ 구하기 (전확률 공식)**\n불량품이 나오는 경로를 모두 합산합니다.\n$$P(D) = P(D|A) \\cdot P(A) + P(D|B) \\cdot P(B)$$\n$$= 0.03 \\times 0.6 + 0.05 \\times 0.4 = 0.018 + 0.020 = 0.038$$\n\n**Step 3. 베이즈 정리로 역확률 구하기**\n\"불량품인데 A에서 나왔을 확률\"을 구합니다.\n$$P(A|D) = \\frac{P(D|A) \\cdot P(A)}{P(D)} = \\frac{0.018}{0.038}$$\n\n**Step 4. 분수 정리하기**\n분자와 분모에 1000을 곱하면\n$$P(A|D) = \\frac{18}{38} = \\frac{9}{19}$$\n분자는 $9$입니다.\n\n**∴ 답: 9**\n\n**💡 포인트:** 베이즈 정리는 \"원인의 확률\"을 구하는 도구입니다. 결과(불량)를 보고 원인(어느 기계?)을 역추적하세요.",
