    "explanation": "**[풀이]**\n\n**핵심 개념:** 확률분포의 기본 성질 — 모든 확률의 합은 1입니다.\n$$\\sum_{\\text{모든 } x} P(X = x) = 1$$\n\n**Step 1. 확률분포표 확인하기**\n주어진 확률분포표를 정리하면 다음과 같습니다.\n| $X$ | 1 | 2 | 3 | 4 |\n| $P$ | $\\frac{1}{6}$ | $a$ | $\\frac{1}{3}$ | $\\frac{1}{4}$ |\n모든 확률값은 0 이상이어야 하고, 합이 정확히 1이어야 합니다.\n\n**Step 2. 확률의 합 = 1 조건으로 방정식 세우기**\n확률분포표에서 모든 확률을 더하면 반드시 1이 되어야 합니다.\n$$\\frac{1}{6} + a + \\frac{1}{3} + \\frac{1}{4} = 1$$\n\n**Step 3. 통분하여 알려진 확률들의 합 구하기**\n$\\frac{1}{6}$, $\\frac{1}{3}$, $\\frac{1}{4}$의 분모의 최소공배수는 12입니다.\n$$\\frac{1}{6} = \\frac{2}{12}, \\quad \\frac{1}{3} = \\frac{4}{12}, \\quad \\frac{1}{4} = \\frac{3}{12}$$\n알려진 확률의 합:\n$$\\frac{2}{12} + \\frac{4}{12} + \\frac{3}{12} = \\frac{9}{12} = \\frac{3}{4}$$\n\n**Step 4. $a$ 값 구하기**\n$$a = 1 - \\frac{3}{4} = \\frac{4}{4} - \\frac{3}{4} = \\frac{1}{4}$$\n\n검증: $\\frac{1}{6} + \\frac{1}{4} + \\frac{1}{3} + \\frac{1}{4} = \\frac{2+3+4+3}{12} = \\frac{12}{12} = 1$ $\\checkmark$\n\n**∴ 답: ③ $\\frac{1}{4}$**\n\n① $\\frac{1}{12}$은 통분 과정에서 분자를 잘못 계산한 경우입니다. ② $\\frac{1}{6}$은 $P(X=1)$과 같은 값으로, 통분 후 뺄셈을 잘못한 결과입니다.\n\n**💡 포인트:** 확률분포에서 미지수가 있으면 \"확률의 총합 = 1\"을 방정식으로 세워 풀면 됩니다. 통분할 때 최소공배수를 정확히 구하는 것이 중요합니다.",
