    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 평균과 분산 공식\n$X \\sim B(n, p) \\Rightarrow E(X) = np, \\quad V(X) = np(1-p)$\n\n**Step 1. 이항분포의 모수 확인하기**\n$X \\sim B(100, \\frac{1}{5})$이므로 시행 횟수 $n = 100$, 성공 확률 $p = \\frac{1}{5}$입니다. 이항분포는 독립인 베르누이 시행을 $n$번 반복할 때 성공 횟수의 분포입니다.\n\n**Step 2. 먼저 평균(기댓값) 구하기**\n$E(X) = np = 100 \\times \\frac{1}{5} = 20$\n이는 100번 중 평균적으로 20번 성공한다는 뜻입니다.\n\n**Step 3. 실패 확률 $(1-p)$ 계산하기**\n$q = 1 - p = 1 - \\frac{1}{5} = \\frac{4}{5}$\n\n**Step 4. 분산 공식에 대입하여 계산하기**\n분산은 평균에 실패 확률 $(1-p)$를 한 번 더 곱한 것입니다.\n$V(X) = np(1-p) = npq = 100 \\times \\frac{1}{5} \\times \\frac{4}{5}$\n단계별로 계산하면:\n$= 100 \\times \\frac{4}{25} = \\frac{400}{25} = 16$\n\n참고로 표준편차는 $\\sigma(X) = \\sqrt{V(X)} = \\sqrt{16} = 4$입니다.\n\n**∴ 답: ④ 16**\n\n⑤ 20은 $np = 100 \\times \\frac{1}{5}$, 즉 평균 $E(X)$를 구한 것입니다. 분산을 구할 때는 반드시 $(1-p)$를 한 번 더 곱해야 합니다. ③ 12는 $n$이나 $p$ 값을 잘못 대입한 경우입니다.\n\n**💡 포인트:** 이항분포에서 $V(X) = np(1-p)$이므로, 분산은 항상 평균 $np$보다 작습니다 ($0 < 1-p < 1$이므로). 이 관계를 이용하면 답의 범위를 빠르게 좁힐 수 있습니다.",
