    "problem": "확률변수 $X$에 대하여 $E(X) = 3$, $V(X) = 2$일 때, $E(3X + 5)$와 $V(3X + 5)$의 값의 합을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 32,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 기댓값과 분산의 선형 변환 성질\n$E(aX + b) = aE(X) + b, \\quad V(aX + b) = a^2 V(X)$\n\n**Step 1. 주어진 정보 정리하기**\n확률변수 $X$에 대해 $E(X) = 3$, $V(X) = 2$가 주어져 있습니다. 이 값들을 이용하여 $Y = 3X + 5$의 기댓값과 분산을 각각 구해야 합니다.\n\n**Step 2. $E(3X+5)$ 구하기 — 기댓값의 선형성**\n기댓값에서는 상수배는 그대로 곱해지고, 상수 덧셈도 그대로 더해집니다.\n$E(3X + 5) = 3 \\cdot E(X) + 5 = 3 \\times 3 + 5 = 9 + 5 = 14$\n\n**Step 3. $V(3X+5)$ 구하기 — 분산의 변환 성질**\n분산에서는 상수 덧셈($+5$)은 영향을 주지 않습니다. 데이터 전체에 같은 수를 더해도 흩어진 정도는 변하지 않기 때문입니다. 반면 상수배($\\times 3$)는 제곱이 됩니다.\n$V(3X + 5) = 3^2 \\cdot V(X) = 9 \\times 2 = 18$\n\n**Step 4. 최종 합 구하기**\n$E(3X+5) + V(3X+5) = 14 + 18 = 32$\n\n**∴ 답: 32**\n\n참고: 만약 $V(3X+5) = 3 \\times V(X) = 6$으로 잘못 계산하면 답이 $14 + 6 = 20$이 됩니다. 분산에서 상수배는 반드시 **제곱**해야 합니다!\n\n**💡 포인트:** 기댓값은 $E(aX+b) = aE(X)+b$, 분산은 $V(aX+b) = a^2 V(X)$입니다. 분산에는 $b$가 사라지고 $a$는 제곱됩니다. 이 차이를 정확히 기억하세요.",
