    "answer": 9,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 평균·분산과 모수 역추적\n$$E(X) = np, \\quad V(X) = np(1-p), \\quad \\frac{V(X)}{E(X)} = 1-p$$\n\n**Step 1. 분산을 평균으로 나누어 $(1-p)$ 구하기**\n이항분포에서 $\\frac{V(X)}{E(X)} = \\frac{np(1-p)}{np} = 1-p$라는 유용한 관계가 있습니다.\n$$1 - p = \\frac{V(X)}{E(X)} = \\frac{2}{6} = \\frac{1}{3}$$\n\n**Step 2. $p$ 값 구하기**\n$$p = 1 - \\frac{1}{3} = \\frac{2}{3}$$\n\n**Step 3. $n$ 값 구하기**\n$E(X) = np = 6$에 $p = \\frac{2}{3}$를 대입합니다.\n$$n \\cdot \\frac{2}{3} = 6 \\quad \\Rightarrow \\quad n = 6 \\times \\frac{3}{2} = 9$$\n\n**Step 4. 검증하기**\n$n=9$, $p=\\frac{2}{3}$일 때:\n$$E(X) = 9 \\times \\frac{2}{3} = 6 \\checkmark, \\quad V(X) = 9 \\times \\frac{2}{3} \\times \\frac{1}{3} = 2 \\checkmark$$\n\n**∴ 답: 9**\n\n**💡 포인트:** $\\frac{V(X)}{E(X)} = 1-p$를 이용하면 $p$를 바로 구할 수 있습니다. 이항분포 역추적의 핵심 기법입니다.",
