    "type": "이산확률분포",
    "problem": "주머니에 1이 적힌 공 1개, 2가 적힌 공 2개, 3이 적힌 공 1개가 있다. 이 주머니에서 2개의 공을 동시에 꺼내어 꺼낸 공에 적힌 수의 합을 확률변수 $X$라 할 때, $E(X)$의 값을 구하시오. (답을 6배 하여 정수로 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 24,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이산확률변수의 기댓값\n$$E(X) = \\sum x_i \\cdot P(X = x_i)$$\n\n**Step 1. 공을 구별하여 모든 경우 나열하기**\n공 4개를 구별합니다: $1$, $2_a$, $2_b$, $3$. 2개를 꺼내는 경우의 수:\n$$\\binom{4}{2} = 6$$\n\n**Step 2. 각 경우의 합 계산하기**\n- $\\{1, 2_a\\}$ → 합 $= 3$\n- $\\{1, 2_b\\}$ → 합 $= 3$\n- $\\{1, 3\\}$ → 합 $= 4$\n- $\\{2_a, 2_b\\}$ → 합 $= 4$\n- $\\{2_a, 3\\}$ → 합 $= 5$\n- $\\{2_b, 3\\}$ → 합 $= 5$\n\n**Step 3. 확률분포표 작성하기**\n| $X$ | 3 | 4 | 5 |\n|-----|---|---|---|\n| $P$ | $\\frac{2}{6}$ | $\\frac{2}{6}$ | $\\frac{2}{6}$ |\n\n**Step 4. 기댓값 계산하기**\n$$E(X) = 3 \\times \\frac{2}{6} + 4 \\times \\frac{2}{6} + 5 \\times \\frac{2}{6} = \\frac{6 + 8 + 10}{6} = \\frac{24}{6} = 4$$\n\n**Step 5. 최종 답 구하기**\n$$4 \\times 6 = 24$$\n\n**∴ 답: 24**\n\n**💡 포인트:** 같은 숫자의 공이 여러 개일 때는 공을 구별하여 세야 동등한 확률로 셀 수 있습니다.",
