    "answer": 1,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 확률의 총합으로 미지상수 결정 후 확률 계산\n$$\\sum_{k=1}^{4} P(X=k) = 1$$\n\n**Step 1. 각 확률값 나열하기**\n$P(X=k) = c \\cdot k^2$이므로:\n- $P(X=1) = c \\cdot 1 = c$\n- $P(X=2) = c \\cdot 4 = 4c$\n- $P(X=3) = c \\cdot 9 = 9c$\n- $P(X=4) = c \\cdot 16 = 16c$\n\n**Step 2. 확률의 합 = 1로 $c$ 구하기**\n$$c + 4c + 9c + 16c = 30c = 1$$\n$$c = \\frac{1}{30}$$\n\n**Step 3. 각 확률값 확정하기**\n$$P(X=1) = \\frac{1}{30}, \\quad P(X=2) = \\frac{4}{30}, \\quad P(X=3) = \\frac{9}{30}, \\quad P(X=4) = \\frac{16}{30}$$\n\n**Step 4. $P(X \\geq 3)$ 계산하기**\n$$P(X \\geq 3) = P(X=3) + P(X=4) = \\frac{9}{30} + \\frac{16}{30} = \\frac{25}{30} = \\frac{5}{6}$$\n\n**Step 5. 검증하기**\n모든 확률의 합: $\\frac{1+4+9+16}{30} = \\frac{30}{30} = 1$ $\\checkmark$\n\n**∴ 답: ② $\\frac{5}{6}$**\n\n① $\\frac{1}{6}$은 $P(X \\leq 2) = \\frac{5}{30} = \\frac{1}{6}$으로 여사건을 구한 값입니다.\n\n**💡 포인트:** 확률질량함수에 미지상수가 있으면, $\\sum P = 1$로 먼저 상수를 결정하세요.",
