    "explanation": "**[풀이]**\n\n**핵심 개념:** 정규분포의 표준화 공식\n$$Z = \\frac{X - \\mu}{\\sigma}$$\n\n**Step 1. 표준화하기**\n$X \\sim N(50, 5^2)$이므로 $\\mu = 50$, $\\sigma = 5$입니다. $X = 55$를 표준화합니다.\n$$P(X \\geq 55) = P\\left(Z \\geq \\frac{55 - 50}{5}\\right) = P(Z \\geq 1)$$\n\n**Step 2. 표준정규분포의 대칭성 이용하기**\n$P(Z \\geq 1)$은 $Z \\geq 0$ 영역에서 $0 \\leq Z \\leq 1$ 부분을 빼면 됩니다.\n$$P(Z \\geq 1) = P(Z \\geq 0) - P(0 \\leq Z \\leq 1)$$\n\n**Step 3. 계산하기**\n표준정규분포에서 $P(Z \\geq 0) = 0.5$ (대칭성)이므로:\n$$P(Z \\geq 1) = 0.5 - 0.3413 = 0.1587$$\n\n**∴ 답: ③ 0.1587**\n\n⑤ 0.3413은 $P(0 \\leq Z \\leq 1)$을 그대로 답한 경우입니다.\n\n**💡 포인트:** $P(Z \\geq a) = 0.5 - P(0 \\leq Z \\leq a)$. 표준화 후 표에서 값을 찾아 0.5에서 빼세요.",
