    "explanation": "**[풀이]**\n\n**핵심 개념:** 정규분포의 대칭성\n정규분포 $N(m, \\sigma^2)$의 확률밀도함수는 평균 $m$을 중심으로 좌우 대칭입니다.\n$P(X \\leq m-a) = P(X \\geq m+a)$\n\n**Step 1. 문제 조건 분석하기**\n$P(X \\leq 14) = P(X \\geq 26)$이라는 조건이 주어져 있습니다. 이는 $X = 14$와 $X = 26$ 지점에서의 꼬리 확률이 같다는 의미입니다.\n\n**Step 2. 정규분포의 대칭 성질 적용하기**\n정규분포는 평균 $m$을 중심으로 좌우 대칭이므로, 같은 꼬리 확률을 가지려면 14와 26이 평균 $m$으로부터 같은 거리에 있어야 합니다. 즉, $m - 14 = 26 - m$이어야 합니다.\n\n**Step 3. 평균 $m$ 구하기**\n$m - 14 = 26 - m$에서:\n$2m = 14 + 26 = 40$\n$m = 20$\n또는 두 값의 중점으로 바로 구할 수 있습니다:\n$m = \\frac{14 + 26}{2} = \\frac{40}{2} = 20$\n\n**Step 4. 검증하기**\n$m = 20$이면 $14 = 20 - 6$, $26 = 20 + 6$으로 평균에서 양쪽으로 $6$만큼 떨어져 있어 대칭 조건을 만족합니다. $\\checkmark$\n\n**∴ 답: ③ 20**\n\n② 18은 14에서 4를 더한 값으로, 대칭점이 아닌 잘못된 계산입니다. ④ 22는 26에서 4를 뺀 값으로, 역시 대칭 구조를 무시한 오답입니다.\n\n**💡 포인트:** 정규분포에서 $P(X \\leq a) = P(X \\geq b)$이면 평균 $m = \\frac{a+b}{2}$입니다. 이 성질은 정규분포 문제에서 자주 활용되므로 반드시 기억하세요.",
