    "explanation": "**[풀이]**\n\n**핵심 개념:** 정규분포 표준화 → 확률 → 인원 수 환산\n$\\text{인원 수} = \\text{전체 인원} \\times P(X \\geq a)$\n\n**Step 1. 주어진 정보 정리하기**\n수학 성적이 정규분포 $N(60, 15^2)$을 따르므로, 평균 $\\mu = 60$점, 표준편차 $\\sigma = 15$점입니다. 전체 학생 수는 500명입니다.\n\n**Step 2. 표준화하기**\n75점을 표준정규분포의 $Z$값으로 변환합니다.\n$Z = \\frac{X - \\mu}{\\sigma} = \\frac{75 - 60}{15} = \\frac{15}{15} = 1$\n따라서 $P(X \\geq 75) = P(Z \\geq 1)$입니다.\n\n**Step 3. 표준정규분포표를 이용하여 확률 계산하기**\n표준정규분포의 대칭성에 의해 $P(Z \\geq 0) = 0.5$이고,\n$P(0 \\leq Z \\leq 1) = 0.3413$이 주어져 있으므로:\n$P(Z \\geq 1) = P(Z \\geq 0) - P(0 \\leq Z \\leq 1) = 0.5 - 0.3413 = 0.1587$\n\n**Step 4. 인원 수로 환산하기**\n전체 500명 중 상위 15.87%에 해당하는 학생 수를 구합니다.\n$500 \\times 0.1587 = 79.35\\text{명}$\n소수점 이하를 버리면 $\\lfloor 79.35 \\rfloor = 79$명입니다.\n\n**∴ 답: 79**\n\n참고: 75점 이상인 학생은 평균(60점)에서 $1\\sigma$(15점) 이상 높은 점수를 받은 학생입니다. 정규분포에서 $\\mu + 1\\sigma$ 이상은 약 15.87%입니다.\n\n**💡 포인트:** 정규분포 응용 문제는 \"표준화($Z$ 변환) → 표에서 확률 → 실제 값 환산\"의 3단계로 풀어갑니다. $P(Z \\geq 1) \\approx 0.1587$은 자주 쓰이므로 기억해두세요.",
