    "explanation": "**[풀이]**\n\n**핵심 개념:** $m \\pm k\\sigma$ 형태의 표준화\n$$P(m - a\\sigma \\leq X \\leq m + b\\sigma) = P(-a \\leq Z \\leq b)$$\n\n**Step 1. 표준화하기**\n$X$의 범위를 $Z$로 변환합니다.\n$$P(m - 2\\sigma \\leq X \\leq m + \\sigma) = P\\left(\\frac{m-2\\sigma - m}{\\sigma} \\leq Z \\leq \\frac{m+\\sigma - m}{\\sigma}\\right)$$\n$$= P(-2 \\leq Z \\leq 1)$$\n\n**Step 2. 구간을 $Z=0$ 기준으로 분리하기**\n$$P(-2 \\leq Z \\leq 1) = P(-2 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 1)$$\n\n**Step 3. 대칭성 적용하여 계산하기**\n$$P(-2 \\leq Z \\leq 0) = P(0 \\leq Z \\leq 2) = 0.4772$$\n$$P(0 \\leq Z \\leq 1) = 0.3413$$\n\n**Step 4. 합산 및 최종 답 구하기**\n$$P(-2 \\leq Z \\leq 1) = 0.4772 + 0.3413 = 0.8185$$\n소수점 넷째 자리에서 반올림: $0.8185 \\approx 0.819$\n$$0.819 \\times 1000 = 819$$\n\n**∴ 답: 819**\n\n**💡 포인트:** $m \\pm k\\sigma$는 표준화하면 $\\pm k$가 됩니다. $m$과 $\\sigma$의 구체적 값은 알 필요 없습니다.",
