    "explanation": "**[풀이]**\n\n**핵심 개념:** 표본평균의 분포\n$$\\bar{X} \\sim N\\left(\\mu, \\frac{\\sigma^2}{n}\\right), \\quad \\sigma_{\\bar{X}} = \\frac{\\sigma}{\\sqrt{n}}$$\n\n**Step 1. 표본평균의 분포 구하기**\n모집단이 $N(60, 10^2)$이고 표본 크기가 $n = 25$이므로:\n$$\\bar{X} \\sim N\\left(60, \\frac{10^2}{25}\\right) = N(60, 2^2)$$\n표본평균의 표준편차: $\\frac{\\sigma}{\\sqrt{n}} = \\frac{10}{\\sqrt{25}} = \\frac{10}{5} = 2$\n\n**Step 2. 표본평균을 표준화하기**\n$$P(\\bar{X} \\geq 64) = P\\left(Z \\geq \\frac{64 - 60}{2}\\right) = P(Z \\geq 2)$$\n\n**Step 3. 확률 계산하기**\n$$P(Z \\geq 2) = 0.5 - P(0 \\leq Z \\leq 2) = 0.5 - 0.4772 = 0.0228$$\n\n**Step 4. 주의점 확인하기**\n표준화할 때 분모는 $\\sigma = 10$이 아니라 $\\frac{\\sigma}{\\sqrt{n}} = 2$입니다! 개별 관측값이 아닌 표본평균의 분포이기 때문입니다.\n\n**∴ 답: ① 0.0228**\n\n③ 0.1587은 분모에 $\\sigma = 10$ 대신 $\\frac{\\sigma}{\\sqrt{n}} = 2$를 쓰지 않고 $Z = 0.4$로 잘못 계산한 경우입니다.\n\n**💡 포인트:** 표본평균 문제에서는 반드시 $\\frac{\\sigma}{\\sqrt{n}}$으로 나누세요. 이것이 개별값 문제와의 핵심 차이입니다.",
