    "explanation": "**[풀이]**\n\n**핵심 개념:** 대칭 구간의 확률 차이 계산\n$$P(-a \\leq Z \\leq a) = 2P(0 \\leq Z \\leq a)$$\n\n**Step 1. 첫 번째 구간 표준화하기**\n$\\mu = 100$, $\\sigma = 15$\n$$P(70 \\leq X \\leq 130) = P\\left(\\frac{70-100}{15} \\leq Z \\leq \\frac{130-100}{15}\\right) = P(-2 \\leq Z \\leq 2)$$\n\n**Step 2. 두 번째 구간 표준화하기**\n$$P(85 \\leq X \\leq 115) = P\\left(\\frac{85-100}{15} \\leq Z \\leq \\frac{115-100}{15}\\right) = P(-1 \\leq Z \\leq 1)$$\n\n**Step 3. 각 구간의 확률 계산하기**\n두 구간 모두 평균 대칭이므로:\n$$P(-2 \\leq Z \\leq 2) = 2 \\times 0.4772 = 0.9544$$\n$$P(-1 \\leq Z \\leq 1) = 2 \\times 0.3413 = 0.6826$$\n\n**Step 4. 차이 계산 및 최종 답 구하기**\n$$0.9544 - 0.6826 = 0.2718$$\n이 값은 \"$1\\sigma$와 $2\\sigma$ 사이 양쪽 영역\"의 확률입니다.\n$$0.2718 \\times 10000 = 2718$$\n\n**∴ 답: 2718**\n\n**💡 포인트:** $P(-2 \\leq Z \\leq 2) - P(-1 \\leq Z \\leq 1)$은 종 모양 곡선에서 \"가운데 좁은 구간 바깥~넓은 구간 안쪽\" 영역입니다.",
