    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립인 정규분포의 선형결합\n$X \\sim N(\\mu_1, \\sigma_1^2)$, $Y \\sim N(\\mu_2, \\sigma_2^2)$이 독립이면:\n$$X - Y \\sim N(\\mu_1 - \\mu_2, \\sigma_1^2 + \\sigma_2^2)$$\n\n**Step 1. $W = X - Y$의 평균 구하기**\n기댓값의 선형성에 의해:\n$$E(W) = E(X) - E(Y) = 10 - 5 = 5$$\n\n**Step 2. $W = X - Y$의 분산 구하기**\n**독립**이므로 뺄셈이라도 분산은 **더합니다** (핵심 주의!)\n$$V(W) = V(X) + V(Y) = 3^2 + 4^2 = 9 + 16 = 25$$\n따라서 $W \\sim N(5, 5^2)$\n\n**Step 3. 표준화하기**\n$$P(W \\geq 10) = P\\left(Z \\geq \\frac{10 - 5}{5}\\right) = P(Z \\geq 1)$$\n\n**Step 4. 확률 계산하기**\n$$P(Z \\geq 1) = 0.5 - P(0 \\leq Z \\leq 1) = 0.5 - 0.3413 = 0.1587$$\n\n**Step 5. 핵심 원리 정리**\n독립인 확률변수의 차 $X - Y$에서 분산이 더해지는 이유: 두 변수가 각각 흔들리므로 차이의 불확실성은 커집니다.\n\n**∴ 답: ② 0.1587**\n\n① 0.0228은 $P(Z \\geq 2)$의 값으로, 분산을 $V(X) - V(Y)$로 잘못 뺀 경우입니다.\n\n**💡 포인트:** \"빼기여도 분산은 더하기!\" — 독립인 정규분포의 선형결합에서 가장 많이 틀리는 포인트입니다.",
