    "explanation": "**[풀이]**\n\n**핵심 개념:** 표본평균의 표준편차 (표준오차, Standard Error)\n$\\sigma_{\\bar{X}} = \\frac{\\sigma}{\\sqrt{n}}$\n\n**Step 1. 표본평균의 분포 이해하기**\n모집단에서 크기 $n$인 표본을 추출하면, 표본평균 $\\bar{X}$도 하나의 확률변수가 됩니다. $\\bar{X}$의 표준편차는 개별 관측값의 표준편차($\\sigma$)보다 작아지는데, 이는 여러 값의 평균이 개별값보다 덜 흔들리기 때문입니다.\n\n**Step 2. 표본평균의 표준편차 공식 적용하기**\n$\\sigma_{\\bar{X}} = \\frac{\\sigma}{\\sqrt{n}}$\n\n**Step 3. 주어진 값 대입하기**\n$\\sigma = 6$, $n = 36$을 대입합니다.\n$\\sigma_{\\bar{X}} = \\frac{6}{\\sqrt{36}} = \\frac{6}{6} = 1$\n\n**Step 4. 결과의 의미 해석하기**\n개별값의 표준편차가 6이지만, 36개의 평균은 변동이 훨씬 작아져서 표준편차가 1이 됩니다. 즉, 표본 크기가 36배가 되면 표준오차는 $\\frac{1}{\\sqrt{36}} = \\frac{1}{6}$배로 줄어듭니다.\n\n**∴ 답: ② 1**\n\n⑤ 3은 $\\frac{\\sigma}{2} = \\frac{6}{2}$로 잘못 계산한 경우이고, ① $\\frac{1}{2}$은 $\\frac{\\sigma}{n} = \\frac{6}{36}$처럼 $n$으로 나눈 경우입니다. 반드시 $\\sqrt{n}$으로 나누어야 합니다.\n\n**💡 포인트:** $\\frac{\\sigma}{\\sqrt{n}}$을 **표준오차(SE)**라 하며, 표본 크기가 클수록 작아집니다. 정밀도를 2배로 높이려면 표본 크기를 4배로 늘려야 합니다.",
