    "explanation": "**[풀이]**\n\n**핵심 개념:** 홀짝 분석(Parity Analysis)과 조합\n세 수의 합이 짝수가 되는 조건: (짝+짝+짝) 또는 (홀+홀+짝)\n\n**Step 1. 홀수와 짝수 분류하기**\n$\\{1, 2, 3, 4, 5, 6\\}$에서:\n- 짝수: $\\{2, 4, 6\\}$ → 3개\n- 홀수: $\\{1, 3, 5\\}$ → 3개\n\n**Step 2. 합이 짝수가 되는 조건 파악하기**\n세 수의 합이 짝수가 되려면 홀수의 개수가 짝수 개(0개 또는 2개)여야 합니다.\n- (짝, 짝, 짝): 홀수 0개 → 짝+짝+짝 = 짝 ✓\n- (홀, 홀, 짝): 홀수 2개 → 홀+홀 = 짝, 짝+짝 = 짝 ✓\n- (홀, 짝, 짝): 홀수 1개 → 홀+짝+짝 = 홀 ✗\n- (홀, 홀, 홀): 홀수 3개 → 홀+홀+홀 = 홀 ✗\n\n**Step 3. 경우 ① — 세 수 모두 짝수**\n짝수 3개 중 3개를 모두 뽑습니다.\n$\\binom{3}{3} = 1$\n이 경우는 $\\{2, 4, 6\\}$ 단 한 가지입니다.\n\n**Step 4. 경우 ② — 홀수 2개 + 짝수 1개**\n홀수 3개 중 2개를 뽑고, 짝수 3개 중 1개를 뽑습니다.\n$\\binom{3}{2} \\times \\binom{3}{1} = 3 \\times 3 = 9$\n\n**Step 5. 합산하기**\n$1 + 9 = 10$\n\n검증: 전체 경우의 수 $\\binom{6}{3} = 20$이고, 합이 홀수인 경우는 $20 - 10 = 10$가지입니다. 대칭적으로 절반씩 나뉘므로 합리적입니다. $\\checkmark$\n\n**∴ 답: 10**\n\n**💡 포인트:** 합의 홀짝은 각 수의 홀짝만으로 결정됩니다. 구체적 수를 대입하지 않고 홀짝 분석으로 경우를 크게 줄이는 것이 핵심 기법입니다.",
