    "explanation": "**[풀이]**\n\n**핵심 개념:** \"적어도\"는 해당 조건 이상을 모두 합산\n$P(\\text{흰} \\geq 2) = P(\\text{흰} = 2) + P(\\text{흰} = 3)$\n\n**Step 1. 전체 경우의 수 구하기**\n$$\\binom{8}{3} = \\frac{8 \\times 7 \\times 6}{3!} = 56$$\n\n**Step 2. 흰 공 정확히 2개 + 검은 공 1개인 경우**\n$$\\binom{5}{2} \\times \\binom{3}{1} = 10 \\times 3 = 30$$\n\n**Step 3. 흰 공 3개인 경우**\n$$\\binom{5}{3} = 10$$\n\n**Step 4. 확률 계산하기**\n$$P(\\text{흰} \\geq 2) = \\frac{30 + 10}{56} = \\frac{40}{56} = \\frac{5}{7}$$\n\n**∴ 답: ③ $\\frac{5}{7}$**\n\n② $\\frac{15}{28}$은 여사건을 잘못 계산한 경우이며, ① $\\frac{13}{28}$은 \"적어도 2개\"가 아닌 \"정확히 2개\"까지만 센 결과를 약분 잘못한 경우입니다.\n\n**💡 포인트:** \"적어도 k개\"는 직접 세거나, 여사건(k-1개 이하)을 이용할 수 있습니다.",
