    "type": "복합 킬러",
    "problem": "확률변수 $X$가 이항분포 $B(n, p)$를 따르고 $E(X) = 6$, $V(X) = 2$일 때, $n + p$의 값을 구하시오. (답을 3배 하여 정수로 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 29,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 평균·분산에서 $n$, $p$ 역추적\n$$E(X) = np, \\quad V(X) = np(1-p), \\quad \\frac{V}{E} = 1-p$$\n\n**Step 1. $p$ 값 구하기**\n분산을 평균으로 나누면 $1-p$를 바로 구할 수 있습니다.\n$$1 - p = \\frac{V(X)}{E(X)} = \\frac{2}{6} = \\frac{1}{3}$$\n$$p = 1 - \\frac{1}{3} = \\frac{2}{3}$$\n\n**Step 2. $n$ 값 구하기**\n$E(X) = np = 6$에 $p = \\frac{2}{3}$를 대입합니다.\n$$n \\times \\frac{2}{3} = 6 \\quad \\Rightarrow \\quad n = 6 \\times \\frac{3}{2} = 9$$\n\n**Step 3. $n + p$ 계산하기**\n$$n + p = 9 + \\frac{2}{3} = \\frac{27 + 2}{3} = \\frac{29}{3}$$\n\n**Step 4. 최종 답 구하기**\n$$\\frac{29}{3} \\times 3 = 29$$\n\n**∴ 답: 29**\n\n**💡 포인트:** $\\frac{V(X)}{E(X)} = 1-p$는 이항분포 역추적의 핵심 공식입니다. 반드시 암기하세요.",
    "difficulty": "lv2",
