    "type": "복합 킬러",
    "problem": "정규분포 $N(50, 10^2)$을 따르는 모집단에서 크기 25인 표본을 추출하여 표본평균 $\\bar{x}$를 구했다. 모평균 $m$에 대한 95% 신뢰구간에 $m = 47$이 포함되려면 $\\bar{x}$의 범위를 구하시오. 이때 $\\bar{x}$가 취할 수 있는 구간의 길이를 구하시오. (소수 둘째 자리까지 구한 후, 100을 곱하여 정수로 답하시오.) (단, $P(|Z| \\leq 1.96) = 0.95$)",
    "answerType": "short",
    "choices": null,
    "answer": 784,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 신뢰구간에 특정 값이 포함되는 조건\n$$\\bar{x} - E \\leq m \\leq \\bar{x} + E \\quad \\Leftrightarrow \\quad m - E \\leq \\bar{x} \\leq m + E$$\n\n**Step 1. 오차한계 $E$ 구하기**\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{10}{\\sqrt{25}} = \\frac{10}{5} = 2$$\n$$E = z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}} = 1.96 \\times 2 = 3.92$$\n\n**Step 2. 신뢰구간을 $\\bar{x}$로 표현하기**\n$$\\bar{x} - 3.92 \\leq m \\leq \\bar{x} + 3.92$$\n\n**Step 3. $m = 47$이 포함되는 $\\bar{x}$의 조건 구하기**\n$m = 47$이 구간에 포함되려면:\n$$\\bar{x} - 3.92 \\leq 47 \\leq \\bar{x} + 3.92$$\n\n왼쪽 부등식에서: $\\bar{x} \\leq 47 + 3.92 = 50.92$\n오른쪽 부등식에서: $\\bar{x} \\geq 47 - 3.92 = 43.08$\n\n$$43.08 \\leq \\bar{x} \\leq 50.92$$\n\n**Step 4. 구간의 길이 계산하기**\n$$50.92 - 43.08 = 7.84$$\n\n**Step 5. 최종 답 구하기**\n$$7.84 \\times 100 = 784$$\n\n참고: 이 길이는 $2E = 2 \\times 3.92 = 7.84$와 같습니다. 이는 신뢰구간의 길이와 동일합니다!\n\n**∴ 답: 784**\n\n**💡 포인트:** \"$m$이 $\\bar{x}$의 구간에 포함\" ↔ \"$\\bar{x}$가 $m$의 구간에 포함\"은 동치입니다. 부등식을 뒤집어 생각하는 역발상이 핵심입니다.",
    "difficulty": "lv3",
