    "answerType": "short",
    "choices": null,
    "answer": 60,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립적인 순서 조건을 각각 적용\n\n**Step 1. 전체 배열**\n$$6! = 720$$\n\n**Step 2. 조건 1: 1 < 2 < 3 (위치 순서)**\n1, 2, 3의 상대적 순서가 1 < 2 < 3으로 고정. 3개의 모든 순서 $3! = 6$가지 중 1가지.\n$$\\frac{6!}{3!}$$\n\n**Step 3. 조건 2: 4 < 5 (위치 순서)**\n4, 5의 상대적 순서가 4 < 5로 고정. 2개의 모든 순서 $2! = 2$가지 중 1가지.\n\n**Step 4. 두 조건은 독립**\n{1,2,3}과 {4,5}는 서로 겹치지 않으므로 두 조건을 독립적으로 적용합니다.\n$$\\frac{6!}{3! \\times 2!} = \\frac{720}{6 \\times 2} = \\frac{720}{12} = 60$$\n\n**Step 5. 검증**\n6자리에서 {1,2,3}의 위치 3개를 먼저 정하면 $\\binom{6}{3} = 20$, 순서 고정이므로 20가지. {4,5}가 남은 3자리 중 2개에 위치: $\\binom{3}{2} = 3$, 순서 고정이므로 3가지. 6은 나머지 1자리. $20 \\times 3 \\times 1 = 60$ ✓\n\n**∴ 답: 60**\n\n**💡 포인트:** 서로 겹치지 않는 그룹의 순서 조건은 각각 나누면 됩니다: $\\frac{n!}{k_1! \\times k_2!}$",
