    "explanation": "**[풀이]**\n\n**핵심 개념:** 단조증가 또는 단조감소 배열 = 조합으로 전환\n\n**Step 1. 단조증가 수**\n7개에서 4개를 택하면 증가 순서는 유일하게 결정됩니다.\n$$\\binom{7}{4} = 35$$\n\n**Step 2. 단조감소 수**\n마찬가지로 4개를 택하면 감소 순서도 유일합니다.\n$$\\binom{7}{4} = 35$$\n\n**Step 3. 합산**\n증가와 감소는 동시에 성립할 수 없으므로 (4개 이상의 수에서):\n$$35 + 35 = 70$$\n\n**Step 4. 검증**\n예를 들어 {1,2,3,4}를 택하면 증가수 1234, 감소수 4321. 이 둘은 다른 수이므로 중복 없음. ✓\n전체 네 자리 순열: $_7P_4 = 840$. 이 중 증가+감소 = 70으로 비율 $\\frac{70}{840} = \\frac{1}{12}$. 각 조합에서 $4! = 24$개의 배열 중 증가 1개 + 감소 1개 = 2개. $\\frac{2}{24} = \\frac{1}{12}$ ✓\n\n**∴ 답: 70**\n\n**💡 포인트:** 단조증가/감소 배열은 순서가 유일하므로 '선택'만 하면 됩니다. 순열이 조합으로 바뀌는 대표적 유형입니다.",
