    "explanation": "**[풀이]**\n\n**핵심 개념:** 포함-배제 원리: $|A^c \\cap B^c| = |U| - |A \\cup B|$\n\n**Step 1. 전체 경로 수**\n$(0,0) \\to (4,3)$: 오른쪽 4칸, 위 3칸 → $\\binom{7}{3} = 35$\n\n**Step 2. (1,1)을 지나는 경로 수 (A)**\n$(0,0) \\to (1,1)$: $\\binom{2}{1} = 2$\n$(1,1) \\to (4,3)$: $\\binom{5}{2} = 10$\n$$|A| = 2 \\times 10 = 20$$\n\n**Step 3. (2,2)를 지나는 경로 수 (B)**\n$(0,0) \\to (2,2)$: $\\binom{4}{2} = 6$\n$(2,2) \\to (4,3)$: $\\binom{3}{1} = 3$\n$$|B| = 6 \\times 3 = 18$$\n\n**Step 4. (1,1)과 (2,2)를 모두 지나는 경로 수 ($A \\cap B$)**\n$(0,0) \\to (1,1) \\to (2,2) \\to (4,3)$:\n$$2 \\times \\binom{2}{1} \\times 3 = 2 \\times 2 \\times 3 = 12$$\n\n**Step 5. 포함-배제**\n$$|A \\cup B| = 20 + 18 - 12 = 26$$\n$$|A^c \\cap B^c| = 35 - 26 = 9$$\n\n**∴ 답: 9**\n\n**💡 포인트:** '모두 지나지 않는' = $(A \\cup B)^c$. 포함-배제로 $|A \\cup B|$를 구한 뒤 전체에서 빼면 됩니다.",
