    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** (최솟값, 최댓값) 쌍을 고정하고 사이의 원소를 선택합니다.\n\n4개를 택했을 때 최솟값 $a$, 최댓값 $b$이면 $b - a \\geq 7$.\n\n**Step 1. 가능한 $(a, b)$ 쌍 나열**\n\n차이 7: $(1,8), (2,9), (3,10)$\n- 각각 사이 원소 6개에서 2개 택: $3 \\times \\binom{6}{2} = 3 \\times 15 = 45$\n\n차이 8: $(1,9), (2,10)$\n- 각각 사이 원소 7개에서 2개 택: $2 \\times \\binom{7}{2} = 2 \\times 21 = 42$\n\n차이 9: $(1,10)$\n- 사이 원소 8개에서 2개 택: $\\binom{8}{2} = 28$\n\n**Step 2. 합산**\n$$45 + 42 + 28 = 115$$\n\n**Step 3. 검증**\n전체 $\\binom{10}{4} = 210$. 차이 < 7인 경우: $210 - 115 = 95$. 합리적인 값입니다. ✓\n\n**∴ 답: ③ 115**\n\n**💡 포인트:** 최댓값-최솟값 조건은 양 끝 $(a, b)$을 고정하고 사이의 원소를 택하는 방법으로 풀 수 있습니다. 빠짐없이 모든 쌍을 나열하는 것이 핵심입니다.",
