    "type": "중복순열·중복조합",
    "problem": "서로 다른 4개의 문자 a, b, c, d에서 중복을 허락하여 3개를 택해 일렬로 나열하는 경우의 수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 64,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 서로 다른 $n$개에서 중복을 허락하여 $r$개를 택해 일렬로 나열하는 **중복순열**의 수는 $n^r$입니다.\\n$$_n\\Pi_r = n^r$$\\n\\n**Step 1. 중복순열 판별**\\n4개의 문자에서 중복을 허락하여 3개를 택해 '일렬로 나열'하므로 순서가 중요합니다. 같은 문자를 여러 번 사용할 수 있으므로 이는 **중복순열**에 해당합니다.\\n\\n**Step 2. 각 자리별 선택 가능한 문자 수**\\n- 첫 번째 자리: a, b, c, d 중 하나 → **4가지**\\n- 두 번째 자리: 중복 허용이므로 다시 4개 모두 가능 → **4가지**\\n- 세 번째 자리: 마찬가지로 → **4가지**\\n\\n**Step 3. 곱의 법칙 적용**\\n각 자리의 선택은 독립적이므로 곱의 법칙을 적용합니다.\\n$$_4\\Pi_3 = 4^3 = 4 \\times 4 \\times 4 = 64$$\\n\\n**Step 4. 검증**\\n중복을 허락하지 않았다면 $_4P_3 = 4 \\times 3 \\times 2 = 24$이므로, 중복을 허락한 64가 이보다 큰 것은 합리적입니다. ✓\\n\\n**∴ 답: 64**\\n\\n**💡 포인트:** 중복순열 = $n^r$, 순열 = $_nP_r$. 중복 허용 여부에 따라 공식이 달라지므로 문제 조건을 정확히 파악하세요.",
