    "answer": 1,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 서로 다른 $n$개에서 중복을 허락하여 $r$개를 택하는 **중복조합**의 수는 $_nH_r$입니다.\\n$$_nH_r = _{n+r-1}C_r = \\frac{(n+r-1)!}{r!(n-1)!}$$\\n\\n**Step 1. 중복조합 판별**\\n3가지 종류의 음료에서 중복을 허락하여 5잔을 '선택'하는 것이므로 순서는 중요하지 않습니다. 같은 종류를 여러 번 택할 수 있으므로 **중복조합**에 해당합니다.\\n\\n**Step 2. 공식 대입**\\n$n = 3$, $r = 5$이므로:\\n$$_3H_5 = _{3+5-1}C_5 = _7C_5$$\\n\\n**Step 3. 조합 계산**\\n$$_7C_5 = _7C_2 = \\frac{7 \\times 6}{2 \\times 1} = 21$$\\n\\n**Step 4. 검증 — 칸막이 모델**\\n○○○○○를 2개의 칸막이 |로 3구간으로 나누는 것과 같습니다. 전체 7자리(○5개 + |2개)에서 |의 위치 2곳을 선택하면 $_7C_2 = 21$. ✓\\n\\n**∴ 답: ② 21**\\n\\n⑤ 243은 중복순열 $3^5$를 구한 경우로, 순서를 고려한 오답입니다.\\n\\n**💡 포인트:** '선택'이면 조합, '나열'이면 순열. 중복조합 $_nH_r = _{n+r-1}C_r$을 정확히 기억하세요.",
