    "answer": 54,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 네 자리 양의 정수에서 천의 자리는 0이 올 수 없습니다. 나머지 자리는 중복순열을 적용합니다.\\n\\n**Step 1. 천의 자리 결정**\\n네 자리 양의 정수이므로 천의 자리에 0은 올 수 없습니다.\\n사용 가능한 숫자: 1, 2 → **2가지**\\n\\n**Step 2. 나머지 세 자리 결정**\\n백의 자리, 십의 자리, 일의 자리 각각에 0, 1, 2 모두 올 수 있습니다.\\n- 백의 자리: 3가지\\n- 십의 자리: 3가지\\n- 일의 자리: 3가지\\n\\n**Step 3. 곱의 법칙 적용**\\n$$2 \\times 3 \\times 3 \\times 3 = 2 \\times 27 = 54$$\\n\\n**Step 4. 검증**\\n전체 네 자리 수열(0 포함)은 $3^4 = 81$개이고, 천의 자리가 0인 경우는 $3^3 = 27$개이므로 $81 - 27 = 54$. ✓\\n\\n**∴ 답: 54**\\n\\n**💡 포인트:** 양의 정수 조건에서 맨 앞자리 0 제외를 잊지 마세요. 전체에서 빼는 여사건 방법도 유용합니다.",
