    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 중복순열의 공식은 $_n\\Pi_r = n^r$입니다. 이때 $n$은 택할 대상의 종류, $r$은 나열 횟수입니다.\\n\\n**Step 1. $2^5$ 분석**\\n$2^5$에서 밑수 $2$는 선택 가능한 대상의 수($n$)이고, 지수 $5$는 택하는 횟수($r$)입니다.\\n\\n**Step 2. 해석**\\n서로 다른 2개의 대상에서 중복을 허락하여 5개를 택해 일렬로 나열하는 경우입니다.\\n$$_2\\Pi_5 = 2^5 = 32$$\\n예: 동전 5번 던지기(앞/뒤 = 2가지, 5회 = $2^5 = 32$가지)\\n\\n**Step 3. 다른 보기 확인**\\n① $_2H_5 = _6C_5 = 6$ (중복조합이므로 다름)\\n② $_5\\Pi_2 = 5^2 = 25$ (밑과 지수가 반대)\\n④ $_5H_2 = _6C_2 = 15$ (중복조합)\\n⑤ $_2C_5$: $n < r$이므로 정의 불가\\n\\n**∴ 답: ③ 2개에서 5개를 택하는 중복순열**\\n\\n**💡 포인트:** $n^r$에서 **밑 $n$ = 종류 수**, **지수 $r$ = 택하는 횟수**를 구분하는 것이 핵심입니다.",
