    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 같은 종류의 공 $r$개를 서로 다른 $n$개의 상자에 넣는 것은 **중복조합** $_nH_r$에 해당합니다.\\n$$_nH_r = _{n+r-1}C_r$$\\n\\n**Step 1. 중복조합 판별**\\n공이 모두 같으므로 어떤 공이 어떤 상자에 들어가는지의 순서는 의미 없습니다. 각 상자에 들어가는 공의 '개수'만 중요하므로, 3개의 상자에서 중복을 허락하여 6개를 선택하는 중복조합과 같습니다.\\n\\n**Step 2. 공식 대입**\\n$n = 3$ (상자), $r = 6$ (공)\\n$$_3H_6 = _{3+6-1}C_6 = _8C_6$$\\n\\n**Step 3. 계산**\\n$$_8C_6 = _8C_2 = \\frac{8 \\times 7}{2 \\times 1} = 28$$\\n\\n**Step 4. 검증**\\n$x_1 + x_2 + x_3 = 6$ ($x_i \\geq 0$)의 음이 아닌 정수해의 수와 같습니다. 칸막이 모델로 ○○○○○○|| 에서 8자리 중 |의 위치 2곳 선택 = $_8C_2 = 28$. ✓\\n\\n**∴ 답: ③ 28**\\n\\n⑤ 729는 서로 다른 공을 넣는 중복순열 $3^6$을 구한 오답입니다.\\n\\n**💡 포인트:** 같은 공 → 중복조합, 서로 다른 공 → 중복순열. 공의 구별 여부가 핵심입니다.",
