    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 각 시행에서 독립적으로 $n$가지 결과가 나오는 시행을 $r$번 반복하면, 모든 순서쌍의 수는 중복순열 $n^r$입니다.\\n\\n**Step 1. 중복순열 판별**\\n주사위의 각 눈은 1~6의 6가지이고, 3번 던지는 각 시행은 독립적입니다. 순서쌍 $(a, b, c)$이므로 순서가 중요합니다.\\n이는 6개에서 중복을 허락하여 3개를 택해 나열하는 중복순열입니다.\\n\\n**Step 2. 계산**\\n$$_6\\Pi_3 = 6^3 = 6 \\times 6 \\times 6 = 216$$\\n\\n**Step 3. 확인**\\n- $a$: 1~6 중 하나 (6가지)\\n- $b$: 1~6 중 하나 (6가지)\\n- $c$: 1~6 중 하나 (6가지)\\n곱의 법칙: $6 \\times 6 \\times 6 = 216$ ✓\\n\\n**∴ 답: 216**\\n\\n**💡 포인트:** 주사위, 동전 등 독립 시행의 반복은 전형적인 중복순열 상황입니다. 순서쌍으로 물어보면 $n^r$을 바로 적용하세요.",
