    "explanation": "**[풀이]**\\n\\n**핵심 개념:** $x_1 + x_2 + \\cdots + x_n = r$ ($x_i \\geq 1$)의 **양의 정수해**의 개수는 $_{r-1}C_{n-1}$입니다. 또는 $x_i' = x_i - 1$로 치환하면 음이 아닌 정수해 문제로 변환됩니다.\\n\\n**Step 1. 양의 정수 → 음이 아닌 정수 치환**\\n$x \\geq 1, y \\geq 1, z \\geq 1$이므로 $x' = x-1, y' = y-1, z' = z-1$으로 치환합니다. 그러면 $x', y', z' \\geq 0$이고:\\n$$x' + y' + z' = 5 - 3 = 2$$\\n\\n**Step 2. 중복조합 적용**\\n$$_3H_2 = _{3+2-1}C_2 = _4C_2 = \\frac{4 \\times 3}{2 \\times 1} = 6$$\\n\\n**Step 3. 검증 — 직접 나열**\\n$(x, y, z)$: $(1,1,3), (1,3,1), (3,1,1), (1,2,2), (2,1,2), (2,2,1)$ → 6가지 ✓\\n\\n**∴ 답: ② 6**\\n\\n③ 10은 음이 아닌 정수해 $_3H_5 = 21$이 아니라 $_3H_2 = 6$을 구해야 하므로 오답입니다.\\n\\n**💡 포인트:** 양의 정수해는 각 변수에서 1씩 빼서 음이 아닌 정수해로 변환하세요. $r$에서 $n$을 빼는 것을 잊지 마세요.",
