    "explanation": "**[풀이]**\\n\\n**핵심 개념:** $x_1 + x_2 + \\cdots + x_n = r$ ($x_i \\geq 1$)의 양의 정수해는 치환 후 음이 아닌 정수해로 변환합니다.\\n\\n**Step 1. 치환**\\n$a' = a - 1, b' = b - 1, c' = c - 1$으로 놓으면 $a', b', c' \\geq 0$이고:\\n$$a' + b' + c' = 8 - 3 = 5$$\\n\\n**Step 2. 중복조합 적용**\\n$$_3H_5 = _{3+5-1}C_5 = _7C_5 = _7C_2 = \\frac{7 \\times 6}{2} = 21$$\\n\\n**Step 3. 검증**\\n양의 정수해의 공식으로도 확인합니다:\\n$$_{r-1}C_{n-1} = _7C_2 = 21$$ ✓\\n\\n또한 칸막이 방법: 8개의 ○를 일렬로 놓고 7개의 틈 중 2곳에 칸막이를 넣으면:\\n$$_7C_2 = 21$$ ✓\\n\\n**∴ 답: 21**\\n\\n**💡 포인트:** 양의 정수해는 $_{r-1}C_{n-1}$, 음이 아닌 정수해는 $_nH_r = _{n+r-1}C_r$. 두 공식을 구분하세요.",
