    "answer": 38,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 상한 조건이 있는 경우, 조건을 만족하는 각 경우를 분리하여 합합니다.\\n\\n**Step 1. $x$의 값에 따른 분류**\\n$x \\leq 3$이므로 $x = 0, 1, 2, 3$ 각각에 대해 $y + z$의 음이 아닌 정수해를 구합니다.\\n\\n**Step 2. 각 경우 계산**\\n$y + z = 10 - x$의 음이 아닌 정수해의 수는 $(10-x) + 1 = 11 - x$가지입니다.\\n($(0, 10-x), (1, 10-x-1), \\ldots, (10-x, 0)$)\\n\\n- $x = 0$: $y + z = 10$ → $11$가지\\n- $x = 1$: $y + z = 9$ → $10$가지\\n- $x = 2$: $y + z = 8$ → $9$가지\\n- $x = 3$: $y + z = 7$ → $8$가지\\n\\n**Step 3. 합산**\\n$$11 + 10 + 9 + 8 = 38$$\\n\\n**Step 4. 검증 — 여사건**\\n전체 해의 수: $_3H_{10} = _{12}C_2 = 66$\\n$x \\geq 4$인 해: $x' = x-4$로 치환하면 $x' + y + z = 6$, $_3H_6 = _8C_2 = 28$\\n$x \\leq 3$인 해: $66 - 28 = 38$ ✓\\n\\n**∴ 답: 38**\\n\\n**💡 포인트:** 상한 조건이 있으면 해당 변수를 고정하고 나머지의 해를 구하세요. 여사건(전체 - 초과분)도 가능합니다.",
