    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 같은 물건을 나누는 문제에서 '적어도 k개' 조건은 치환 후 중복조합으로 해결합니다.\\n\\n**Step 1. 치환**\\n각 학생이 적어도 2개를 받으므로, 먼저 각 학생에게 2개씩 배분합니다.\\n$3 \\times 2 = 6$개를 미리 배분, 남은 사탕: $10 - 6 = 4$개\\n\\n**Step 2. 남은 사탕 배분**\\n같은 종류의 사탕 4개를 3명에게 자유롭게 나누는 문제입니다.\\n$$_3H_4 = _{3+4-1}C_4 = _6C_4 = _6C_2 = \\frac{6 \\times 5}{2} = 15$$\\n\\n**Step 3. 검증**\\n$x_1 + x_2 + x_3 = 10$ ($x_i \\geq 2$)에서 $x_i' = x_i - 2$로 치환하면 $x_1' + x_2' + x_3' = 4$의 음이 아닌 정수해 = $_3H_4 = 15$ ✓\\n\\n**∴ 답: 15**\\n\\n**💡 포인트:** '적어도 k개' → 먼저 k개씩 배분 → 남은 것을 자유롭게 배분. 이 2단계 전략을 기억하세요.",
