    "answer": 0,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 각 $f(i) \\in \\{1, 2, 3, 4\\}$이고 $f(1) + f(2) + f(3) + f(4) = 10$인 순서쌍의 수를 구합니다. 상하한이 있는 부정방정식 문제입니다.\\n\\n**Step 1. 치환으로 하한 제거**\\n$f(i) \\geq 1$이므로 $g(i) = f(i) - 1$로 놓으면 $g(i) \\in \\{0, 1, 2, 3\\}$이고:\\n$$g(1) + g(2) + g(3) + g(4) = 10 - 4 = 6$$\\n단, $0 \\leq g(i) \\leq 3$\\n\\n**Step 2. 포함-배제 원리**\\n먼저 상한 없이: $_4H_6 = _9C_6 = _9C_3 = 84$\\n\\n$A_i$: $g(i) \\geq 4$인 해의 집합. $g(i)' = g(i) - 4$로 치환하면:\\n$g(i)' + \\text{나머지 합} = 6 - 4 = 2$이므로 $_4H_2 = _5C_2 = 10$\\n\\n$|A_i| = 10$이고 이런 $i$가 4개이므로:\\n$\\sum |A_i| = 4 \\times 10 = 40$\\n\\n$|A_i \\cap A_j|$: $g(i) \\geq 4$이고 $g(j) \\geq 4$이면 합이 $\\geq 8 > 6$이므로 해가 없습니다.\\n\\n**Step 3. 포함-배제 적용**\\n$$84 - 40 + 0 = 44$$\\n\\n**Step 4. 검증**\\n$g(i) \\leq 3$, 합 = 6: 직접 세어도 44가 나옵니다. 예를 들어 $(3,3,0,0)$ 형태는 $\\frac{4!}{2!2!} = 6$가지, $(3,2,1,0)$ 형태는 $4! = 24$가지, $(3,1,1,1)$ 형태는 4가지, $(2,2,2,0)$ 형태는 4가지, $(2,2,1,1)$ 형태는 $\\frac{4!}{2!2!} = 6$가지. 합: $6 + 24 + 4 + 4 + 6 = 44$ ✓\\n\\n**∴ 답: ① 44**\\n\\n⑤ 84는 상한 조건($g(i) \\leq 3$)을 무시한 경우입니다.\\n\\n**💡 포인트:** 상하한이 있는 부정방정식에서는 포함-배제 원리가 핵심 도구입니다.",
