    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 비내림차순 수열 = 중복조합. $\\{1, 2, 3, 4\\}$에서 중복을 허락하여 5개를 택하는 것과 같습니다.\\n\\n**Step 1. 중복조합으로 변환**\\n$a_1 \\leq a_2 \\leq a_3 \\leq a_4 \\leq a_5$이고 각 $a_i \\in \\{1, 2, 3, 4\\}$이므로, 이는 4종류에서 중복을 허락하여 5개를 선택하는 중복조합과 정확히 같습니다.\\n\\n**Step 2. 계산**\\n$$_4H_5 = _{4+5-1}C_5 = _8C_5 = _8C_3 = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1} = 56$$\\n\\n**Step 3. 검증**\\n방정식 $x_1 + x_2 + x_3 + x_4 = 5$ ($x_i \\geq 0$, $x_i$는 값 $i$가 수열에 나타나는 횟수)의 음이 아닌 정수해의 수와 같습니다. $_4H_5 = 56$ ✓\\n\\n**∴ 답: 56**\\n\\n**💡 포인트:** 비내림차순(≤) → 중복조합, 순증가(<) → 조합. 수열과 중복조합의 대응은 수능 빈출 유형입니다.",
