    "answer": 2,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 상한 조건이 모든 변수에 있을 때 **포함-배제 원리**를 사용합니다.\\n\\n**Step 1. 상한 없는 전체 해의 수**\\n$x + y + z = 10$ ($x, y, z \\geq 0$)의 해:\\n$$_3H_{10} = _{12}C_2 = \\frac{12 \\times 11}{2} = 66$$\\n\\n**Step 2. $A_i$: $x_i \\geq 6$인 해의 집합**\\n$x \\geq 6$이면 $x' = x - 6$으로 치환: $x' + y + z = 4$\\n$$_3H_4 = _6C_2 = 15$$\\n대칭이므로 $|A_1| = |A_2| = |A_3| = 15$\\n$$\\sum |A_i| = 3 \\times 15 = 45$$\\n\\n**Step 3. $A_i \\cap A_j$: 두 변수가 $\\geq 6$**\\n$x \\geq 6, y \\geq 6$이면 치환: $x' + y' + z = 10 - 12 = -2 < 0$이므로 해가 없습니다.\\n\\n**Step 4. 포함-배제 적용**\\n$$66 - 45 + 0 = 21$$\\n\\n**Step 5. 검증**\\n$x = 5$일 때: $y + z = 5$ ($y, z \\leq 5$), 6가지\\n$x = 4$: $y + z = 6$ ($y, z \\leq 5$), $(1,5)(2,4)(3,3)(4,2)(5,1)$ = 5가지\\n$x = 3$: $y + z = 7$, $(2,5)(3,4)(4,3)(5,2)$ = 4가지\\n$x = 2$: 3가지, $x = 1$: 2가지, $x = 0$: 1가지\\n합: $6+5+4+3+2+1 = 21$ ✓\\n\\n**∴ 답: ③ 21**\\n\\n**💡 포인트:** 모든 변수에 상한이 있는 부정방정식은 포함-배제 원리의 대표 유형입니다.",
