    "problem": "집합 $X = \\{1, 2, 3, 4\\}$에서 집합 $X$로의 함수 $f$ 중에서 $f(1) \\leq f(2) \\leq f(3) \\leq f(4)$이고 $f(1) + f(4) = 5$를 만족하는 함수의 개수를 구하시오.",
