    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 짝수의 합의 홀짝성을 먼저 확인합니다.\\n\\n**Step 1. 홀짝성 분석**\\n$x, y, z$가 모두 짝수(0 포함)이면 $x = 2a, y = 2b, z = 2c$ ($a, b, c \\geq 0$)로 놓을 수 있습니다.\\n$$2a + 2b + 2c = 15$$\\n$$a + b + c = \\frac{15}{2} = 7.5$$\\n\\n**Step 2. 모순 확인**\\n$a, b, c$는 음이 아닌 **정수**여야 하므로, 합이 $7.5$(소수)가 될 수 없습니다.\\n\\n**Step 3. 결론**\\n짝수 3개의 합은 항상 짝수이므로 홀수 15가 될 수 없습니다. 해가 존재하지 않습니다.\\n\\n**∴ 답: 0**\\n\\n**💡 포인트:** 부정방정식을 풀기 전에 홀짝성(parity)을 반드시 확인하세요. 짝수의 합은 짝수, 홀수의 합은 홀짝이 교대합니다.",
