    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 다항정리에서 $(x_1 + x_2 + \\cdots + x_k)^n$의 서로 다른 항의 수는 지수의 조합, 즉 $a_1 + a_2 + \\cdots + a_k = n$ ($a_i \\geq 0$)의 해의 수와 같습니다.\\n\\n**Step 1. 다항정리 분석**\\n$(x_1 + x_2 + x_3)^4$를 전개하면 각 항은 $x_1^{a_1} x_2^{a_2} x_3^{a_3}$ 형태입니다 ($a_1 + a_2 + a_3 = 4$, $a_i \\geq 0$).\\n\\n**Step 2. 서로 다른 항의 수**\\n서로 다른 $(a_1, a_2, a_3)$ 순서쌍의 수를 구합니다:\\n$$_3H_4 = _{3+4-1}C_4 = _6C_4 = _6C_2 = \\frac{6 \\times 5}{2} = 15$$\\n\\n**Step 3. 검증**\\n$k = 2$일 때 $(x_1 + x_2)^4$의 항 수는 $a_1 + a_2 = 4$의 해 5개 ($x_1^4, x_1^3x_2, \\ldots, x_2^4$)이고 $_2H_4 = 5$와 일치합니다. ✓\\n\\n**∴ 답: ③ 15**\\n\\n⑤ 81은 $3^4$으로, 이는 전개 시 동류항을 합치기 전의 항 수입니다.\\n\\n**💡 포인트:** 다항정리의 항 수 = 중복조합. $(x_1 + \\cdots + x_k)^n$의 서로 다른 항의 수는 $_kH_n$입니다.",
