    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 각 자릿수가 비내림차순인 세 자리 수는 $a \\leq b \\leq c$ ($a, b, c \\in \\{1, 2, 3\\}$, $a \\geq 1$)인 수 $\\overline{abc}$입니다.\\n\\n**Step 1. 비내림차순 조건 분석**\\n$f(n) = 1$이란, $n$이 세 자리 수이고 그 자릿수가 비내림차순이라는 의미입니다.\\n\\n$\\{1, 2, 3\\}$에서 중복을 허락하여 3개를 비내림차순으로 택하면 이것이 곧 $a \\leq b \\leq c$인 세 자리 수가 됩니다.\\n\\n**Step 2. 중복조합 적용**\\n$$_3H_3 = _{3+3-1}C_3 = _5C_3 = _5C_2 = \\frac{5 \\times 4}{2} = 10$$\\n\\n**Step 3. 나열 검증**\\n111, 112, 113, 122, 123, 133, 222, 223, 233, 333 → 10개 ✓\\n\\n**∴ 답: 10**\\n\\n**💡 포인트:** 비내림차순 수열은 중복조합과 일대일 대응됩니다. 이 연결고리는 수능에서 자주 활용됩니다.",
