    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 계수가 1이 아닌 변수가 포함된 부정방정식은, 해당 변수를 고정하고 나머지를 구합니다.\\n\\n**Step 1. $x$ 고정**\\n$2x \\leq 10$이므로 $x = 0, 1, 2, 3, 4, 5$가 가능합니다.\\n$x = k$이면 $y + z = 10 - 2k$ ($y, z \\geq 0$)\\n\\n**Step 2. 각 $x$에 대한 해의 수**\\n$y + z = m$의 음이 아닌 정수해의 수는 $m + 1$입니다.\\n\\n- $x = 0$: $y + z = 10$ → $11$가지\\n- $x = 1$: $y + z = 8$ → $9$가지\\n- $x = 2$: $y + z = 6$ → $7$가지\\n- $x = 3$: $y + z = 4$ → $5$가지\\n- $x = 4$: $y + z = 2$ → $3$가지\\n- $x = 5$: $y + z = 0$ → $1$가지\\n\\n**Step 3. 합산**\\n$$11 + 9 + 7 + 5 + 3 + 1 = 36$$\\n\\n**Step 4. 검증**\\n이는 등차수열 $1, 3, 5, 7, 9, 11$의 합이며, 항 수 6개, $\\frac{6(1+11)}{2} = 36$ ✓\\n\\n**∴ 답: ④ 36**\\n\\n**💡 포인트:** 계수가 다른 부정방정식에서는 큰 계수의 변수를 고정하고, 나머지 변수의 해를 등차수열의 합으로 구합니다.",
