    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 이항정리에 의해 $(a+b)^n = \\sum_{k=0}^{n} _nC_k\\, a^{n-k}\\, b^k$입니다.\\n$$(1+x)^n = \\sum_{k=0}^{n} _nC_k\\, x^k$$\\n\\n**Step 1. 일반항 확인**\\n$(1+x)^5$의 일반항은 $_5C_k\\, x^k$입니다.\\n\\n**Step 2. $x^3$의 계수**\\n$k = 3$을 대입합니다:\\n$$_5C_3 = \\frac{5!}{3!\\,2!} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\\n\\n**Step 3. 검증**\\n$(1+x)^5 = 1 + 5x + 10x^2 + 10x^3 + 5x^4 + x^5$\\n$x^3$의 계수는 10. ✓\\n\\n**∴ 답: 10**\\n\\n**💡 포인트:** $(1+x)^n$에서 $x^k$의 계수는 바로 $_nC_k$입니다. 이항계수와 조합의 관계를 기억하세요.",
