    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 이항계수에서 짝수 번째 합 또는 홀수 번째 합을 구하는 공식입니다.\\n$$(1+1)^n = 2^n, \\quad (1-1)^n = 0$$\\n\\n**Step 1. 두 등식 설정**\\n$(1+x)^{10}$에 $x = 1$: $\\sum_{k=0}^{10} _{10}C_k = 2^{10} = 1024$ ··· ①\\n$(1+x)^{10}$에 $x = -1$: $\\sum_{k=0}^{10} _{10}C_k \\cdot (-1)^k = 0$ ··· ②\\n\\n**Step 2. ① + ② 계산**\\n$$① + ②: 2(_{10}C_0 + _{10}C_2 + _{10}C_4 + \\cdots + _{10}C_{10}) = 1024$$\\n$$_{10}C_0 + _{10}C_2 + \\cdots + _{10}C_{10} = \\frac{1024}{2} = 512$$\\n\\n**Step 3. 검증**\\n$1 + 45 + 210 + 252 + 210 + 45 + 1 = ...$\\n아, $_{10}C_0 = 1, _{10}C_2 = 45, _{10}C_4 = 210, _{10}C_6 = 210, _{10}C_8 = 45, _{10}C_{10} = 1$\\n합: $1 + 45 + 210 + 210 + 45 + 1 = 512$ ✓\\n\\n**∴ 답: 512**\\n\\n**💡 포인트:** 짝수 번째 이항계수의 합 = 홀수 번째 합 = $2^{n-1}$. $x = 1$과 $x = -1$ 대입의 합/차로 구합니다.",
