    "answer": 51,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** $11^5 = (10 + 1)^5$로 놓고 이항정리를 적용합니다. $10^2 = 100$이므로 $10^2$ 이상의 항은 100의 배수입니다.\\n\\n**Step 1. 이항전개**\\n$$(10+1)^5 = \\sum_{k=0}^{5} _5C_k \\cdot 10^{5-k} \\cdot 1^k$$\\n$$= 10^5 + 5 \\cdot 10^4 + 10 \\cdot 10^3 + 10 \\cdot 10^2 + 5 \\cdot 10 + 1$$\\n\\n**Step 2. 100으로 나눈 나머지**\\n$10^2$ 이상인 항($10^5, 5 \\cdot 10^4, 10 \\cdot 10^3, 10 \\cdot 10^2$)은 모두 100의 배수이므로 나머지에 기여하지 않습니다.\\n\\n나머지에 기여하는 항:\\n$$_5C_4 \\cdot 10^1 + _5C_5 \\cdot 10^0 = 5 \\cdot 10 + 1 = 51$$\\n\\n**Step 3. 검증**\\n$11^5 = 161051$, $161051 \\div 100 = 1610$ 나머지 $51$ ✓\\n\\n**∴ 답: 51**\\n\\n**💡 포인트:** 나머지 구하기에 이항정리를 활용할 때, $10^k$에서 $k \\geq 2$인 항은 100의 배수임을 이용합니다.",
