    "answer": 2,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** $(1+x)^n$에서 $x$의 계수는 $_nC_1 = n$, $x^2$의 계수는 $_nC_2 = \\frac{n(n-1)}{2}$입니다.\\n\\n**Step 1. 조건 설정**\\n$x^2$의 계수 = $x$의 계수의 4배:\\n$$_nC_2 = 4 \\cdot _nC_1$$\\n$$\\frac{n(n-1)}{2} = 4n$$\\n\\n**Step 2. 방정식 풀기**\\n$n \\neq 0$이므로 양변을 $n$으로 나눕니다:\\n$$\\frac{n-1}{2} = 4$$\\n$$n - 1 = 8$$\\n$$n = 9$$\\n\\n**Step 3. 검증**\\n$_9C_1 = 9$, $_9C_2 = 36 = 4 \\times 9$ ✓\\n\\n**∴ 답: ③ 9**\\n\\n**💡 포인트:** 이항계수의 비 관계식 $\\frac{_nC_{k+1}}{_nC_k} = \\frac{n-k}{k+1}$을 활용하면 빠르게 풀 수 있습니다.",
