    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 일반항에서 $x$의 지수를 정리합니다.\\n\\n**Step 1. 일반항**\\n$(x + (-\\frac{1}{x}))^9$의 일반항:\\n$$_9C_k \\cdot x^{9-k} \\cdot \\left(-\\frac{1}{x}\\right)^k = _9C_k \\cdot (-1)^k \\cdot x^{9-k} \\cdot x^{-k} = _9C_k \\cdot (-1)^k \\cdot x^{9-2k}$$\\n\\n**Step 2. $x^3$ 조건**\\n$9 - 2k = 3$이면 $k = 3$\\n\\n**Step 3. 계수 계산**\\n$$_9C_3 \\cdot (-1)^3 = 84 \\cdot (-1) = -84$$\\n\\n**Step 4. 검증**\\n$_9C_3 = \\frac{9 \\times 8 \\times 7}{3 \\times 2 \\times 1} = 84$ ✓\\n$(-1)^3 = -1$이므로 부호가 음수입니다. ✓\\n\\n**∴ 답: ① $-84$**\\n\\n④ $84$는 $(-1)^k$의 부호를 빠뜨린 오답입니다.\\n\\n**💡 포인트:** $(a - b)^n$의 전개에서 $b$의 지수 $k$가 홀수이면 음수, 짝수이면 양수입니다. 부호 확인을 반드시 하세요.",
