    "answer": 10,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** $_nC_r$이 최대가 되는 $r$은 $n$이 짝수이면 $r = \\frac{n}{2}$, 홀수이면 $r = \\frac{n-1}{2}$ 또는 $r = \\frac{n+1}{2}$ (두 값이 같음)입니다.\\n\\n**Step 1. 인접항 비 분석**\\n$$\\frac{_{20}C_{r+1}}{_{20}C_r} = \\frac{20-r}{r+1}$$\\n이 비가 1보다 클 조건: $20 - r > r + 1$, 즉 $r < 9.5$\\n이 비가 1일 조건: $20 - r = r + 1$은 $r = 9.5$로 정수가 아님.\\n\\n따라서 $r \\leq 9$이면 $_{20}C_{r+1} > _{20}C_r$이고, $r \\geq 10$이면 $_{20}C_{r+1} < _{20}C_r$입니다.\\n\\n**Step 2. 결론**\\n$_{20}C_r$은 $r = 10$에서 최대입니다.\\n\\n**Step 3. 검증**\\n$_{20}C_9 = 167960$, $_{20}C_{10} = 184756$, $_{20}C_{11} = 167960$\\n$_{20}C_{10} > _{20}C_9$이고 $_{20}C_{10} > _{20}C_{11}$ ✓\\n\\n**∴ 답: 10**\\n\\n**💡 포인트:** $n$이 짝수이면 최대 이항계수는 유일하게 $r = \\frac{n}{2}$에서, 홀수이면 $r = \\frac{n \\pm 1}{2}$에서 같은 최댓값을 가집니다.",
