    "explanation": "**[풀이]**\\n\\n**핵심 개념:** $k \\cdot _nC_k = n \\cdot _{n-1}C_{k-1}$이라는 항등식을 사용합니다.\\n\\n**Step 1. 항등식 적용**\\n$$k \\cdot _{10}C_k = 10 \\cdot _9C_{k-1}$$\\n이것은 $k \\cdot \\frac{10!}{k!(10-k)!} = 10 \\cdot \\frac{9!}{(k-1)!(10-k)!}$로 확인됩니다.\\n\\n**Step 2. 합 계산**\\n$$\\sum_{k=0}^{10} k \\cdot _{10}C_k = \\sum_{k=1}^{10} 10 \\cdot _9C_{k-1} = 10 \\sum_{j=0}^{9} _9C_j = 10 \\cdot 2^9$$\\n($k = 0$인 항은 $0 \\cdot _{10}C_0 = 0$이므로 $k = 1$부터 시작)\\n\\n**Step 3. 최종 계산**\\n$$10 \\cdot 2^9 = 10 \\cdot 512 = 5120$$\\n\\n**Step 4. 검증 — 미분 이용**\\n$(1+x)^{10} = \\sum _nC_k x^k$의 양변을 미분:\\n$10(1+x)^9 = \\sum k \\cdot _{10}C_k x^{k-1}$\\n$x = 1$ 대입: $10 \\cdot 2^9 = \\sum k \\cdot _{10}C_k = 5120$ ✓\\n\\n**∴ 답: ② $5120$**\\n\\n**💡 포인트:** $\\sum k \\cdot _nC_k = n \\cdot 2^{n-1}$. 미분 또는 항등식으로 유도합니다.",
