    "answer": 1,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** $3^{20} = (1 + 2)^{20}$으로 놓고 이항정리를 적용합니다.\\n\\n**Step 1. 이항전개**\\n$$(1+2)^{20} = \\sum_{k=0}^{20} _{20}C_k \\cdot 2^k$$\\n\\n**Step 2. $8 = 2^3$으로 나눈 나머지**\\n$k \\geq 3$인 항은 $2^k$가 $2^3 = 8$의 배수이므로 나머지에 기여하지 않습니다.\\n\\n나머지에 기여하는 항:\\n$$_{20}C_0 \\cdot 2^0 + _{20}C_1 \\cdot 2^1 + _{20}C_2 \\cdot 2^2$$\\n$$= 1 + 20 \\cdot 2 + 190 \\cdot 4 = 1 + 40 + 760 = 801$$\\n\\n**Step 3. 801을 8로 나눈 나머지**\\n$$801 = 100 \\times 8 + 1$$\\n나머지: **1**\\n\\n**Step 4. 검증**\\n$3^2 = 9 \\equiv 1 \\pmod{8}$이므로 $3^{20} = (3^2)^{10} \\equiv 1^{10} = 1 \\pmod{8}$ ✓\\n\\n**∴ 답: 1**\\n\\n**💡 포인트:** 이항정리로 나머지를 구할 때, 제수의 배수가 되는 항을 무시합니다. 합동식을 이용한 검증도 병행하세요.",
