    "answer": 1,
    "explanation": "**[풀이]**\\n\\n**핵심 개념:** 다항정리에서 $(x_1 + x_2 + \\cdots + x_k)^n$의 서로 다른 항의 수는 $a_1 + a_2 + \\cdots + a_k = n$ ($a_i \\geq 0$)의 해의 수, 즉 $_kH_n$입니다.\\n\\n**Step 1. 다항정리 분석**\\n$(x + y + z)^5$를 전개하면 각 항은 $x^a y^b z^c$ ($a + b + c = 5$, $a, b, c \\geq 0$) 형태입니다.\\n\\n**Step 2. 서로 다른 항의 수**\\n$a + b + c = 5$의 음이 아닌 정수해의 수:\\n$$_3H_5 = _{3+5-1}C_5 = _7C_5 = _7C_2 = \\frac{7 \\times 6}{2} = 21$$\\n\\n**Step 3. 검증**\\n$k = 2$일 때 $(x+y)^5$의 항 수: $a + b = 5$의 해 6개이고, $_2H_5 = _6C_5 = 6$과 일치. ✓\\n\\n**∴ 답: ② 21**\\n\\n⑤ 125는 $5^3$으로 관련 없는 값이고, ③ 35는 $_7C_3 = 35$로 $(x+y+z)^5$이 아닌 다른 경우입니다.\\n\\n사실 $_7C_5 = _7C_2 = 21$이고 $_7C_3 = 35$는 다른 값이므로 주의하세요.\\n\\n**💡 포인트:** 다항정리의 항 수 = 중복조합 = 부정방정식의 음이 아닌 정수해의 수. 세 개념이 연결됩니다.",
