    "explanation": "**[풀이]**\\n\\n**핵심 개념:** $\\sum k^2 \\cdot _nC_k$를 구할 때, $k^2 = k(k-1) + k$로 분해합니다.\\n\\n**Step 1. 분해**\\n$$\\sum_{k=0}^{10} k^2 \\cdot _{10}C_k = \\sum k(k-1) \\cdot _{10}C_k + \\sum k \\cdot _{10}C_k$$\\n\\n**Step 2. 첫째 합: $\\sum k(k-1) \\cdot _{10}C_k$**\\n$k(k-1) \\cdot _nC_k = n(n-1) \\cdot _{n-2}C_{k-2}$를 이용합니다.\\n$$\\sum_{k=2}^{10} 10 \\cdot 9 \\cdot _8C_{k-2} = 90 \\sum_{j=0}^{8} _8C_j = 90 \\cdot 2^8 = 90 \\cdot 256 = 23040$$\\n\\n**Step 3. 둘째 합: $\\sum k \\cdot _{10}C_k$**\\n이전에 구한 바와 같이:\\n$$10 \\cdot 2^9 = 5120$$\\n\\n**Step 4. 최종 합산**\\n$$23040 + 5120 = 28160$$\\n\\n**Step 5. 검증 — 이계 미분**\\n$(1+x)^{10}$의 양변에 $x \\frac{d}{dx}$를 적용:\\n$x \\cdot 10(1+x)^9 = \\sum k \\cdot _{10}C_k x^k$\\n다시 $x \\frac{d}{dx}$를 적용:\\n$\\sum k^2 \\cdot _{10}C_k x^k = x \\frac{d}{dx}[10x(1+x)^9]$\\n$= x[10(1+x)^9 + 90x(1+x)^8]$\\n$x = 1$ 대입:\\n$= 1 \\cdot [10 \\cdot 512 + 90 \\cdot 256] = 5120 + 23040 = 28160$ ✓\\n\\n**∴ 답: ③ $28160$**\\n\\n**💡 포인트:** $k^2 = k(k-1) + k$로 분해하면 알려진 공식을 활용할 수 있습니다. 일반적으로 $\\sum k^2 _nC_k = n(n-1)2^{n-2} + n \\cdot 2^{n-1}$입니다.",
