    "explanation": "**[풀이]**\n\n**핵심 개념:** 확률의 기본 정의 — 사건 $A$가 일어날 확률은 다음과 같습니다.\n$$P(A) = \\frac{\\text{사건 } A\\text{에 해당하는 경우의 수}}{\\text{전체 경우의 수}}$$\n\n**Step 1. 전체 경우의 수 파악**\n주사위 한 개를 던질 때 나올 수 있는 눈: $\\{1, 2, 3, 4, 5, 6\\}$\n전체 경우의 수 = $6$\n\n**Step 2. 사건 파악 — 3의 배수인 눈**\n$1$부터 $6$ 사이에서 3의 배수는 $3, 6$입니다.\n사건에 해당하는 경우의 수 = $2$\n\n**Step 3. 확률 계산**\n$$P(\\text{3의 배수}) = \\frac{2}{6} = \\frac{1}{3}$$\n\n**Step 4. 검증**\n$\\{1,2,3,4,5,6\\}$ 중 3의 배수는 $3$과 $6$ 두 개뿐입니다. $\\frac{2}{6}=\\frac{1}{3}$은 올바릅니다. ✓\n\n**∴ 답: ② 1/3**\n\n① $\\frac{1}{6}$은 특정 눈 하나가 나올 확률이고, ③ $\\frac{1}{2}$은 짝수 또는 홀수가 나올 확률입니다.\n\n**💡 포인트:** 주사위 문제에서는 전체 표본공간 $\\{1,2,3,4,5,6\\}$을 명확히 쓰고, 조건에 맞는 원소를 세면 됩니다.\n\n**보충:** 주사위의 각 눈이 나올 확률은 $\\frac{1}{6}$로 모두 같습니다(등확률 모형). 3의 배수는 $3 = 3 \\times 1$, $6 = 3 \\times 2$로 두 개이며, 6의 배수는 $6$ 하나뿐입니다. 배수 조건을 정확히 파악하는 것이 핵심입니다.",
