    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립사건의 곱셈 정리 — 두 사건 $A$, $B$가 독립이면:\n$$P(A \\cap B) = P(A) \\times P(B)$$\n\n**Step 1. 각 시행의 확률**\n동전 한 개를 던질 때 앞면이 나올 확률: $P(\\text{앞면}) = \\frac{1}{2}$\n\n**Step 2. 독립성 확인**\n첫 번째 던지기의 결과는 두 번째 던지기에 영향을 주지 않습니다. 따라서 두 시행은 **독립**입니다.\n\n**Step 3. 곱셈 정리 적용**\n$$P(\\text{두 번 모두 앞면}) = P(\\text{1회 앞면}) \\times P(\\text{2회 앞면}) = \\frac{1}{2} \\times \\frac{1}{2} = \\frac{1}{4}$$\n\n**Step 4. 검증 — 표본공간 나열**\n동전 2회의 모든 결과: $\\{(앞,앞), (앞,뒤), (뒤,앞), (뒤,뒤)\\}$ → 4가지\n두 번 모두 앞면: $\\{(앞,앞)\\}$ → 1가지\n$P = \\frac{1}{4}$ ✓\n\n**∴ 답: ② 1/4**\n\n④ $\\frac{1}{2}$은 한 번만 앞면이 나올 확률을 구한 것이고, ① $\\frac{1}{8}$은 동전 3회에서 모두 앞면일 확률입니다.\n\n**💡 포인트:** 독립 시행을 반복할 때는 각 시행의 확률을 곱합니다. 동전 $n$번 던져 모두 앞면일 확률은 $\\left(\\frac{1}{2}\\right)^n$입니다.",
