    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 확률의 덧셈 정리 — 두 사건 $A$, $B$에 대해:\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n**Step 1. 각 사건 정의**\n사건 $A$: 짝수의 눈 → $\\{2, 4, 6\\}$ → $P(A) = \\frac{3}{6} = \\frac{1}{2}$\n사건 $B$: 5 이상의 눈 → $\\{5, 6\\}$ → $P(B) = \\frac{2}{6} = \\frac{1}{3}$\n\n**Step 2. 교사건 확인**\n$A \\cap B$: 짝수이면서 5 이상 → $\\{6\\}$ → $P(A \\cap B) = \\frac{1}{6}$\n\n**Step 3. 덧셈 정리 적용**\n$$P(A \\cup B) = \\frac{1}{2} + \\frac{1}{3} - \\frac{1}{6} = \\frac{3}{6} + \\frac{2}{6} - \\frac{1}{6} = \\frac{4}{6} = \\frac{2}{3}$$\n\n**Step 4. 검증 — 직접 나열**\n$A \\cup B = \\{2, 4, 5, 6\\}$ → 4개\n$P(A \\cup B) = \\frac{4}{6} = \\frac{2}{3}$ ✓\n\n**∴ 답: ③ 2/3**\n\n④ $\\frac{5}{6}$은 교사건을 빼지 않고 $\\frac{3}{6}+\\frac{2}{6}=\\frac{5}{6}$으로 계산한 오답입니다.\n\n**💡 포인트:** 합사건 $P(A \\cup B)$를 구할 때는 반드시 교사건 $P(A \\cap B)$를 빼야 중복 계산을 방지합니다.",
