    "explanation": "**[풀이]**\n\n**핵심 개념:** 확률의 기본 정의를 이용합니다.\n$$P(A) = \\frac{\\text{사건에 해당하는 경우의 수}}{\\text{전체 경우의 수}}$$\n\n**Step 1. 전체 경우의 수**\n주사위 한 개를 던질 때 나올 수 있는 모든 눈: $\\{1, 2, 3, 4, 5, 6\\}$ → 6가지\n\n**Step 2. 홀수인 눈**\n홀수: $\\{1, 3, 5\\}$ → 3가지\n\n**Step 3. 확률 계산**\n$$P(\\text{홀수}) = \\frac{3}{6} = \\frac{1}{2}$$\n\n**Step 4. 검증 — 여사건 활용**\n짝수의 눈: $\\{2, 4, 6\\}$ → 3가지 → $P(\\text{짝수}) = \\frac{3}{6} = \\frac{1}{2}$\n$P(\\text{홀수}) = 1 - P(\\text{짝수}) = 1 - \\frac{1}{2} = \\frac{1}{2}$ ✓\n\n홀수와 짝수는 각각 3개씩이므로 확률이 같다는 것은 직관적으로도 타당합니다.\n\n**∴ 답: ③ 1/2**\n\n② $\\frac{1}{3}$은 3의 배수가 나올 확률($\\{3,6\\}$)이고, 홀수의 확률과 혼동하지 마세요.\n\n**💡 포인트:** 주사위에서 홀수와 짝수는 각각 3개로 같으므로 확률이 $\\frac{1}{2}$입니다. 여사건 $P(A^c) = 1 - P(A)$로도 확인할 수 있습니다.\n\n**보충:** 주사위 확률의 핵심 패턴을 정리하면: 짝수/홀수 = $\\frac{1}{2}$, 3의 배수 = $\\frac{1}{3}$, 특정 숫자 = $\\frac{1}{6}$. 이러한 기본 확률을 암기해 두면 복합 문제에서 빠르게 활용할 수 있습니다.",
