    "type": "확률의 덧셈·곱셈",
    "problem": "1부터 10까지 자연수가 적힌 카드 10장에서 1장을 뽑을 때, 소수가 적힌 카드를 뽑을 확률을 구하시오. (답을 기약분수로 나타낼 때, 분자와 분모의 합을 구하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 7,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 확률의 기본 정의를 적용하며, 10 이하의 소수를 정확히 파악해야 합니다.\n\n**Step 1. 전체 경우의 수**\n1부터 10까지 적힌 카드 10장에서 1장을 뽑는 경우의 수 = $10$\n\n**Step 2. 10 이하의 소수 나열**\n소수(prime number): 1보다 크고, 1과 자기 자신만을 약수로 가지는 자연수\n$2, 3, 5, 7$ → **4개**\n(주의: 1은 소수가 아닙니다.)\n\n**Step 3. 확률 계산**\n$$P(\\text{소수}) = \\frac{4}{10} = \\frac{2}{5}$$\n\n**Step 4. 분자 + 분모**\n기약분수 $\\frac{2}{5}$에서 분자 = $2$, 분모 = $5$\n$$2 + 5 = 7$$\n\n**Step 5. 검증**\n$\\{2, 3, 5, 7\\}$은 모두 소수 맞습니다. $\\gcd(2, 5) = 1$이므로 기약분수도 맞습니다. ✓\n\n**∴ 답: 7**\n\n**💡 포인트:** 10 이하 소수는 $2, 3, 5, 7$의 4개입니다. 1은 소수가 아님에 주의하세요. 단답형에서 확률이 분수이면 '분자+분모'로 묻는 유형이 자주 나옵니다.\n\n**참고:** 소수의 정의를 정확히 알아야 합니다. 소수는 1보다 큰 자연수 중 1과 자기 자신만을 약수로 가지는 수입니다. 4($=2 \\times 2$), 6($=2 \\times 3$), 8, 9, 10은 소수가 아닙니다. 20 이하의 소수: $2, 3, 5, 7, 11, 13, 17, 19$",
    "difficulty": "lv1",
