    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립 시행의 반복에서 특정 횟수만큼 성공할 확률은 이항분포 공식과 동일합니다.\n$$P(X = k) = \\binom{n}{k} p^k (1-p)^{n-k}$$\n\n**Step 1. 조건 정리**\n- 동전을 $n = 3$번 던짐\n- 앞면이 나올 확률 $p = \\frac{1}{2}$\n- 정확히 $k = 1$번 앞면\n\n**Step 2. 경우의 수 계산**\n3번 중 앞면이 1번 나오는 위치를 고르는 방법: $\\binom{3}{1} = 3$\n\n**Step 3. 확률 계산**\n$$P(X=1) = \\binom{3}{1} \\left(\\frac{1}{2}\\right)^1 \\left(\\frac{1}{2}\\right)^2 = 3 \\times \\frac{1}{2} \\times \\frac{1}{4} = \\frac{3}{8}$$\n\n**Step 4. 기약분수 확인 및 답**\n$\\gcd(3, 8) = 1$이므로 $\\frac{3}{8}$은 기약분수입니다.\n$$p + q = 3 + 8 = 11$$\n\n**Step 5. 검증 — 직접 나열**\n모든 경우: $\\{HHH, HHT, HTH, HTT, THH, THT, TTH, TTT\\}$ → 8가지\n앞면 정확히 1번: $\\{HTT, THT, TTH\\}$ → 3가지\n$P = \\frac{3}{8}$ ✓\n\n**∴ 답: 11**\n\n**💡 포인트:** 동전 $n$번 던져 앞면 $k$번 → $\\binom{n}{k} \\times (\\frac{1}{2})^n$입니다. 전체 경우의 수는 $2^n$입니다.\n\n**보충:** 동전 3번의 확률 분포: 앞면 0번 = $\\frac{1}{8}$, 1번 = $\\frac{3}{8}$, 2번 = $\\frac{3}{8}$, 3번 = $\\frac{1}{8}$. 합은 $\\frac{1+3+3+1}{8}=1$입니다. 이 분포는 이항분포 $B(3, \\frac{1}{2})$와 같습니다.",
