    "explanation": "**[풀이]**\n\n**핵심 개념:** 배반사건의 덧셈 정리 — 두 사건 $A$, $B$가 동시에 일어날 수 없으면($A \\cap B = \\emptyset$):\n$$P(A \\cup B) = P(A) + P(B)$$\n\n**Step 1. 각 사건 정의**\n사건 $A$: 2 이하의 눈 → $\\{1, 2\\}$ → $P(A) = \\frac{2}{6} = \\frac{1}{3}$\n사건 $B$: 5 이상의 눈 → $\\{5, 6\\}$ → $P(B) = \\frac{2}{6} = \\frac{1}{3}$\n\n**Step 2. 배반 여부 확인**\n$A \\cap B = \\{1,2\\} \\cap \\{5,6\\} = \\emptyset$\n두 사건은 동시에 일어날 수 없으므로 **배반사건**입니다.\n\n**Step 3. 덧셈 정리 적용**\n$$P(A \\cup B) = P(A) + P(B) = \\frac{1}{3} + \\frac{1}{3} = \\frac{2}{3}$$\n\n**Step 4. 검증 — 직접 나열**\n$A \\cup B = \\{1, 2, 5, 6\\}$ → 4개\n$P = \\frac{4}{6} = \\frac{2}{3}$ ✓\n\n**∴ 답: ③ 2/3**\n\n여사건 관점: 2 이하도 5 이상도 아닌 눈 = $\\{3, 4\\}$ → $P = \\frac{2}{6} = \\frac{1}{3}$이므로 $1 - \\frac{1}{3} = \\frac{2}{3}$으로도 확인됩니다.\n\n**💡 포인트:** 두 사건이 배반이면 교사건이 공집합이므로 단순히 확률을 더하면 됩니다. 배반 여부를 먼저 확인하는 습관을 기르세요.",
