    "explanation": "**[풀이]**\n\n**핵심 개념:** 여사건의 확률 — 사건 $A$가 일어나지 않을 확률은:\n$$P(A^c) = 1 - P(A)$$\n\n**Step 1. 사건 정의**\n사건 $A$: 4 이하의 눈 → $\\{1, 2, 3, 4\\}$ → $P(A) = \\frac{4}{6} = \\frac{2}{3}$\n\n**Step 2. 여사건의 확률**\n'4 이하가 나오지 않는다' = 4 이하의 여사건 = 5 이상의 눈\n$$P(A^c) = 1 - P(A) = 1 - \\frac{2}{3} = \\frac{1}{3}$$\n\n**Step 3. 검증 — 직접 나열**\n4 이하가 아닌 눈: $\\{5, 6\\}$ → 2개\n$P = \\frac{2}{6} = \\frac{1}{3}$ ✓\n\n**∴ 답: ② 1/3**\n\n④ $\\frac{2}{3}$은 '4 이하의 눈이 나올 확률', 즉 사건 자체의 확률이지 여사건의 확률이 아닙니다.\n\n**💡 포인트:** '~가 아닐 확률', '~가 일어나지 않을 확률'이 나오면 여사건 $P(A^c) = 1 - P(A)$를 먼저 떠올리세요. 특히 '적어도 하나' 유형에서 여사건이 매우 유용합니다.\n\n**보충:** 여사건은 확률의 가장 강력한 도구 중 하나입니다. 직접 세기 어려운 경우에 '일어나지 않는 경우'를 세서 1에서 빼는 전략으로, 복잡한 문제를 간단하게 만들어 줍니다. 특히 '적어도', '최소', '이상' 등의 표현이 나오면 여사건 활용을 고려하세요.",
