    "explanation": "**[풀이]**\n\n**핵심 개념:** 주사위 2개를 던질 때 전체 경우의 수는 $6 \\times 6 = 36$이고, 조건에 맞는 순서쌍을 나열합니다.\n\n**Step 1. 전체 경우의 수**\n두 주사위의 눈을 $(a, b)$로 나타내면 전체 = $6 \\times 6 = 36$\n\n**Step 2. 두 눈의 합이 4인 경우**\n$a + b = 4$를 만족하는 순서쌍:\n- $(1, 3)$, $(2, 2)$, $(3, 1)$ → **3가지**\n\n**Step 3. 확률 계산**\n$$P(\\text{합 = 4}) = \\frac{3}{36} = \\frac{1}{12}$$\n\n**Step 4. 검증**\n합이 2인 경우: $(1,1)$ → 1가지 = $\\frac{1}{36}$\n합이 3인 경우: $(1,2),(2,1)$ → 2가지 = $\\frac{2}{36}$\n합이 4인 경우: 3가지 = $\\frac{3}{36}$ → 합이 커질수록 경우의 수가 증가하는 패턴과 부합합니다. ✓\n\n**∴ 답: ② 1/12**\n\n③ $\\frac{1}{9}$은 $\\frac{4}{36}$(합이 5인 경우)와 혼동한 것이고, ⑤ $\\frac{5}{36}$은 합이 6인 경우입니다.\n\n**💡 포인트:** 주사위 2개 문제에서는 순서쌍 $(a,b)$를 직접 나열하는 것이 가장 확실합니다. 전체가 36이라는 것을 기억하세요.\n\n**보충:** 주사위 2개의 합별 경우의 수를 외워 두면 편리합니다: 합2→1, 합3→2, 합4→3, 합5→4, 합6→5, 합7→6, 합8→5, 합9→4, 합10→3, 합11→2, 합12→1. 합이 7일 때 6가지로 가장 많습니다.",
