    "answer": 3,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 배반사건의 덧셈 정리\n두 사건 $A$, $B$가 배반($A \\cap B = \\emptyset$)이면:\n$$P(A \\cup B) = P(A) + P(B)$$\n\n**Step 1. 배반사건의 의미 확인**\n$A$와 $B$가 배반이라 함은 두 사건이 동시에 일어날 수 없다는 뜻입니다.\n$$P(A \\cap B) = 0$$\n\n**Step 2. 합사건의 확률**\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n$$= 0.3 + 0.5 - 0 = 0.8$$\n\n**Step 3. 검증**\n$0 \\le P(A \\cup B) = 0.8 \\le 1$ ✓\n배반이므로 $P(A \\cup B) = P(A) + P(B)$는 단순 합이고, $0.8 < 1$이므로 확률값으로 타당합니다. ✓\n\n**∴ 답: ④ 0.8**\n\n① $0.15$는 $P(A) \\times P(B)$를 구한 것으로, 독립사건의 교사건과 혼동한 오답입니다.\n③ $0.65$는 출처 불명의 계산 오류입니다.\n\n**💡 포인트:** 배반사건과 독립사건을 혼동하지 마세요. 배반 → $P(A \\cap B) = 0$, 독립 → $P(A \\cap B) = P(A)P(B)$입니다. 배반이면서 독립인 경우는 $P(A)=0$ 또는 $P(B)=0$인 경우뿐입니다.\n\n**보충:** 배반사건은 동시에 일어날 수 없는 관계이고, 독립사건은 서로 영향을 주지 않는 관계입니다. 예를 들어 주사위에서 '1이 나옴'과 '6이 나옴'은 배반이지만, '첫 번째 주사위 1'과 '두 번째 주사위 6'은 독립입니다.",
