    "problem": "주사위 두 개를 동시에 던질 때, 적어도 하나가 6인 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, $\\frac{p}{q}$는 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 47,
    "explanation": "**[풀이]**\n\n**핵심 개념:** '적어도 하나'가 나오면 **여사건**을 이용하는 것이 효율적입니다.\n$$P(\\text{적어도 하나 6}) = 1 - P(\\text{둘 다 6이 아님})$$\n\n**Step 1. 여사건 정의**\n여사건: 두 주사위 모두 6이 아닌 경우\n\n**Step 2. 여사건의 확률**\n주사위 하나에서 6이 아닌 눈: $\\{1,2,3,4,5\\}$ → 확률 $\\frac{5}{6}$\n두 주사위는 독립이므로:\n$$P(\\text{둘 다 6 아님}) = \\frac{5}{6} \\times \\frac{5}{6} = \\frac{25}{36}$$\n\n**Step 3. 적어도 하나 6인 확률**\n$$P(\\text{적어도 하나 6}) = 1 - \\frac{25}{36} = \\frac{11}{36}$$\n\n**Step 4. 기약분수 확인**\n$11$은 소수이고 $36 = 2^2 \\times 3^2$이므로 $\\gcd(11, 36) = 1$ → 기약분수입니다.\n$p = 11$, $q = 36$\n$$p + q = 11 + 36 = 47$$\n\n**Step 5. 검증 — 직접 세기**\n6이 포함된 순서쌍: $(6,1),(6,2),\\ldots,(6,6),(1,6),(2,6),\\ldots,(5,6)$\n$= 6 + 5 = 11$가지 (중복 $(6,6)$ 주의)\n$P = \\frac{11}{36}$ ✓\n\n**∴ 답: 47**\n\n**💡 포인트:** '적어도 하나' → 여사건(하나도 없는 경우)의 확률을 1에서 빼면 됩니다. 직접 세는 것보다 훨씬 효율적입니다.",
