    "problem": "두 사건 $A$, $B$에 대해 $P(A) = 0.4$, $P(B) = 0.5$, $P(A \\cap B) = 0.2$일 때, $P(A \\cup B)$의 값에 10을 곱한 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 7,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 확률의 덧셈 정리(일반형)\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n**Step 1. 덧셈 정리 적용**\n$$P(A \\cup B) = 0.4 + 0.5 - 0.2 = 0.7$$\n\n**Step 2. 최종 답**\n$$P(A \\cup B) \\times 10 = 0.7 \\times 10 = 7$$\n\n**Step 3. 검증**\n확률의 기본 성질을 확인합니다:\n- $P(A \\cap B) = 0.2 \\le \\min(P(A), P(B)) = 0.4$ ✓\n- $P(A \\cup B) = 0.7 \\le 1$ ✓\n- $P(A \\cup B) = 0.7 \\ge \\max(P(A), P(B)) = 0.5$ ✓\n\n또한 $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$에서 벤 다이어그램으로 생각하면:\n- $A$만: $0.4 - 0.2 = 0.2$\n- $B$만: $0.5 - 0.2 = 0.3$\n- 교집합: $0.2$\n- 합집합: $0.2 + 0.3 + 0.2 = 0.7$ ✓\n\n**∴ 답: 7**\n\n**💡 포인트:** 덧셈 정리는 확률의 가장 기본 공식입니다. 검증할 때는 벤 다이어그램으로 각 영역의 확률을 구해 합이 맞는지 확인하세요.\n\n**보충:** 벤 다이어그램에서 $A \\cup B$는 세 영역으로 나뉩니다: $A$만($P(A) - P(A \\cap B)$), $B$만($P(B) - P(A \\cap B)$), 교집합($P(A \\cap B)$). 이 세 영역의 합이 $P(A \\cup B)$입니다. 보기 검증에 매우 유용한 방법입니다.",
