    "problem": "동전 한 개를 4번 던질 때, 앞면이 적어도 1번 나올 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, $\\frac{p}{q}$는 기약분수)",
    "answerType": "short",
