    "answer": 31,
    "explanation": "**[풀이]**\n\n**핵심 개념:** '적어도 1번' → 여사건 활용\n$$P(\\text{적어도 1번 앞면}) = 1 - P(\\text{모두 뒷면})$$\n\n**Step 1. 여사건 — 모두 뒷면**\n동전 4번 모두 뒷면이 나올 확률:\n$$P(\\text{4번 모두 뒷면}) = \\left(\\frac{1}{2}\\right)^4 = \\frac{1}{16}$$\n\n**Step 2. 적어도 1번 앞면**\n$$P(\\text{적어도 1번 앞면}) = 1 - \\frac{1}{16} = \\frac{15}{16}$$\n\n**Step 3. 기약분수 확인**\n$15 = 3 \\times 5$, $16 = 2^4$이므로 $\\gcd(15, 16) = 1$ → 기약분수입니다.\n$p = 15$, $q = 16$\n$$p + q = 15 + 16 = 31$$\n\n**Step 4. 검증**\n동전 4번의 모든 결과: $2^4 = 16$가지\n모두 뒷면: $\\{TTTT\\}$ → 1가지\n앞면이 적어도 1번: $16 - 1 = 15$가지\n$P = \\frac{15}{16}$ ✓\n\n**∴ 답: 31**\n\n**💡 포인트:** '적어도 하나' 유형은 여사건('하나도 없는 경우')을 빼는 것이 정석입니다. 동전 $n$번 던져 적어도 1번 앞면일 확률은 $1 - (\\frac{1}{2})^n$입니다.\n\n**보충:** 동전 횟수별 '적어도 1번 앞면' 확률: $n=1$ → $\\frac{1}{2}$, $n=2$ → $\\frac{3}{4}$, $n=3$ → $\\frac{7}{8}$, $n=4$ → $\\frac{15}{16}$, $n=5$ → $\\frac{31}{32}$. $n$이 커질수록 1에 빠르게 수렴합니다.",
