    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립사건의 성질과 덧셈 정리를 결합하여 미지의 확률을 구합니다.\n\n**Step 1. $P(A)$ 구하기**\n$$P(A) = 1 - P(A^c) = 1 - \\frac{2}{3} = \\frac{1}{3}$$\n\n**Step 2. 독립 + 덧셈 정리 세우기**\n$A$와 $B$가 독립이므로 $P(A \\cap B) = P(A) \\cdot P(B)$\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n$$\\frac{5}{6} = \\frac{1}{3} + P(B) - \\frac{1}{3} \\cdot P(B)$$\n\n**Step 3. $P(B)$ 풀기**\n$P(B) = x$로 놓으면:\n$$\\frac{5}{6} = \\frac{1}{3} + x - \\frac{x}{3} = \\frac{1}{3} + \\frac{2x}{3}$$\n$$\\frac{5}{6} - \\frac{1}{3} = \\frac{2x}{3}$$\n$$\\frac{5}{6} - \\frac{2}{6} = \\frac{2x}{3}$$\n$$\\frac{3}{6} = \\frac{2x}{3}$$\n$$\\frac{1}{2} = \\frac{2x}{3}$$\n$$x = \\frac{1}{2} \\times \\frac{3}{2} = \\frac{3}{4}$$\n\n**Step 4. 검증**\n$P(A \\cup B) = \\frac{1}{3} + \\frac{3}{4} - \\frac{1}{3} \\times \\frac{3}{4} = \\frac{1}{3} + \\frac{3}{4} - \\frac{1}{4} = \\frac{1}{3} + \\frac{1}{2} = \\frac{2}{6} + \\frac{3}{6} = \\frac{5}{6}$ ✓\n$0 \\le P(B) = \\frac{3}{4} \\le 1$ ✓\n\n**∴ 답: ③ 3/4**\n\n① $\\frac{5}{12}$은 $\\frac{2x}{3} = \\frac{5}{12}$을 $x$로 착각한 오답이고, ② $\\frac{1}{2}$은 중간 계산값 $\\frac{1}{2}$을 답으로 잘못 택한 것입니다.\n\n**💡 포인트:** 독립 + 합사건 문제에서는 $P(A \\cap B) = P(A)P(B)$를 대입하여 미지의 확률에 대한 일차방정식을 세웁니다.",
