    "explanation": "**[풀이]**\n\n**핵심 개념:** 특정 조건을 만족하는 조합 / 전체 조합\n\n**Step 1. 전체 경우의 수**\n$$\\binom{10}{4} = \\frac{10!}{4! \\cdot 6!} = 210$$\n\n**Step 2. 특정 2명이 모두 포함되는 경우의 수**\n특정 2명은 이미 포함되어야 하므로, 나머지 8명 중에서 2명을 더 뽑으면 됩니다.\n$$\\binom{8}{2} = \\frac{8 \\times 7}{2} = 28$$\n\n**Step 3. 확률 계산**\n$$P = \\frac{28}{210} = \\frac{2}{15}$$\n\n**Step 4. 기약분수 확인**\n$\\gcd(2, 15) = 1$ → 기약분수\n$p = 2$, $q = 15$\n$$p + q = 2 + 15 = 17$$\n\n**Step 5. 검증**\n$\\frac{28}{210}$에서 $28 = 4 \\times 7$, $210 = 2 \\times 3 \\times 5 \\times 7$이므로:\n$\\frac{28}{210} = \\frac{4}{30} = \\frac{2}{15}$ ✓\n\n**∴ 답: 17**\n\n**💡 포인트:** '특정 인원이 반드시 포함' → 그 인원을 고정하고 나머지만 뽑는 전략을 씁니다.\n\n**보충:** 반대로 '특정 인원이 반드시 제외'되는 경우는, 그 인원을 빼고 나머지에서 뽑으면 됩니다. 예를 들어 특정 2명이 모두 제외되려면 나머지 8명에서 4명을 뽑는 $\\binom{8}{4} = 70$가지입니다. 포함/제외 조건이 있는 조합 문제에서는 '고정 후 나머지 뽑기' 전략이 핵심입니다.",
