    "problem": "한 개의 주사위를 3번 던질 때, 나온 눈의 최댓값이 5일 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, $\\frac{p}{q}$는 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 277,
    "explanation": "**[풀이]**\n\n**핵심 개념:** '최댓값이 정확히 $k$'인 확률 = '최댓값이 $k$ 이하' - '최댓값이 $k-1$ 이하'\n$$P(\\max = k) = P(\\max \\le k) - P(\\max \\le k-1)$$\n\n**Step 1. 최댓값이 5 이하인 확률**\n3번 모두 5 이하의 눈($\\{1,2,3,4,5\\}$)이 나와야 합니다.\n$$P(\\max \\le 5) = \\left(\\frac{5}{6}\\right)^3 = \\frac{125}{216}$$\n\n**Step 2. 최댓값이 4 이하인 확률**\n3번 모두 4 이하의 눈($\\{1,2,3,4\\}$)이 나와야 합니다.\n$$P(\\max \\le 4) = \\left(\\frac{4}{6}\\right)^3 = \\left(\\frac{2}{3}\\right)^3 = \\frac{8}{27} = \\frac{64}{216}$$\n\n**Step 3. 최댓값이 정확히 5인 확률**\n$$P(\\max = 5) = \\frac{125}{216} - \\frac{64}{216} = \\frac{61}{216}$$\n\n**Step 4. 기약분수 확인**\n$61$은 소수이고 $216 = 6^3 = 2^3 \\times 3^3$이므로 $\\gcd(61, 216) = 1$ → 기약분수입니다.\n$p = 61$, $q = 216$\n$$p + q = 61 + 216 = 277$$\n\n**Step 5. 검증**\n전체 경우의 수: $6^3 = 216$\n3개의 눈이 모두 5 이하: $5^3 = 125$가지\n3개의 눈이 모두 4 이하: $4^3 = 64$가지\n최댓값이 정확히 5: $125 - 64 = 61$가지 ✓\n\n**∴ 답: 277**\n\n**💡 포인트:** '최댓값이 정확히 $k$' 유형은 누적확률의 차이로 구합니다. 이 기법은 수능에서 자주 출제됩니다.",
