    "explanation": "**[풀이]**\n\n**핵심 개념:** 세 수의 합이 짝수가 되려면 홀수가 0개 또는 2개여야 합니다.\n$$\\text{짝+짝+짝 = 짝}, \\quad \\text{홀+홀+짝 = 짝}$$\n\n**Step 1. 전체 경우의 수**\n$$\\binom{9}{3} = 84$$\n\n**Step 2. 1~9에서 짝수와 홀수**\n짝수: $\\{2, 4, 6, 8\\}$ → 4개\n홀수: $\\{1, 3, 5, 7, 9\\}$ → 5개\n\n**Step 3. 합이 짝수인 경우 분류**\n\n**(1) 세 수 모두 짝수 (짝짝짝):**\n$$\\binom{4}{3} = 4$$\n\n**(2) 홀수 2개 + 짝수 1개 (홀홀짝):**\n$$\\binom{5}{2} \\times \\binom{4}{1} = 10 \\times 4 = 40$$\n\n**Step 4. 합계 및 확률**\n$$4 + 40 = 44$$\n$$P = \\frac{44}{84} = \\frac{11}{21}$$\n\n**Step 5. 검증**\n합이 홀수인 경우: 홀수 1개+짝수 2개 = $\\binom{5}{1}\\binom{4}{2} = 30$, 홀수 3개 = $\\binom{5}{3} = 10$\n합계: $30 + 10 = 40$\n$\\frac{44 + 40}{84} = \\frac{84}{84} = 1$ ✓\n$P(\\text{합 짝수}) = \\frac{44}{84} = \\frac{11}{21}$ ✓\n\n**∴ 답: ① 11/21**\n\n② $\\frac{13}{21}$은 합이 홀수인 경우를 잘못 계산한 것이고, ③ $\\frac{2}{3}$은 짝수가 6개인 경우의 결과입니다.\n\n**💡 포인트:** 합의 짝·홀 판별에서는 뽑힌 수 중 홀수의 개수가 짝수(0개 또는 2개)이면 합이 짝수입니다. 홀수와 짝수의 개수를 먼저 파악한 후 조합을 구하세요.",
