    "problem": "A, B, C 세 사람이 각각 독립적으로 과녁을 한 번씩 쏜다. A가 맞힐 확률은 $\\frac{1}{2}$, B가 맞힐 확률은 $\\frac{1}{3}$, C가 맞힐 확률은 $\\frac{1}{4}$일 때, 적어도 한 명이 맞힐 확률은?",
    "answerType": "choice",
    "choices": [
      "① 1/2",
      "② 7/12",
      "③ 2/3",
      "④ 3/4",
      "⑤ 11/12"
    ],
    "answer": 3,
    "explanation": "**[풀이]**\n\n**핵심 개념:** '적어도 한 명' → 여사건 '아무도 못 맞힘'을 이용합니다. 독립이므로 각 여사건의 곱입니다.\n$$P(\\text{적어도 1명}) = 1 - P(A^c)P(B^c)P(C^c)$$\n\n**Step 1. 각 사람이 못 맞힐 확률**\n$P(A^c) = 1 - \\frac{1}{2} = \\frac{1}{2}$\n$P(B^c) = 1 - \\frac{1}{3} = \\frac{2}{3}$\n$P(C^c) = 1 - \\frac{1}{4} = \\frac{3}{4}$\n\n**Step 2. 아무도 못 맞힐 확률 (독립)**\n$$P(\\text{모두 빗남}) = \\frac{1}{2} \\times \\frac{2}{3} \\times \\frac{3}{4} = \\frac{6}{24} = \\frac{1}{4}$$\n\n**Step 3. 적어도 한 명 맞힐 확률**\n$$P(\\text{적어도 1명}) = 1 - \\frac{1}{4} = \\frac{3}{4}$$\n\n**Step 4. 검증**\n모든 경우를 세밀하게 확인:\n- 정확히 1명: $P(A)P(B^c)P(C^c) + P(A^c)P(B)P(C^c) + P(A^c)P(B^c)P(C) = \\frac{1}{2}\\cdot\\frac{2}{3}\\cdot\\frac{3}{4} + \\frac{1}{2}\\cdot\\frac{1}{3}\\cdot\\frac{3}{4} + \\frac{1}{2}\\cdot\\frac{2}{3}\\cdot\\frac{1}{4} = \\frac{6}{24}+\\frac{3}{24}+\\frac{2}{24} = \\frac{11}{24}$\n- 정확히 2명: $\\frac{1}{2}\\cdot\\frac{1}{3}\\cdot\\frac{3}{4}+\\frac{1}{2}\\cdot\\frac{2}{3}\\cdot\\frac{1}{4}+\\frac{1}{2}\\cdot\\frac{1}{3}\\cdot\\frac{1}{4} = \\frac{3}{24}+\\frac{2}{24}+\\frac{1}{24} = \\frac{6}{24} = \\frac{1}{4}$\n\n잠깐, 재계산:\n- 정확히 2명: $P(A)P(B)P(C^c)+P(A)P(B^c)P(C)+P(A^c)P(B)P(C) = \\frac{1}{2}\\cdot\\frac{1}{3}\\cdot\\frac{3}{4}+\\frac{1}{2}\\cdot\\frac{2}{3}\\cdot\\frac{1}{4}+\\frac{1}{2}\\cdot\\frac{1}{3}\\cdot\\frac{1}{4} = \\frac{3}{24}+\\frac{2}{24}+\\frac{1}{24} = \\frac{6}{24}$\n- 정확히 3명: $\\frac{1}{2}\\cdot\\frac{1}{3}\\cdot\\frac{1}{4} = \\frac{1}{24}$\n- 합: $\\frac{11}{24}+\\frac{6}{24}+\\frac{1}{24} = \\frac{18}{24} = \\frac{3}{4}$ ✓\n\n**∴ 답: ④ 3/4**\n\n② $\\frac{7}{12}$은 C를 빠뜨리고 A, B만으로 계산한 것이고, ⑤ $\\frac{11}{12}$은 여사건을 잘못 계산한 경우입니다.\n\n**💡 포인트:** 독립 시행에서 '적어도 하나' = $1 - (\\text{모두 여사건의 곱})$이 가장 효율적입니다.",
    "difficulty": "lv4",
