    "answer": 1,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 여사건을 이용합니다. 세 색이 모두 포함되지 않는 경우 = 어떤 한 색이 빠지는 경우를 셉니다.\n\n**Step 1. 전체 경우의 수**\n총 $3+3+3=9$개에서 4개를 뽑는 경우의 수:\n$$\\binom{9}{4} = 126$$\n\n**Step 2. 여사건 — 세 색 중 빠지는 색이 있는 경우**\n특정 한 색이 빠지면, 나머지 6개(두 색)에서 4개를 뽑습니다.\n한 색이 빠지는 경우: $\\binom{6}{4} = 15$\n빠질 수 있는 색: 3가지\n\n포함-배제 원리:\n- 한 색 빠짐: $3 \\times 15 = 45$\n- 두 색 빠짐(한 색만 사용): 한 색에서 4개를 뽑아야 하는데 각 색 3개뿐이므로 $\\binom{3}{4} = 0$\n따라서 두 색 이상 빠지는 것은 불가능합니다.\n\n$$|\\text{여사건}| = 45 - 0 = 45$$\n\n**Step 3. 세 색 모두 포함**\n$$126 - 45 = 81$$\n\n**Step 4. 확률 계산**\n$$P = \\frac{81}{126} = \\frac{9}{14}$$\n\n**Step 5. 검증**\n$\\gcd(81, 126) = 9$이므로 $\\frac{81}{126} = \\frac{9}{14}$.\n세 색이 모두 포함되는 구성: (2,1,1)의 배분 → 색이 2개인 색 고르기 $\\times$ 각 색에서 뽑기\n$\\binom{3}{1} \\times \\binom{3}{2} \\times \\binom{3}{1} \\times \\binom{3}{1} = 3 \\times 3 \\times 3 \\times 3 = 81$ ✓\n\n**∴ 답: ② 9/14**\n\n④ $\\frac{27}{42} = \\frac{9}{14}$로 같은 값이지만 기약분수가 아닙니다.\n\n**💡 포인트:** '모두 포함'은 여사건(어떤 것이 빠짐)을 포함-배제로 구하면 깔끔합니다.",
