    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 복합 시행에서 '적어도 1번' → 여사건을 이용합니다.\n\n**Step 1. 주사위 2개의 합이 7인 확률**\n합이 7인 순서쌍: $(1,6),(2,5),(3,4),(4,3),(5,2),(6,1)$ → 6가지\n전체: $6 \\times 6 = 36$\n$$p = \\frac{6}{36} = \\frac{1}{6}$$\n\n**Step 2. 합이 7이 아닌 확률**\n$$1 - p = 1 - \\frac{1}{6} = \\frac{5}{6}$$\n\n**Step 3. 2번 모두 합이 7이 아닌 확률**\n두 시행은 독립이므로:\n$$P(\\text{2번 모두 아님}) = \\left(\\frac{5}{6}\\right)^2 = \\frac{25}{36}$$\n\n**Step 4. 적어도 1번 합이 7인 확률**\n$$P = 1 - \\frac{25}{36} = \\frac{11}{36}$$\n\n**Step 5. 검증**\n- 정확히 1번: $\\binom{2}{1} \\times \\frac{1}{6} \\times \\frac{5}{6} = 2 \\times \\frac{5}{36} = \\frac{10}{36}$\n- 정확히 2번: $\\left(\\frac{1}{6}\\right)^2 = \\frac{1}{36}$\n- 합: $\\frac{10}{36} + \\frac{1}{36} = \\frac{11}{36}$ ✓\n\n**∴ 답: ③ 11/36**\n\n② $\\frac{5}{18} = \\frac{10}{36}$은 정확히 1번만 나올 확률(2번 나오는 경우 누락)입니다.\n\n**💡 포인트:** 반복 시행에서 '적어도 1번' = $1 - (1-p)^n$입니다. 이 공식을 외워 두면 빠르게 풀 수 있습니다.",
