    "problem": "검은 공 5개, 흰 공 4개가 들어 있는 주머니에서 비복원으로 공을 하나씩 꺼낸다. 3번째로 꺼낸 공이 처음으로 흰 공일 확률은?",
    "answerType": "choice",
