    "answer": 1,
    "explanation": "**[풀이]**\n\n**핵심 개념:** '3번째에 처음으로 흰 공'이란 1, 2번째는 검은 공이고 3번째가 흰 공인 사건입니다. 비복원이므로 조건부 확률을 곱합니다.\n\n**Step 1. 1번째: 검은 공**\n전체 9개 중 검은 공 5개:\n$$P_1 = \\frac{5}{9}$$\n\n**Step 2. 2번째: 검은 공**\n남은 8개 중 검은 공 4개:\n$$P_2 = \\frac{4}{8} = \\frac{1}{2}$$\n\n**Step 3. 3번째: 흰 공**\n남은 7개 중 흰 공 4개:\n$$P_3 = \\frac{4}{7}$$\n\n**Step 4. 곱셈 정리 (순차적 조건부)**\n$$P = P_1 \\times P_2 \\times P_3 = \\frac{5}{9} \\times \\frac{1}{2} \\times \\frac{4}{7} = \\frac{20}{126} = \\frac{10}{63}$$\n\n잠깐, $\\frac{20}{126} = \\frac{10}{63}$이고 이는 보기 ②입니다.\n\n**Step 5. 검증**\n순열로 확인: 9개를 일렬로 나열할 때, 처음 2개가 검은 공이고 3번째가 흰 공인 경우의 수:\n$\\frac{5 \\times 4 \\times 4}{9 \\times 8 \\times 7} = \\frac{80}{504} = \\frac{10}{63}$ ✓\n\n**∴ 답: ② 10/63**\n\n① $\\frac{5}{21} = \\frac{15}{63}$과는 다른 값입니다.\n\n**💡 포인트:** 비복원 순차 추출에서는 각 단계의 조건부 확률을 차례로 곱합니다. 분모와 분자가 매번 1씩 줄어든다는 점에 주의하세요.",
