    "type": "확률의 덧셈·곱셈",
    "problem": "A, B 두 팀이 시합을 하여 먼저 3승을 하는 팀이 우승한다. 매 시합에서 A가 이길 확률이 $\\frac{2}{3}$이고 비기는 것은 없다고 할 때, A가 정확히 4번째 시합에서 우승할 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, $\\frac{p}{q}$는 기약분수, 각 시합은 독립)",
    "answerType": "short",
    "choices": null,
    "answer": 35,
    "explanation": "**[풀이]**\n\n**핵심 개념:** A가 정확히 4번째에 우승하려면, 처음 3번 중 2번 이기고 1번 지고, 4번째에 이겨야 합니다.\n\n**Step 1. 조건 분석**\n- 처음 3번 중: A가 2승, B가 1승 (A가 3승이면 3번째에 끝남)\n- 4번째: A 승\n\n**Step 2. 처음 3번 중 A가 2승 1패하는 경우의 수**\n3번 중 A가 이기는 2번의 위치를 고르면: $\\binom{3}{2} = 3$\n\n**Step 3. 확률 계산**\n$$P = \\binom{3}{2} \\times \\left(\\frac{2}{3}\\right)^2 \\times \\left(\\frac{1}{3}\\right)^1 \\times \\frac{2}{3}$$\n$$= 3 \\times \\frac{4}{9} \\times \\frac{1}{3} \\times \\frac{2}{3}$$\n$$= 3 \\times \\frac{8}{81} = \\frac{24}{81} = \\frac{8}{27}$$\n\n**Step 4. 기약분수 확인**\n$\\gcd(8, 27) = 1$ (8 = $2^3$, 27 = $3^3$) → 기약분수\n$p = 8$, $q = 27$\n$$p + q = 8 + 27 = 35$$\n\n잠깐, answer가 105라고 적었는데 35가 맞습니다. answer를 35로 수정합니다.\n\n**Step 5. 검증**\n3경기 중 A가 2승: WW L의 배열 → WWL, WLW, LWW (3가지)\n각각의 확률: $\\left(\\frac{2}{3}\\right)^2 \\times \\frac{1}{3} = \\frac{4}{27}$\n4경기 A 승: $\\times \\frac{2}{3}$\n합계: $3 \\times \\frac{4}{27} \\times \\frac{2}{3} = \\frac{24}{81} = \\frac{8}{27}$ ✓\n\n**∴ 답: 35**\n\n**💡 포인트:** '정확히 $n$번째에 우승' = '처음 $n-1$번 중 $k-1$승' × '$n$번째 승리'로 분해합니다. 이 구조는 음이항분포와 같습니다.",
