    "problem": "1부터 10까지 자연수가 적힌 카드 10장에서 비복원으로 3장을 뽑을 때, 뽑은 세 수가 연속하는 세 자연수일 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, $\\frac{p}{q}$는 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 16,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 연속하는 세 자연수의 집합이 몇 개인지 세고, 전체 조합으로 나눕니다.\n\n**Step 1. 전체 경우의 수**\n$$\\binom{10}{3} = 120$$\n\n**Step 2. 연속하는 세 자연수의 집합**\n$\\{1,2,3\\}, \\{2,3,4\\}, \\{3,4,5\\}, \\ldots, \\{8,9,10\\}$\n시작 숫자가 1부터 8까지 → **8개**\n\n**Step 3. 확률 계산**\n$$P = \\frac{8}{120} = \\frac{1}{15}$$\n\n**Step 4. 기약분수 확인**\n$\\gcd(1, 15) = 1$ → 기약분수\n$p = 1$, $q = 15$\n$$p + q = 1 + 15 = 16$$\n\n**Step 5. 검증**\n10개의 수에서 연속 3개를 선택하는 경우: $10 - 3 + 1 = 8$가지\n$\\frac{8}{120} = \\frac{1}{15}$ ✓\n\n**∴ 답: 16**\n\n**💡 포인트:** 1부터 $n$까지에서 연속 $k$개를 뽑는 방법의 수는 $n - k + 1$입니다. 이 공식을 알면 바로 풀 수 있습니다.\n\n**보충:** 연속 자연수 문제는 '슬라이딩 윈도우'로 이해하면 쉽습니다. 크기 $k$의 창을 $\\{1, \\ldots, n\\}$ 위에서 한 칸씩 이동하면 $n-k+1$개의 위치가 있습니다. 연속 4개라면 $\\{1,2,3,4\\}, \\ldots, \\{7,8,9,10\\}$으로 $10-4+1=7$가지가 됩니다. 이런 패턴은 수열과 결합한 확률 문제에서도 자주 등장합니다.",
    "difficulty": "lv4",
