    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건부 확률의 정의\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n**Step 1. 사건 정의**\n사건 $A$: 짝수의 눈 → $\\{2, 4, 6\\}$\n사건 $B$: 4 이상의 눈 → $\\{4, 5, 6\\}$\n\n**Step 2. 교사건**\n$A \\cap B$: 짝수이면서 4 이상 → $\\{4, 6\\}$\n\n**Step 3. 조건부 확률 계산**\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)} = \\frac{2/6}{3/6} = \\frac{2}{3}$$\n\n또는 축소된 표본공간으로 생각하면:\n짝수가 나왔으므로 표본공간이 $\\{2, 4, 6\\}$ (3개)로 축소됩니다.\n이 중 4 이상인 것: $\\{4, 6\\}$ (2개)\n$$P(B|A) = \\frac{2}{3}$$\n\n**Step 4. 검증**\n$P(B|A) = \\frac{2}{3} > P(B) = \\frac{3}{6} = \\frac{1}{2}$\n짝수 조건이 4 이상일 가능성을 높이는 것은 직관적으로 타당합니다. (짝수 중 2만 4 미만) ✓\n\n**∴ 답: ③ 2/3**\n\n④ $\\frac{1}{2}$은 조건 없이 4 이상인 확률($P(B)$)이고, 조건부 확률이 아닙니다.\n\n**💡 포인트:** 조건부 확률에서는 조건(이미 일어난 사건)이 새로운 표본공간이 됩니다. 이 축소된 공간에서 원하는 사건의 비율을 구하면 됩니다.\n\n**보충:** 조건부 확률은 두 가지 방법으로 구할 수 있습니다: ① 공식 $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$ 사용, ② 축소된 표본공간에서 직접 세기. 간단한 문제에서는 ②가 직관적이고, 복잡한 문제에서는 ①이 체계적입니다.",
