    "explanation": "**[풀이]**\n\n**핵심 개념:** 비복원 추출에서 첫 번째 결과가 알려진 후, 남은 구성으로 조건부 확률을 구합니다.\n\n**Step 1. 초기 구성**\n불량품 2개 + 정상품 8개 = 총 10개\n\n**Step 2. 1개 꺼낸 후 (불량품)**\n남은 구성: 불량품 $2-1=1$개 + 정상품 8개 = 총 9개\n\n**Step 3. 두 번째에 불량품일 확률**\n$$P(\\text{2번째 불량}|\\text{1번째 불량}) = \\frac{1}{9}$$\n\n**Step 4. 검증**\n비복원 추출의 조건부 확률을 공식으로도 확인:\n$P(\\text{1번째 불량} \\cap \\text{2번째 불량}) = \\frac{2}{10} \\times \\frac{1}{9} = \\frac{2}{90}$\n$P(\\text{1번째 불량}) = \\frac{2}{10}$\n$P(\\text{2번째 불량}|\\text{1번째 불량}) = \\frac{2/90}{2/10} = \\frac{2}{90} \\times \\frac{10}{2} = \\frac{1}{9}$ ✓\n\n**∴ 답: ② 1/9**\n\n① $\\frac{1}{10}$은 초기 구성에서의 불량률($\\frac{1}{10}$ 아닌 $\\frac{2}{10}$)과도 다른 값이고, 남은 9개를 고려하지 않은 오답입니다.\n\n**💡 포인트:** 비복원 추출에서 이전 결과가 알려지면, 그에 따라 남은 구성이 변합니다. 이 '축소된 상자'에서 확률을 구하면 됩니다.",
