    "problem": "두 사건 $A$, $B$에 대해 $P(A) = \\frac{2}{5}$, $P(B|A) = \\frac{3}{4}$일 때, $P(A \\cap B)$의 값을 구하시오. 답을 $\\frac{p}{q}$ (기약분수)로 나타낼 때, $p+q$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 13,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건부 확률의 곱셈 정리\n$$P(A \\cap B) = P(A) \\times P(B|A)$$\n\n**Step 1. 곱셈 정리 적용**\n$$P(A \\cap B) = P(A) \\times P(B|A) = \\frac{2}{5} \\times \\frac{3}{4} = \\frac{6}{20} = \\frac{3}{10}$$\n\n**Step 2. 기약분수 확인**\n$\\gcd(3, 10) = 1$ → 기약분수\n$p = 3$, $q = 10$\n$$p + q = 3 + 10 = 13$$\n\n**Step 3. 검증**\n$P(B|A) = \\frac{P(A \\cap B)}{P(A)} = \\frac{3/10}{2/5} = \\frac{3}{10} \\times \\frac{5}{2} = \\frac{3}{4}$ ✓\n\n**∴ 답: 13**\n\n**💡 포인트:** $P(A \\cap B) = P(A) \\times P(B|A)$는 조건부 확률 정의를 변형한 것입니다. 곱셈 정리라고도 하며, 트리 다이어그램에서 경로의 확률을 곱하는 것과 같습니다.\n\n**보충:** 곱셈 정리는 두 가지 형태로 쓸 수 있습니다: $P(A \\cap B) = P(A) \\cdot P(B|A) = P(B) \\cdot P(A|B)$. 어떤 사건을 먼저 놓느냐는 자유이며, 주어진 조건에 따라 편한 쪽을 선택하면 됩니다. 이 공식은 베이즈 정리의 출발점이기도 합니다. 곱셈 정리를 자유자재로 변형할 수 있으면 조건부 확률의 대부분의 문제를 풀 수 있습니다.",
