    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립사건이면 한 사건이 일어나도 다른 사건의 확률에 영향을 주지 않습니다.\n$$A, B\\text{ 독립} \\implies P(A|B) = P(A)$$\n\n**Step 1. 독립의 의미**\n$A$와 $B$가 독립이면:\n$$P(A \\cap B) = P(A) \\times P(B) = \\frac{1}{3} \\times \\frac{1}{2} = \\frac{1}{6}$$\n\n**Step 2. 조건부 확률 계산**\n$$P(A|B) = \\frac{P(A \\cap B)}{P(B)} = \\frac{1/6}{1/2} = \\frac{1}{6} \\times \\frac{2}{1} = \\frac{1}{3}$$\n\n**Step 3. 검증**\n$P(A|B) = \\frac{1}{3} = P(A)$\n독립이면 $P(A|B) = P(A)$이므로 결과가 일치합니다. ✓\n\n**∴ 답: ③ 1/3**\n\n① $\\frac{1}{6}$은 $P(A \\cap B)$이지 $P(A|B)$가 아닙니다.\n\n**💡 포인트:** 독립 → $P(A|B) = P(A)$, $P(B|A) = P(B)$. 이것이 독립의 핵심 의미입니다. B가 일어났든 안 일어났든 A의 확률은 변하지 않습니다.\n\n**보충:** 독립의 세 가지 동치 조건: ① $P(A \\cap B) = P(A)P(B)$, ② $P(A|B) = P(A)$, ③ $P(B|A) = P(B)$. 이 중 하나만 확인하면 나머지도 성립합니다. 독립과 배반은 전혀 다른 개념이므로 혼동하지 마세요.",
    "difficulty": "lv2",
