    "explanation": "**[풀이]**\n\n**핵심 개념:** 곱셈 정리 — $P(A \\cap B) = P(A) \\times P(B|A)$\n\n**Step 1. 주어진 정보 정리**\n$P(\\text{안경}) = 0.6$\n$P(\\text{콘택트}|\\text{안경}) = 0.3$\n\n**Step 2. 곱셈 정리 적용**\n$$P(\\text{안경} \\cap \\text{콘택트}) = P(\\text{안경}) \\times P(\\text{콘택트}|\\text{안경})$$\n$$= 0.6 \\times 0.3 = 0.18 = \\frac{18}{100} = \\frac{9}{50}$$\n\n**Step 3. 검증**\n100명 기준으로 생각하면:\n- 안경 착용: 60명\n- 그 중 콘택트도 사용: $60 \\times 0.3 = 18$명\n- 비율: $\\frac{18}{100} = \\frac{9}{50}$ ✓\n\n**∴ 답: ① 9/50**\n\n④ $\\frac{18}{100}$은 $\\frac{9}{50}$과 같은 값이지만 기약분수가 아닙니다. ② $\\frac{3}{10}$은 $P(\\text{콘택트}|\\text{안경})$을 $P(\\text{콘택트})$로 착각한 오답입니다.\n\n**💡 포인트:** $P(A \\cap B) = P(A) \\times P(B|A)$는 트리 다이어그램의 가지를 따라 곱하는 것과 같습니다. '~의 ~%'라는 표현이 나오면 곱셈 정리를 적용하세요.\n\n**보충:** 트리 다이어그램(수형도)은 확률의 흐름을 시각화하는 강력한 도구입니다. 각 분기점에서의 확률을 경로를 따라 곱하면 최종 사건의 확률을 구할 수 있습니다. 복잡한 다단계 문제에서 특히 유용합니다.",
