    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건부 확률 — 축소된 표본공간에서 원하는 경우를 셉니다.\n\n**Step 1. 합이 8 이상인 순서쌍 나열**\n합 8: $(2,6),(3,5),(4,4),(5,3),(6,2)$ → 5가지\n합 9: $(3,6),(4,5),(5,4),(6,3)$ → 4가지\n합 10: $(4,6),(5,5),(6,4)$ → 3가지\n합 11: $(5,6),(6,5)$ → 2가지\n합 12: $(6,6)$ → 1가지\n합계: $5+4+3+2+1 = 15$가지\n\n**Step 2. 합 8 이상이면서 두 눈 모두 짝수인 경우**\n두 눈이 모두 짝수이면 합도 짝수이므로 합이 홀수(9, 11)인 경우에서는 불가능합니다.\n- 합 8: $(2,6), (4,4), (6,2)$ → 3가지\n- 합 10: $(4,6), (6,4)$ → 2가지\n- 합 12: $(6,6)$ → 1가지\n합계: $3 + 2 + 1 = 6$가지\n\n**Step 3. 조건부 확률**\n$$P(\\text{둘 다 짝수}|\\text{합 ≥ 8}) = \\frac{6}{15} = \\frac{2}{5}$$\n\n**Step 4. 검증**\n전체 36가지 중 합 8 이상: 15가지, 그중 짝짝: 6가지\n$P = \\frac{6}{15} = \\frac{2}{5} = 0.4$로 합리적인 값입니다. ✓\n\n**∴ 답: ④ 2/5**\n\n② $\\frac{4}{15}$는 합 10 이상에서만 세거나 일부를 누락한 계산 오류이고, ③ $\\frac{1}{3} = \\frac{5}{15}$과는 다른 값입니다.\n\n**💡 포인트:** 합이 특정 값 이상이라는 조건이 주어지면, 해당 순서쌍을 모두 나열한 후 그 안에서 원하는 조건을 세면 됩니다.",
