    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 덧셈 정리로 교사건을 구한 뒤, 조건부 확률을 계산합니다.\n\n**Step 1. $P(A \\cap B)$ 구하기**\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n$$0.7 = 0.5 + 0.4 - P(A \\cap B)$$\n$$P(A \\cap B) = 0.9 - 0.7 = 0.2$$\n\n**Step 2. $P(B|A)$ 계산**\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)} = \\frac{0.2}{0.5} = 0.4$$\n\n**Step 3. 검증**\n벤 다이어그램으로 확인:\n- $A$만: $0.5 - 0.2 = 0.3$\n- $B$만: $0.4 - 0.2 = 0.2$\n- $A \\cap B$: $0.2$\n- $A \\cup B$: $0.3 + 0.2 + 0.2 = 0.7$ ✓\n\n$P(B|A) = \\frac{0.2}{0.5} = 0.4$ ✓\n\n**∴ 답: ③ 0.4**\n\n① $0.2$는 $P(A \\cap B)$이며 조건부 확률이 아닙니다.\n\n**💡 포인트:** 세 값($P(A), P(B), P(A \\cup B)$)이 주어지면 덧셈 정리로 교사건을 구한 뒤, 조건부 확률을 계산합니다. 이 2단계 과정을 숙달하세요.\n\n**보충:** 이 문제는 많은 확률 문제의 기본 패턴입니다: ① 덧셈 정리로 $P(A \\cap B)$ 구하기, ② 조건부 확률 공식에 대입하기. 벤 다이어그램을 그려 각 영역의 확률을 시각화하면 실수를 줄일 수 있습니다.",
    "difficulty": "lv2",
