    "explanation": "**[풀이]**\n\n**핵심 개념:** 전확률 공식\n$$P(B) = P(A) \\cdot P(B|A) + P(A^c) \\cdot P(B|A^c)$$\n\n**Step 1. $P(A^c)$ 구하기**\n$$P(A^c) = 1 - P(A) = 1 - \\frac{2}{3} = \\frac{1}{3}$$\n\n**Step 2. 전확률 공식 적용**\n$$P(B) = \\frac{2}{3} \\times \\frac{1}{4} + \\frac{1}{3} \\times \\frac{1}{2}$$\n$$= \\frac{2}{12} + \\frac{1}{6} = \\frac{1}{6} + \\frac{1}{6} = \\frac{2}{6} = \\frac{1}{3}$$\n\n**Step 3. 검증**\n$P(A \\cap B) = P(A) \\cdot P(B|A) = \\frac{2}{3} \\times \\frac{1}{4} = \\frac{1}{6}$\n$P(A^c \\cap B) = P(A^c) \\cdot P(B|A^c) = \\frac{1}{3} \\times \\frac{1}{2} = \\frac{1}{6}$\n$P(B) = \\frac{1}{6} + \\frac{1}{6} = \\frac{1}{3}$ ✓\n\n또한 $\\min(P(B|A), P(B|A^c)) = \\frac{1}{4} \\le P(B) = \\frac{1}{3} \\le \\frac{1}{2} = \\max(P(B|A), P(B|A^c))$ ✓\n($P(B)$는 두 조건부 확률의 가중평균이므로 둘 사이에 있어야 합니다.)\n\n**∴ 답: ② 1/3**\n\n③ $\\frac{5}{12}$은 $\\frac{1}{4} + \\frac{1}{6}$으로 잘못 더한 것이고, ④ $\\frac{1}{2}$은 $P(B|A^c)$의 값일 뿐입니다.\n\n**💡 포인트:** 전확률 공식은 원인($A$ 또는 $A^c$)별로 나눠 각 경로의 확률을 합산합니다. 트리 다이어그램에서 $B$에 도달하는 모든 경로를 더하는 것과 같습니다.",
