    "problem": "두 사건 $A$, $B$에 대해 $P(A \\cap B) = \\frac{1}{5}$, $P(B|A) = \\frac{2}{5}$일 때, $P(A)$의 값을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 3,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건부 확률의 정의에서 $P(A)$를 역으로 구합니다.\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)} \\implies P(A) = \\frac{P(A \\cap B)}{P(B|A)}$$\n\n**Step 1. $P(A)$ 계산**\n$$P(A) = \\frac{P(A \\cap B)}{P(B|A)} = \\frac{1/5}{2/5} = \\frac{1}{5} \\times \\frac{5}{2} = \\frac{1}{2}$$\n\n**Step 2. 기약분수 확인**\n$\\frac{1}{2}$은 기약분수 → $p = 1$, $q = 2$\n$$p + q = 1 + 2 = 3$$\n\n**Step 3. 검증**\n$P(B|A) = \\frac{P(A \\cap B)}{P(A)} = \\frac{1/5}{1/2} = \\frac{2}{5}$ ✓\n\n**∴ 답: 3**\n\n**💡 포인트:** $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$에서 세 값 중 두 개가 주어지면 나머지 하나를 구할 수 있습니다.\n\n**보충:** 조건부 확률 공식 $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$은 세 가지 양을 포함합니다. 어떤 두 개가 주어져도 나머지를 구할 수 있으므로, 이 공식의 변형에 익숙해지면 다양한 문제에 대응할 수 있습니다: $P(A \\cap B) = P(A) \\cdot P(B|A)$, $P(A) = \\frac{P(A \\cap B)}{P(B|A)}$.",
