    "type": "조건부 확률",
    "problem": "상자에 흰 공 4개, 빨간 공 6개가 있다. 비복원으로 2개를 꺼낼 때, 첫 번째가 흰 공이었다는 조건 하에 두 번째도 흰 공일 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 비복원 추출에서 첫 번째 결과가 확정된 후의 조건부 확률\n\n**Step 1. 첫 번째 흰 공을 꺼낸 후 상태**\n- 남은 공: 흰 $4-1=3$개, 빨간 6개, 총 9개\n\n**Step 2. 두 번째도 흰 공일 확률**\n$$P(\\text{2번째 흰}|\\text{1번째 흰}) = \\frac{3}{9} = \\frac{1}{3}$$\n\n**Step 3. 기약분수 확인 및 답**\n$\\frac{1}{3}$은 기약분수 → $p = 1$, $q = 3$\n$$p + q = 1 + 3 = 4$$\n\n**Step 4. 검증 (곱셈 정리)**\n$P(\\text{1번째 흰} \\cap \\text{2번째 흰}) = \\frac{4}{10} \\times \\frac{3}{9} = \\frac{12}{90} = \\frac{2}{15}$\n$P(\\text{1번째 흰}) = \\frac{4}{10} = \\frac{2}{5}$\n$P(\\text{2번째 흰}|\\text{1번째 흰}) = \\frac{2/15}{2/5} = \\frac{2}{15} \\times \\frac{5}{2} = \\frac{1}{3}$ ✓\n\n**∴ 답: 4**\n\n**💡 포인트:** 비복원 추출에서는 이전 결과에 따라 남은 구성이 달라지므로 조건부 확률이 자연스럽게 적용됩니다.\n\n**보충:** 비복원과 복원의 차이를 비교하면: 복원 추출은 독립 시행이므로 $P = \\frac{4}{10} \\times \\frac{4}{10} = \\frac{4}{25}$이지만, 비복원은 $\\frac{4}{10} \\times \\frac{3}{9} = \\frac{2}{15}$으로 값이 다릅니다. 문제에서 '복원'인지 '비복원'인지를 반드시 확인하세요.",
