    "explanation": "**[풀이]**\n\n**핵심 개념:** 베이즈 정리\n$$P(A|D) = \\frac{P(A) \\cdot P(D|A)}{P(A) \\cdot P(D|A) + P(B) \\cdot P(D|B)}$$\n\n**Step 1. 주어진 정보**\n$P(A) = 0.6$, $P(B) = 0.4$\n$P(D|A) = 0.03$ (A의 불량률), $P(D|B) = 0.05$ (B의 불량률)\n\n**Step 2. 전확률 — $P(D)$**\n$$P(D) = P(A) \\cdot P(D|A) + P(B) \\cdot P(D|B)$$\n$$= 0.6 \\times 0.03 + 0.4 \\times 0.05 = 0.018 + 0.020 = 0.038$$\n\n**Step 3. 베이즈 정리**\n$$P(A|D) = \\frac{0.018}{0.038} = \\frac{18}{38} = \\frac{9}{19}$$\n\n**Step 4. 검증**\n$P(B|D) = \\frac{0.020}{0.038} = \\frac{20}{38} = \\frac{10}{19}$\n$P(A|D) + P(B|D) = \\frac{9}{19} + \\frac{10}{19} = 1$ ✓\n\nA가 더 많이 생산하지만(60%), 불량률은 낮으므로(3%) $P(A|D) < P(B|D)$인 것이 합리적입니다. ✓\n\n**∴ 답: ② 9/19**\n\n③ $\\frac{10}{19}$은 $P(B|D)$, 즉 B에서 생산되었을 확률입니다.\n\n**💡 포인트:** 베이즈 정리는 '결과(불량)를 알고 원인(공장)을 추론'하는 역확률 문제에 핵심입니다. 분자 = 특정 경로의 확률, 분모 = 모든 경로의 확률 합.",
