    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건부 확률 $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$\n\n**Step 1. 전체 경우의 수**\n$\\binom{5}{2} = 10$\n\n**Step 2. 적어도 1개 흰 공 (조건 B)**\n여사건: 2개 모두 검은 공 = $\\binom{2}{2} = 1$\n적어도 1개 흰 공: $10 - 1 = 9$가지\n$P(B) = \\frac{9}{10}$\n\n**Step 3. 2개 모두 흰 공 (사건 A)**\n$\\binom{3}{2} = 3$\n$P(A) = \\frac{3}{10}$\n\n**Step 4. $A \\cap B$**\n2개 모두 흰 공이면 자동으로 적어도 1개는 흰 공.\n$P(A \\cap B) = P(A) = \\frac{3}{10}$\n\n**Step 5. 조건부 확률**\n$$P(A|B) = \\frac{3/10}{9/10} = \\frac{3}{9} = \\frac{1}{3}$$\n\n**Step 6. 검증**\n축소된 표본공간(적어도 1개 흰): 9가지\n그 중 2개 모두 흰: 3가지\n$\\frac{3}{9} = \\frac{1}{3}$ ✓\n\n**∴ 답: ③ 3/9 (= 1/3)**\n\n보기 ①과 ③은 같은 값($\\frac{1}{3}$)입니다. 정답은 ③입니다. (정확히는 $\\frac{3}{9}$으로 약분하면 $\\frac{1}{3}$)\n\n**💡 포인트:** '적어도 ~'라는 조건이 주어지면, 그 조건을 만족하는 전체 경우가 새로운 표본공간이 됩니다.",
