    "explanation": "**[풀이]**\n\n**핵심 개념:** 비복원 순차 추출에서 곱셈 정리 적용\n\n**Step 1. 경로 1: 빨→파**\n$$P(\\text{빨→파}) = \\frac{4}{10} \\times \\frac{6}{9} = \\frac{24}{90}$$\n\n**Step 2. 경로 2: 파→빨**\n$$P(\\text{파→빨}) = \\frac{6}{10} \\times \\frac{4}{9} = \\frac{24}{90}$$\n\n**Step 3. 합**\n$$P = \\frac{24}{90} + \\frac{24}{90} = \\frac{48}{90} = \\frac{8}{15}$$\n\n**Step 4. 검증**\n$\\frac{48}{90}$에서 $\\gcd(48, 90) = 6$이므로 $\\frac{48}{90} = \\frac{8}{15}$.\n또한 이는 '1개 빨강 1개 파랑'을 뽑는 확률과 같습니다:\n$\\frac{\\binom{4}{1}\\binom{6}{1}}{\\binom{10}{2}} = \\frac{24}{45} = \\frac{8}{15}$ ✓\n\n**∴ 답: ② 8/15**\n\n두 경로의 확률이 같다는 점이 흥미롭습니다. 이는 비복원에서 순서를 바꿔도 곱이 같기 때문입니다($\\frac{a}{n} \\times \\frac{b}{n-1} = \\frac{b}{n} \\times \\frac{a}{n-1}$).\n\n**💡 포인트:** 비복원 추출에서 다른 색 1개씩 뽑는 확률 = 순서를 고려한 두 경로의 합. 조합으로 한 번에 $\\frac{\\binom{a}{1}\\binom{b}{1}}{\\binom{n}{2}}$로 구할 수도 있습니다. 두 방법의 결과가 같은지 교차 검증하는 습관을 기르세요.",
