    "explanation": "**[풀이]**\n\n**핵심 개념:** 베이즈 정리\n$$P(A|R) = \\frac{P(A) \\cdot P(R|A)}{P(A) \\cdot P(R|A) + P(B) \\cdot P(R|B)}$$\n\n**Step 1. 사전 확률**\n상자를 임의로 선택: $P(A) = P(B) = \\frac{1}{2}$\n\n**Step 2. 우도(likelihood)**\n$P(R|A) = \\frac{3}{5}$ (A에서 빨간 공)\n$P(R|B) = \\frac{1}{5}$ (B에서 빨간 공)\n\n**Step 3. 전확률**\n$$P(R) = \\frac{1}{2} \\times \\frac{3}{5} + \\frac{1}{2} \\times \\frac{1}{5} = \\frac{3}{10} + \\frac{1}{10} = \\frac{4}{10} = \\frac{2}{5}$$\n\n**Step 4. 베이즈 정리**\n$$P(A|R) = \\frac{\\frac{1}{2} \\times \\frac{3}{5}}{\\frac{2}{5}} = \\frac{\\frac{3}{10}}{\\frac{2}{5}} = \\frac{3}{10} \\times \\frac{5}{2} = \\frac{3}{4}$$\n\n**Step 5. 검증**\n$P(B|R) = 1 - \\frac{3}{4} = \\frac{1}{4}$\n$P(B|R) = \\frac{\\frac{1}{2} \\times \\frac{1}{5}}{\\frac{2}{5}} = \\frac{\\frac{1}{10}}{\\frac{2}{5}} = \\frac{1}{4}$ ✓\n\nA에 빨간 공이 더 많으므로(60% vs 20%) $P(A|R) > P(B|R)$는 직관적으로 타당합니다. ✓\n\n**∴ 답: ② 3/4**\n\n① $\\frac{1}{2}$은 사전 확률(상자 선택)이며, 빨간 공이라는 정보를 반영하지 않은 것입니다.\n\n**💡 포인트:** 베이즈 정리에서 사전 확률(같은 $\\frac{1}{2}$)이 우도에 의해 업데이트됩니다. A의 빨간 공 비율이 높으므로 사후 확률은 $\\frac{1}{2}$보다 커집니다.",
