    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건부 확률 — 축소된 표본공간에서 직접 셉니다.\n\n**Step 1. 합이 10 이상인 순서쌍**\n합 10: $(4,6),(5,5),(6,4)$ → 3가지\n합 11: $(5,6),(6,5)$ → 2가지\n합 12: $(6,6)$ → 1가지\n합계: **6가지**\n\n**Step 2. 그 중 $a \\ge 5$인 경우**\n$(5,5), (5,6), (6,4), (6,5), (6,6)$ → **5가지**\n($a=4$인 것: $(4,6)$ 1가지만 제외)\n\n**Step 3. 조건부 확률**\n$$P(a \\ge 5 | a+b \\ge 10) = \\frac{5}{6}$$\n\n**Step 4. 기약분수 확인**\n$\\gcd(5, 6) = 1$ → 기약분수\n$p = 5$, $q = 6$\n$$p + q = 5 + 6 = 11$$\n\n**Step 5. 검증**\n$a \\ge 5$이면서 $a + b \\ge 10$: $a=5$일 때 $b \\ge 5$ → $(5,5),(5,6)$ = 2가지, $a=6$일 때 $b \\ge 4$ → $(6,4),(6,5),(6,6)$ = 3가지, 합계 5가지 ✓\n\n**∴ 답: 11**\n\n**💡 포인트:** 조건부 확률에서는 조건을 만족하는 경우를 모두 나열한 후, 그 안에서 원하는 조건을 세면 됩니다.\n\n**보충:** 주사위 2개 문제에서 합이 큰 조건이 주어지면, 큰 눈이 나올 가능성이 높아집니다. 이처럼 조건부 확률은 '정보가 주어진 후 확률이 어떻게 변하는가'를 수학적으로 표현한 것입니다.",
