    "_type": "cond_prob",
    "type": "조건부 확률",
    "problem": "두 사건 $A$, $B$에 대해 $P(A|B) = \\frac{1}{3}$, $P(B|A) = \\frac{1}{2}$, $P(A \\cup B) = \\frac{4}{5}$일 때, $P(A)$의 값을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 7,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 두 조건부 확률에서 교사건과 각 확률 사이의 관계식을 세워 연립합니다.\n\n**Step 1. 교사건 관계식 세우기**\n$P(A|B) = \\frac{P(A \\cap B)}{P(B)} = \\frac{1}{3}$ → $P(A \\cap B) = \\frac{1}{3}P(B)$ ... ①\n$P(B|A) = \\frac{P(A \\cap B)}{P(A)} = \\frac{1}{2}$ → $P(A \\cap B) = \\frac{1}{2}P(A)$ ... ②\n\n**Step 2. ①과 ②에서 $P(B)$를 $P(A)$로 표현**\n$\\frac{1}{3}P(B) = \\frac{1}{2}P(A)$\n$$P(B) = \\frac{3}{2}P(A)$$\n\n**Step 3. 덧셈 정리에 대입**\n$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n$$\\frac{4}{5} = P(A) + \\frac{3}{2}P(A) - \\frac{1}{2}P(A)$$\n$$\\frac{4}{5} = P(A)\\left(1 + \\frac{3}{2} - \\frac{1}{2}\\right) = 2P(A)$$\n$$P(A) = \\frac{4}{10} = \\frac{2}{5}$$\n\n**Step 4. 기약분수 확인**\n$\\gcd(2, 5) = 1$ → 기약분수\n$p = 2$, $q = 5$\n$$p + q = 2 + 5 = 7$$\n\n**Step 5. 검증**\n$P(A) = \\frac{2}{5}$, $P(B) = \\frac{3}{2} \\times \\frac{2}{5} = \\frac{3}{5}$, $P(A \\cap B) = \\frac{1}{2} \\times \\frac{2}{5} = \\frac{1}{5}$\n$P(A|B) = \\frac{1/5}{3/5} = \\frac{1}{3}$ ✓\n$P(B|A) = \\frac{1/5}{2/5} = \\frac{1}{2}$ ✓\n$P(A \\cup B) = \\frac{2}{5} + \\frac{3}{5} - \\frac{1}{5} = \\frac{4}{5}$ ✓\n\n**∴ 답: 7**\n\n**💡 포인트:** 두 조건부 확률이 주어지면 교사건을 매개변수로 놓고 $P(A)$, $P(B)$를 하나의 변수로 표현한 뒤, 덧셈 정리에 대입하여 일차방정식을 풀면 됩니다.",
