    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건부 확률 — 축소된 표본공간\n$$P(\\text{3개 앞}|\\text{적어도 2개 앞}) = \\frac{P(\\text{3개 앞})}{P(\\text{적어도 2개 앞})}$$\n\n**Step 1. 전체 표본공간**\n동전 3개: $2^3 = 8$가지\n\n**Step 2. 앞면이 적어도 2개**\n앞면 2개: $\\binom{3}{2} = 3$가지 (HHT, HTH, THH)\n앞면 3개: $\\binom{3}{3} = 1$가지 (HHH)\n합계: $3 + 1 = 4$가지\n$P(\\text{적어도 2개 앞}) = \\frac{4}{8} = \\frac{1}{2}$\n\n**Step 3. 3개 모두 앞면**\n$P(\\text{3개 앞}) = \\frac{1}{8}$\n\n**Step 4. 조건부 확률**\n$$P = \\frac{1/8}{1/2} = \\frac{1}{4}$$\n\n**축소된 표본공간으로 확인:**\n적어도 2개 앞: $\\{HHH, HHT, HTH, THH\\}$ → 4가지\n그 중 3개 모두 앞: $\\{HHH\\}$ → 1가지\n$P = \\frac{1}{4}$ ✓\n\n**∴ 답: ② 1/4**\n\n① $\\frac{1}{8}$은 조건 없이 3개 모두 앞면인 확률이고, ④ $\\frac{3}{8}$은 앞면 정확히 2개의 확률입니다.\n\n**💡 포인트:** '적어도 2개'가 조건이면, 2개 이상인 모든 경우가 새로운 전체가 됩니다.\n\n**보충:** 동전 $n$개에서 앞면이 적어도 $k$개 나왔다는 조건 하에서 모두 앞면일 확률은 $\\frac{1}{\\sum_{i=k}^{n}\\binom{n}{i}}$입니다. 이 문제에서는 $\\frac{1}{\\binom{3}{2}+\\binom{3}{3}} = \\frac{1}{3+1} = \\frac{1}{4}$입니다.",
