    "answer": 1,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건부 확률 — 유명한 소년-소녀 문제(Boy or Girl paradox)\n\n**Step 1. 전체 표본공간**\n자녀 2명의 성별 조합: $\\{(아,아), (아,딸), (딸,아), (딸,딸)\\}$ → 4가지 (각 확률 $\\frac{1}{4}$)\n\n**Step 2. 조건: 적어도 한 명이 아들**\n$(딸,딸)$을 제외한 나머지: $\\{(아,아), (아,딸), (딸,아)\\}$ → 3가지\n$P(\\text{적어도 1명 아들}) = \\frac{3}{4}$\n\n**Step 3. 두 명 모두 아들**\n$\\{(아,아)\\}$ → 1가지\n$P(\\text{둘 다 아들}) = \\frac{1}{4}$\n\n**Step 4. 조건부 확률**\n$$P(\\text{둘 다 아들}|\\text{적어도 1명 아들}) = \\frac{1/4}{3/4} = \\frac{1}{3}$$\n\n**Step 5. 검증 — 축소된 표본공간**\n$\\{(아,아), (아,딸), (딸,아)\\}$ 3가지 중 $(아,아)$는 1가지\n$P = \\frac{1}{3}$ ✓\n\n**주의:** 만약 '첫째가 아들'이라는 조건이었다면 $P = \\frac{1}{2}$입니다. '적어도 한 명'과 '특정 한 명'은 다른 조건입니다.\n\n**∴ 답: ② 1/3**\n\n③ $\\frac{1}{2}$은 '첫째가 아들'이라는 조건에서의 답입니다. 조건의 차이에 주의하세요.\n\n**💡 포인트:** 이 문제는 직관($\\frac{1}{2}$)과 실제 답($\\frac{1}{3}$)이 다른 유명한 확률 문제입니다. 조건이 정확히 무엇인지에 따라 답이 달라집니다.",
