    "explanation": "**[풀이]**\n\n**핵심 개념:** 합이 짝수 = 둘 다 짝수 또는 둘 다 홀수. 같은 패리티인 두 수의 차는 반드시 짝수입니다.\n\n**Step 1. 전체 경우의 수**\n$\\binom{6}{2} = 15$\n\n**Step 2. 합이 짝수인 경우 (축소된 표본공간)**\n짝수: $\\{2, 4, 6\\}$, 홀수: $\\{1, 3, 5\\}$\n- 둘 다 짝수: $\\binom{3}{2} = 3$ → $\\{2,4\\}, \\{2,6\\}, \\{4,6\\}$\n- 둘 다 홀수: $\\binom{3}{2} = 3$ → $\\{1,3\\}, \\{1,5\\}, \\{3,5\\}$\n합계: **6가지**\n\n**Step 3. 합이 짝수이면서 차가 정확히 2인 경우**\n같은 패리티인 두 수의 차는 짝수(0, 2, 4, ...)이고, 서로 다른 수이므로 최소 차는 2입니다.\n- $\\{2,4\\}$: 차 = 2 ✓\n- $\\{2,6\\}$: 차 = 4 ✗\n- $\\{4,6\\}$: 차 = 2 ✓\n- $\\{1,3\\}$: 차 = 2 ✓\n- $\\{1,5\\}$: 차 = 4 ✗\n- $\\{3,5\\}$: 차 = 2 ✓\n차가 2인 것: **4가지**\n\n**Step 4. 조건부 확률**\n$$P(\\text{차 = 2}|\\text{합 짝수}) = \\frac{4}{6} = \\frac{2}{3}$$\n\n**Step 5. 검증**\n합이 짝수인 6가지 중 차가 2인 것은 4가지, 차가 4인 것은 2가지.\n$\\frac{4}{6} + \\frac{2}{6} = 1$ ✓\n\n**∴ 답: ③ 2/3**\n\n① $\\frac{1}{3}$은 차가 4인 경우의 확률($\\frac{2}{6}$)이고, ② $\\frac{2}{5}$는 전체 15가지에서 차가 2인 경우 6가지의 확률과도 다릅니다.\n\n**💡 포인트:** 합이 짝수 → 같은 패리티 → 차가 반드시 짝수. 이 축소된 공간에서 추가 조건을 확인하는 2단계 사고가 필요합니다.",
