    "type": "조건부 확률",
    "problem": "상자 A에 흰 공 2개, 검은 공 1개, 상자 B에 흰 공 1개, 검은 공 2개가 있다. 주사위를 던져 3 이하면 A에서, 4 이상이면 B에서 공 1개를 꺼낸다. 꺼낸 공이 흰 공이었을 때, 상자 A에서 꺼냈을 확률은?",
    "answerType": "choice",
    "choices": [
      "① 1/3",
      "② 2/5",
      "③ 1/2",
      "④ 2/3",
      "⑤ 4/5"
    ],
    "answer": 3,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 베이즈 정리\n$$P(A|W) = \\frac{P(A) \\cdot P(W|A)}{P(W)}$$\n\n**Step 1. 사전 확률**\n$P(A) = P(\\text{3 이하}) = \\frac{3}{6} = \\frac{1}{2}$\n$P(B) = P(\\text{4 이상}) = \\frac{3}{6} = \\frac{1}{2}$\n\n**Step 2. 우도**\n$P(W|A) = \\frac{2}{3}$ (A에서 흰 공)\n$P(W|B) = \\frac{1}{3}$ (B에서 흰 공)\n\n**Step 3. 전확률**\n$$P(W) = \\frac{1}{2} \\times \\frac{2}{3} + \\frac{1}{2} \\times \\frac{1}{3} = \\frac{2}{6} + \\frac{1}{6} = \\frac{3}{6} = \\frac{1}{2}$$\n\n**Step 4. 베이즈 정리**\n$$P(A|W) = \\frac{\\frac{1}{2} \\times \\frac{2}{3}}{\\frac{1}{2}} = \\frac{\\frac{1}{3}}{\\frac{1}{2}} = \\frac{2}{3}$$\n\n**Step 5. 검증**\n$P(B|W) = \\frac{\\frac{1}{2} \\times \\frac{1}{3}}{\\frac{1}{2}} = \\frac{1}{3}$\n$P(A|W) + P(B|W) = \\frac{2}{3} + \\frac{1}{3} = 1$ ✓\n\nA에 흰 공이 더 많으므로 $P(A|W) > P(B|W)$는 직관적으로 타당합니다. ✓\n\n**∴ 답: ④ 2/3**\n\n③ $\\frac{1}{2}$은 사전 확률(상자 선택)이며, 흰 공이라는 정보를 반영하지 않은 것입니다.\n\n**💡 포인트:** 주사위+상자 문제는 베이즈 정리의 전형적 유형입니다. 주사위로 상자 선택 → 상자에서 공 꺼내기의 2단계 시행에서 결과를 보고 원인을 추론합니다.",
