    "problem": "주머니에 빨간 공 3개, 파란 공 2개가 있다. 비복원으로 2개를 꺼냈을 때 모두 빨간색이었다. 남은 3개에서 1개를 더 꺼낼 때 빨간 공일 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 비복원 추출에서 이전 결과가 확정된 후의 조건부 확률\n\n**Step 1. 초기 구성**\n빨간 공 3개 + 파란 공 2개 = 총 5개\n\n**Step 2. 2개를 꺼낸 후의 상태**\n빨간 공 2개를 이미 꺼냈으므로:\n- 남은 빨간 공: $3 - 2 = 1$개\n- 남은 파란 공: $2$개\n- 남은 총: $3$개\n\n**Step 3. 남은 3개에서 빨간 공을 꺼낼 확률**\n$$P(\\text{빨간}|\\text{이미 빨간 2개 제거}) = \\frac{1}{3}$$\n\n**Step 4. 검증**\n남은 공: 빨간 1개 + 파란 2개 = 3개\n$P(\\text{빨간}) = \\frac{1}{3}$, $P(\\text{파란}) = \\frac{2}{3}$\n$\\frac{1}{3} + \\frac{2}{3} = 1$ ✓\n\n처음부터 순서대로 확인:\n$P(\\text{빨빨빨}) = \\frac{3}{5} \\times \\frac{2}{4} \\times \\frac{1}{3} = \\frac{6}{60} = \\frac{1}{10}$\n$P(\\text{빨빨}) = \\frac{3}{5} \\times \\frac{2}{4} = \\frac{6}{20} = \\frac{3}{10}$\n$P(\\text{3번째 빨}|\\text{1,2번째 빨}) = \\frac{1/10}{3/10} = \\frac{1}{3}$ ✓\n\n**∴ 답: 4** (즉 $\\frac{1}{3}$, $p+q = 1+3 = 4$)\n\n**💡 포인트:** 비복원 추출에서 이전 결과가 알려지면, 남은 구성에서 새롭게 확률을 계산합니다. 이것이 조건부 확률의 자연스러운 해석입니다.",
