    "type": "조건부 확률",
    "problem": "어느 공장에서 기계 A, B, C가 각각 전체 생산량의 50%, 30%, 20%를 생산한다. 불량률은 A: 2%, B: 3%, C: 5%이다. 임의로 한 제품을 뽑았더니 불량품이었을 때, 이것이 C에서 생산되었을 확률을 $\\frac{p}{q}$라 하자. $p \\times q$의 값을 구하시오. (단, 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 290,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 베이즈 정리 (3개 공장 확장)\n$$P(C|D) = \\frac{P(C) \\cdot P(D|C)}{P(D)}$$\n\n**Step 1. 사전 확률과 불량률**\n$P(A) = 0.5$, $P(B) = 0.3$, $P(C) = 0.2$\n$P(D|A) = 0.02$, $P(D|B) = 0.03$, $P(D|C) = 0.05$\n\n**Step 2. 전확률**\n$$P(D) = 0.5 \\times 0.02 + 0.3 \\times 0.03 + 0.2 \\times 0.05$$\n$$= 0.010 + 0.009 + 0.010 = 0.029$$\n\n**Step 3. 베이즈 정리**\n$$P(C|D) = \\frac{0.2 \\times 0.05}{0.029} = \\frac{0.010}{0.029} = \\frac{10}{29}$$\n\n**Step 4. 기약분수 확인**\n$\\gcd(10, 29) = 1$ ($29$는 소수) → 기약분수\n$p = 10$, $q = 29$\n$$p \\times q = 10 \\times 29 = 290$$\n\n**Step 5. 검증**\n$P(A|D) = \\frac{0.010}{0.029} = \\frac{10}{29}$\n$P(B|D) = \\frac{0.009}{0.029} = \\frac{9}{29}$\n$P(C|D) = \\frac{10}{29}$\n합: $\\frac{10+9+10}{29} = \\frac{29}{29} = 1$ ✓\n\n흥미로운 결과: C의 생산량은 가장 적지만(20%) 불량률이 높아서(5%), A(50%, 2%)와 같은 사후 확률을 가집니다.\n\n**∴ 답: 290**\n\n**💡 포인트:** 베이즈 정리에서 사후 확률은 (사전 확률 × 우도)에 비례합니다. 생산량이 적어도 불량률이 높으면 사후 확률이 높아질 수 있습니다.",
