    "explanation": "**[풀이]**\n\n**핵심 개념:** 누적확률은 해당 값 이하의 모든 확률의 합입니다.\n$$P(X \\leq a) = \\sum_{x_i \\leq a} P(X = x_i)$$\n\n**Step 1. 확률의 합 검증**\n$0.1 + 0.3 + 0.4 + 0.2 = 1.0$ ✓\n\n**Step 2. $P(X \\leq 2)$ 계산**\n$$P(X \\leq 2) = P(X = 1) + P(X = 2)$$\n$$= 0.1 + 0.3 = 0.4$$\n\n**Step 3. 검증 — 여사건 활용**\n$$P(X \\leq 2) = 1 - P(X \\geq 3) = 1 - (0.4 + 0.2) = 1 - 0.6 = 0.4 \\checkmark$$\n\n두 방법의 결과가 일치하므로 정답이 맞습니다.\n\n**∴ 답: ③ 0.4**\n\n② 0.3은 $P(X=2)$만 구한 것이고, ⑤ 0.6은 $P(X \\geq 3)$을 구한 것입니다. $P(X \\leq 2)$는 $X=1$과 $X=2$의 확률을 모두 더해야 합니다.\n\n**💡 포인트:** $P(X \\leq a)$는 $X$가 $a$ '이하'인 모든 값의 확률을 합산합니다. 부등호의 방향과 등호 포함 여부를 항상 주의하세요.\n\n**보충:** 누적분포함수(CDF) $F(x) = P(X \\leq x)$는 이산확률변수에서 계단함수 형태를 띱니다. 여사건을 활용한 검증은 계산 실수를 방지하는 좋은 습관입니다.",
