    "answerType": "short",
    "choices": null,
    "answer": 6,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 기댓값의 선형성\n$$E(aX + b) = aE(X) + b$$\n\n**Step 1. 확률의 합 검증**\n$$\\frac{1}{2} + \\frac{1}{3} + \\frac{1}{6} = \\frac{3+2+1}{6} = \\frac{6}{6} = 1 \\checkmark$$\n\n**Step 2. $E(X)$ 계산**\n$$E(X) = 1 \\times \\frac{1}{2} + 2 \\times \\frac{1}{3} + 3 \\times \\frac{1}{6}$$\n$$= \\frac{1}{2} + \\frac{2}{3} + \\frac{3}{6} = \\frac{3}{6} + \\frac{4}{6} + \\frac{3}{6} = \\frac{10}{6} = \\frac{5}{3}$$\n\n**Step 3. $E(3X+1)$ 계산**\n$$E(3X+1) = 3E(X) + 1 = 3 \\times \\frac{5}{3} + 1 = 5 + 1 = 6$$\n\n**Step 4. 검증 — 직접 계산**\n$3X+1$은 4, 7, 10의 값을 각각 $\\frac{1}{2}$, $\\frac{1}{3}$, $\\frac{1}{6}$의 확률로 가집니다.\n$$E(3X+1) = 4 \\times \\frac{1}{2} + 7 \\times \\frac{1}{3} + 10 \\times \\frac{1}{6}$$\n$$= 2 + \\frac{7}{3} + \\frac{10}{6} = \\frac{12}{6} + \\frac{14}{6} + \\frac{10}{6} = \\frac{36}{6} = 6 \\checkmark$$\n\n**∴ 답: 6**\n\n**💡 포인트:** $E(aX+b) = aE(X)+b$를 활용하면, $3X+1$의 확률분포를 따로 만들지 않고도 빠르게 계산할 수 있습니다.\n\n**보충:** 기댓값의 선형성은 $X$의 분포에 관계없이 항상 성립하는 매우 강력한 성질입니다. 이 성질은 수능에서 가장 빈출되는 공식 중 하나입니다.",
