    "explanation": "**[풀이]**\n\n**핵심 개념:** 분산의 정의와 간편 공식\n$$V(X) = E(X^2) - \\{E(X)\\}^2$$\n\n**Step 1. $E(X)$ 계산**\n$$E(X) = 1 \\times \\frac{1}{4} + 2 \\times \\frac{1}{2} + 3 \\times \\frac{1}{4} = \\frac{1}{4} + 1 + \\frac{3}{4} = 2$$\n\n**Step 2. $E(X^2)$ 계산**\n$$E(X^2) = 1^2 \\times \\frac{1}{4} + 2^2 \\times \\frac{1}{2} + 3^2 \\times \\frac{1}{4}$$\n$$= \\frac{1}{4} + 2 + \\frac{9}{4} = \\frac{1+8+9}{4} = \\frac{18}{4} = \\frac{9}{2}$$\n\n**Step 3. 분산 계산**\n$$V(X) = E(X^2) - \\{E(X)\\}^2 = \\frac{9}{2} - 4 = \\frac{9}{2} - \\frac{8}{2} = \\frac{1}{2}$$\n\n**Step 4. 검증 — 정의로 직접 계산**\n$$V(X) = (1-2)^2 \\times \\frac{1}{4} + (2-2)^2 \\times \\frac{1}{2} + (3-2)^2 \\times \\frac{1}{4}$$\n$$= 1 \\times \\frac{1}{4} + 0 + 1 \\times \\frac{1}{4} = \\frac{1}{2} \\checkmark$$\n\n분포가 $E(X)=2$를 중심으로 대칭이므로, 분산이 비교적 작은 $\\frac{1}{2}$인 것은 합리적입니다.\n\n**∴ 답: ② 1/2**\n\n① $\\frac{1}{4}$는 $(X-\\mu)^2$의 한 항만 계산한 것이고, ③ $\\frac{3}{4}$는 계산 과정에서 오류가 있는 경우입니다.\n\n**💡 포인트:** 분산 계산에는 간편 공식 $V(X) = E(X^2) - \\{E(X)\\}^2$이 효율적이며, 정의 $V(X) = E[(X-\\mu)^2]$로 검증할 수 있습니다.\n\n**보충:** 이 분포는 평균을 중심으로 좌우 대칭이므로 왜도(skewness)가 0입니다. 대칭 분포에서는 분산만으로 산포를 완전히 설명할 수 있습니다.",
