    "explanation": "**[풀이]**\n\n**핵심 개념:** 기댓값과 분산의 선형변환 공식\n$$E(aX + b) = aE(X) + b$$\n$$V(aX + b) = a^2 V(X)$$\n\n**Step 1. $E(2X+5)$ 계산**\n$$E(2X+5) = 2E(X) + 5 = 2 \\times 3 + 5 = 11$$\n\n**Step 2. $V(2X+5)$ 계산**\n$$V(2X+5) = 2^2 \\cdot V(X) = 4 \\times 4 = 16$$\n\n**Step 3. 핵심 차이점 확인**\n기댓값에서는 상수 $b$가 더해지지만, 분산에서는 상수 $b$의 영향이 없습니다. 이는 분산이 '산포도'를 나타내므로, 전체를 같은 양만큼 평행이동해도 흩어진 정도는 변하지 않기 때문입니다. ✓\n\n**∴ 답: ① 11, 16**\n\n② $(11, 8)$은 $V(2X+5) = 2 \\times V(X)$로 잘못 계산한 것이고, ③ $(11, 4)$는 분산에 선형변환을 적용하지 않은 것입니다.\n\n**💡 포인트:** 분산 공식에서 계수는 **제곱**으로 들어갑니다: $V(aX+b) = a^2 V(X)$. 이때 $b$는 분산에 영향을 주지 않습니다. 이 차이를 반드시 기억하세요.\n\n**보충:** 표준편차로는 $\\sigma(2X+5) = |2| \\cdot \\sigma(X) = 2 \\times 2 = 4$입니다. 표준편차에서는 절댓값이 붙어 $\\sigma(aX+b) = |a|\\sigma(X)$가 됩니다.",
