    "explanation": "**[풀이]**\n\n**핵심 개념:** 분산과 $E(X^2)$의 관계\n$$V(X) = E(X^2) - \\{E(X)\\}^2 \\implies E(X^2) = V(X) + \\{E(X)\\}^2$$\n\n**Step 1. 공식 적용**\n$$E(X^2) = V(X) + \\{E(X)\\}^2 = 5 + 4^2 = 5 + 16 = 21$$\n\n**Step 2. 검증**\n역으로 $V(X)$를 구하면:\n$$V(X) = E(X^2) - \\{E(X)\\}^2 = 21 - 16 = 5 \\checkmark$$\n\n주어진 조건과 일치합니다.\n\n**∴ 답: 21**\n\n**💡 포인트:** $V(X) = E(X^2) - \\{E(X)\\}^2$를 변형하면 $E(X^2) = V(X) + \\{E(X)\\}^2$입니다. 이 관계식은 양방향으로 활용할 수 있어야 합니다.\n\n**보충:** $E(X^2)$는 '이차 모멘트'라고 불리며, 기댓값(일차 모멘트)과 분산의 관계를 잇는 중요한 양입니다. $E(X^2) \\geq \\{E(X)\\}^2$가 항상 성립하며(분산이 0 이상이므로), 등호는 $X$가 상수일 때만 성립합니다.\n\n이 공식은 수능에서 매우 자주 출제되므로, 세 가지 양($E(X)$, $E(X^2)$, $V(X)$) 중 두 개가 주어지면 나머지 하나를 구할 수 있어야 합니다.",
