    "problem": "확률변수 $X$에 대해 $E(X) = 2$, $V(X) = 3$일 때, $E\\left((X-1)^2\\right)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[풀이]**\n\n**핵심 개념:** $(X-1)^2$를 전개하여 기댓값의 성질을 활용합니다.\n\n**Step 1. $(X-1)^2$ 전개**\n$$(X-1)^2 = X^2 - 2X + 1$$\n\n**Step 2. 기댓값 계산**\n$$E\\left((X-1)^2\\right) = E(X^2) - 2E(X) + 1$$\n\n**Step 3. $E(X^2)$ 구하기**\n$$E(X^2) = V(X) + \\{E(X)\\}^2 = 3 + 4 = 7$$\n\n**Step 4. 대입**\n$$E\\left((X-1)^2\\right) = 7 - 2 \\times 2 + 1 = 7 - 4 + 1 = 4$$\n\n**Step 5. 검증 — 다른 방법**\n$E\\left((X-1)^2\\right) = V(X-1) + \\{E(X-1)\\}^2$\n$V(X-1) = V(X) = 3$ (상수 이동은 분산에 영향 없음)\n$E(X-1) = E(X) - 1 = 2 - 1 = 1$\n$\\therefore E\\left((X-1)^2\\right) = 3 + 1^2 = 4 \\checkmark$\n\n**∴ 답: 4**\n\n**💡 포인트:** $E\\left((X-a)^2\\right)$를 전개하여 계산하는 방법과, $V(X-a) + \\{E(X-a)\\}^2$로 변환하는 방법 두 가지를 모두 알아 두세요.\n\n**보충:** $E\\left((X-a)^2\\right)$가 최소가 되는 $a$의 값은 $a = E(X)$이며, 이때 최솟값은 $V(X)$입니다. 이 성질은 $E\\left((X-a)^2\\right) = V(X) + (E(X)-a)^2$에서 확인할 수 있습니다.",
