    "problem": "확률변수 $X$에 대해 $E(2X+1) = 9$, $V(2X+1) = 16$일 때, $E(X) + V(X)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 8,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 기댓값과 분산의 선형변환 공식을 역으로 활용합니다.\n$$E(aX+b) = aE(X)+b, \\quad V(aX+b) = a^2 V(X)$$\n\n**Step 1. $E(X)$ 구하기**\n$$E(2X+1) = 2E(X) + 1 = 9$$\n$$2E(X) = 8 \\implies E(X) = 4$$\n\n**Step 2. $V(X)$ 구하기**\n$$V(2X+1) = 2^2 \\cdot V(X) = 16$$\n$$4 \\cdot V(X) = 16 \\implies V(X) = 4$$\n\n**Step 3. 답 계산**\n$$E(X) + V(X) = 4 + 4 = 8$$\n\n**Step 4. 검증**\n$E(2X+1) = 2 \\times 4 + 1 = 9$ ✓\n$V(2X+1) = 4 \\times 4 = 16$ ✓\n\n**∴ 답: 8**\n\n**💡 포인트:** 선형변환 후의 기댓값과 분산이 주어졌을 때, 원래 확률변수의 기댓값과 분산을 역산하는 문제입니다. $E(aX+b) = aE(X)+b$에서 $E(X) = \\frac{E(aX+b)-b}{a}$, $V(aX+b) = a^2 V(X)$에서 $V(X) = \\frac{V(aX+b)}{a^2}$로 구합니다.\n\n**보충:** 이 유형은 수능에서 자주 출제됩니다. 선형변환 공식을 정확히 외우고, 역방향으로도 활용할 수 있어야 합니다. 특히 분산에서 계수가 제곱으로 들어간다는 점을 잊지 마세요.",
