    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포 $B(n, p)$의 기댓값과 분산\n$$E(X) = np, \\quad V(X) = np(1-p)$$\n\n**Step 1. 기댓값 계산**\n$X \\sim B(10, 0.3)$이므로:\n$$E(X) = np = 10 \\times 0.3 = 3$$\n\n**Step 2. 의미 해석**\n성공 확률이 $0.3$인 시행을 10번 반복하면, 평균적으로 3번 성공한다는 의미입니다.\n\n**Step 3. 검증 — 분산도 확인**\n$$V(X) = np(1-p) = 10 \\times 0.3 \\times 0.7 = 2.1$$\n$E(X) = 3$, $V(X) = 2.1$이므로 $\\sigma(X) \\approx 1.45$. 따라서 $X$의 값은 대략 $3 \\pm 1.45$, 즉 1.55~4.45 범위에 자주 분포하며, 이는 합리적입니다. ✓\n\n**∴ 답: ③ 3**\n\n⑤ 7은 $E(X) = n(1-p) = 10 \\times 0.7$으로 실패 횟수의 기댓값을 구한 오답입니다.\n\n**💡 포인트:** 이항분포 $B(n,p)$에서 $E(X) = np$, $V(X) = np(1-p)$는 가장 기본적인 공식입니다. 반드시 암기하세요.\n\n**보충:** 이항분포는 독립 베르누이 시행의 성공 횟수를 나타내는 분포입니다. $n$이 크고 $p$가 극단적이지 않으면 정규분포에 근사할 수 있습니다(정규근사).",
