    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포 $B(n, p)$의 분산\n$$V(X) = np(1-p)$$\n\n**Step 1. 분산 계산**\n$X \\sim B(20, \\frac{1}{4})$이므로:\n$$V(X) = 20 \\times \\frac{1}{4} \\times \\left(1 - \\frac{1}{4}\\right) = 20 \\times \\frac{1}{4} \\times \\frac{3}{4} = \\frac{60}{16} = \\frac{15}{4}$$\n\n**Step 2. 참고 — 기댓값**\n$$E(X) = np = 20 \\times \\frac{1}{4} = 5$$\n\n**Step 3. 검증**\n$V(X) = \\frac{15}{4} = 3.75$\n$\\sigma(X) = \\sqrt{\\frac{15}{4}} = \\frac{\\sqrt{15}}{2} \\approx 1.94$\n$E(X) \\pm 2\\sigma(X) \\approx 5 \\pm 3.87$, 즉 약 1.13~8.87 범위에 대부분의 값이 분포합니다. 20회 시행에서 성공률 25%이면 0~8번 성공이 대부분이므로 합리적입니다. ✓\n\n**∴ 답: ③ 15/4**\n\n④ 5는 $E(X)$의 값이며, ② $\\frac{5}{2}$는 $np(1-p)$에서 $1-p = \\frac{1}{2}$로 잘못 계산한 오답입니다.\n\n**💡 포인트:** $V(X) = np(1-p)$에서 $(1-p)$를 정확히 대입하세요. $p = \\frac{1}{4}$이면 $1-p = \\frac{3}{4}$입니다.\n\n**보충:** 이항분포의 분산 $np(1-p)$는 $p = \\frac{1}{2}$일 때 최대($\\frac{n}{4}$)이고, $p$가 0이나 1에 가까울수록 작아집니다.",
