    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포 $B(n, p)$의 분산 공식을 역으로 활용합니다.\n$$V(X) = np(1-p) = 4$$\n\n**Step 1. 분산 공식에 대입**\n$$n \\times \\frac{1}{3} \\times \\frac{2}{3} = 4$$\n$$\\frac{2n}{9} = 4$$\n\n**Step 2. $n$ 구하기**\n$$n = 4 \\times \\frac{9}{2} = 18$$\n\n**Step 3. 검증**\n$V(X) = 18 \\times \\frac{1}{3} \\times \\frac{2}{3} = 18 \\times \\frac{2}{9} = \\frac{36}{9} = 4 \\checkmark$\n$E(X) = 18 \\times \\frac{1}{3} = 6$\n\n18번 시행에서 성공 확률 $\\frac{1}{3}$이면 기댓값 6, 분산 4는 합리적입니다.\n\n**∴ 답: ③ 18**\n\n① 12를 대입하면 $V = 12 \\times \\frac{1}{3} \\times \\frac{2}{3} = \\frac{8}{3} \\neq 4$이고, ④ 24를 대입하면 $V = 24 \\times \\frac{2}{9} = \\frac{16}{3} \\neq 4$입니다.\n\n**💡 포인트:** 이항분포의 모수를 구하는 문제에서는 $E(X) = np$, $V(X) = np(1-p)$를 연립하거나, 주어진 조건에 직접 대입합니다.\n\n**보충:** $V(X) = np(1-p)$에서 $n = \\frac{V(X)}{p(1-p)}$로 변형할 수 있습니다. $p(1-p) = \\frac{1}{3} \\times \\frac{2}{3} = \\frac{2}{9}$이므로 $n = \\frac{4}{2/9} = 18$입니다.",
