    "answer": 1,
    "explanation": "**[풀이]**\n\n**핵심 개념:** $E(X^2) = V(X) + \\{E(X)\\}^2$를 활용합니다.\n\n**Step 1. 기댓값과 분산 계산**\n$X \\sim B(8, \\frac{1}{4})$이므로:\n$$E(X) = np = 8 \\times \\frac{1}{4} = 2$$\n$$V(X) = np(1-p) = 8 \\times \\frac{1}{4} \\times \\frac{3}{4} = \\frac{24}{16} = \\frac{3}{2}$$\n\n**Step 2. $E(X^2)$ 계산**\n$$E(X^2) = V(X) + \\{E(X)\\}^2 = \\frac{3}{2} + 4 = \\frac{3}{2} + \\frac{8}{2} = \\frac{11}{2}$$\n\n**Step 3. 검증**\n$V(X) = E(X^2) - \\{E(X)\\}^2 = \\frac{11}{2} - 4 = \\frac{3}{2}$ ✓\n\n**∴ 답: ② 11/2**\n\n① $\\frac{5}{2}$는 $E(X^2) = V(X) + E(X)$로 잘못 계산한 것이며, ④ $\\frac{21}{4}$는 $V(X)$를 $\\frac{5}{4}$로 잘못 구한 경우입니다.\n\n**💡 포인트:** 이항분포에서 $E(X^2)$를 직접 구하기는 어렵지만, $E(X^2) = V(X) + \\{E(X)\\}^2$를 활용하면 간단합니다. 이항분포의 $E(X)$와 $V(X)$를 먼저 구한 후 변환하세요.\n\n**보충:** 이항분포에서 $E(X(X-1)) = n(n-1)p^2$라는 공식도 유용합니다. 이를 이용하면 $E(X^2) = E(X(X-1)) + E(X) = n(n-1)p^2 + np$로도 구할 수 있습니다. $8 \\times 7 \\times \\frac{1}{16} + 2 = \\frac{7}{2} + 2 = \\frac{11}{2}$ ✓",
