    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 기댓값과 분산을 연립하여 모수를 구합니다.\n$$E(X) = np = 6, \\quad V(X) = np(1-p) = 2$$\n\n**Step 1. 두 식의 비를 이용하여 $p$ 구하기**\n$$\\frac{V(X)}{E(X)} = \\frac{np(1-p)}{np} = 1-p = \\frac{2}{6} = \\frac{1}{3}$$\n$$\\therefore p = 1 - \\frac{1}{3} = \\frac{2}{3}$$\n\n**Step 2. $n$ 구하기**\n$$np = 6 \\implies n \\times \\frac{2}{3} = 6 \\implies n = 6 \\times \\frac{3}{2} = 9$$\n\n**Step 3. 검증**\n$E(X) = 9 \\times \\frac{2}{3} = 6$ ✓\n$V(X) = 9 \\times \\frac{2}{3} \\times \\frac{1}{3} = \\frac{18}{9} = 2$ ✓\n\n**∴ 답: 9**\n\n**💡 포인트:** $\\frac{V(X)}{E(X)} = 1-p$라는 관계식을 이용하면 $p$를 먼저 구할 수 있습니다. 이는 이항분포의 모수를 구하는 가장 효율적인 방법입니다.\n\n**보충:** 이항분포에서 $\\frac{V(X)}{E(X)} = 1-p < 1$이 항상 성립합니다($p > 0$일 때). 따라서 이항분포에서는 항상 분산 < 기댓값입니다(단, $p > 0$). 이 성질은 포아송 분포($V = E$)와의 차이점이기도 합니다.",
