    "answer": 33,
    "explanation": "**[풀이]**\n\n**핵심 개념:** $X \\sim B(12, \\frac{1}{2})$이며, $E(X(X-1)) = n(n-1)p^2$를 활용합니다.\n\n**Step 1. 기본량 계산**\n$$E(X) = np = 12 \\times \\frac{1}{2} = 6$$\n$$V(X) = np(1-p) = 12 \\times \\frac{1}{2} \\times \\frac{1}{2} = 3$$\n\n**Step 2. $E(X^2)$ 계산**\n$$E(X^2) = V(X) + \\{E(X)\\}^2 = 3 + 36 = 39$$\n\n아니면, $E(X(X-1)) = n(n-1)p^2 = 12 \\times 11 \\times \\frac{1}{4} = 33$\n$E(X^2) = E(X(X-1)) + E(X) = 33 + 6 = 39$\n\n**Step 3. 답 계산**\n$$E(X^2) - E(X) = 39 - 6 = 33$$\n\n또는 직접: $E(X^2 - X) = E(X(X-1)) = n(n-1)p^2 = 12 \\times 11 \\times \\frac{1}{4} = 33$\n\n**Step 4. 검증**\n$E(X(X-1)) = n(n-1)p^2 = 12 \\times 11 \\times \\frac{1}{4} = 33$ ✓\n\n**∴ 답: 33**\n\n**💡 포인트:** $E(X^2) - E(X) = E(X(X-1))$로 변환하면, 이항분포의 팩토리얼 모멘트 공식 $E(X(X-1)) = n(n-1)p^2$를 직접 사용할 수 있어 계산이 한 단계 줄어듭니다.\n\n**보충:** 이항분포의 팩토리얼 모멘트: $E(X(X-1)\\cdots(X-r+1)) = n(n-1)\\cdots(n-r+1) p^r$. 이를 이용하면 고차 모멘트도 효율적으로 계산할 수 있습니다.",
