    "problem": "확률변수 $X$가 이항분포 $B(100, 0.4)$를 따를 때, $\\sigma(2X - 10)$의 값을 구하시오. (답이 $a\\sqrt{b}$ 형태일 때, $a+b$의 값을 구하시오. 단, $b$는 제곱인수를 갖지 않는 자연수)",
    "answerType": "short",
    "choices": null,
    "answer": 10,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 분산과 선형변환 후 표준편차\n$$\\sigma(aX+b) = |a| \\cdot \\sigma(X)$$\n\n**Step 1. $V(X)$ 계산**\n$X \\sim B(100, 0.4)$이므로:\n$$V(X) = np(1-p) = 100 \\times 0.4 \\times 0.6 = 24$$\n$$\\sigma(X) = \\sqrt{24} = 2\\sqrt{6}$$\n\n**Step 2. $\\sigma(2X-10)$ 계산**\n$$\\sigma(2X-10) = |2| \\times \\sigma(X) = 2 \\times 2\\sqrt{6} = 4\\sqrt{6}$$\n\n**Step 3. 답 구하기**\n$a\\sqrt{b} = 4\\sqrt{6}$이므로 $a = 4$, $b = 6$\n$6 = 2 \\times 3$으로 제곱인수가 없습니다. ✓\n$$a + b = 4 + 6 = 10$$\n\n**Step 4. 검증**\n$\\sigma(2X-10)^2 = V(2X-10) = 4 \\times 24 = 96$\n$(4\\sqrt{6})^2 = 16 \\times 6 = 96$ ✓\n\n**∴ 답: 10**\n\n**💡 포인트:** $\\sigma(aX+b) = |a|\\sigma(X)$에서 상수항 $b$는 표준편차에 영향을 주지 않습니다. $\\sqrt{}$ 안의 수를 소인수분해하여 제곱인수를 밖으로 빼내는 정리도 중요합니다.\n\n**보충:** $\\sqrt{24} = \\sqrt{4 \\times 6} = 2\\sqrt{6}$처럼 근호 안의 수를 간단히 하는 과정은 수능에서 자주 요구됩니다. $24 = 2^3 \\times 3$이므로 $\\sqrt{24} = 2\\sqrt{6}$이 됩니다.",
