    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립인 확률변수의 합의 분산\n$$V(X + Y) = V(X) + V(Y) \\quad (\\text{독립일 때})$$\n\n또한, 같은 $p$를 가진 이항분포의 합: $X + Y \\sim B(n_1 + n_2, p)$\n\n**Step 1. 방법 1 — 직접 분산 합산**\n$$V(X) = 10 \\times \\frac{1}{3} \\times \\frac{2}{3} = \\frac{20}{9}$$\n$$V(Y) = 20 \\times \\frac{1}{3} \\times \\frac{2}{3} = \\frac{40}{9}$$\n$$V(X+Y) = \\frac{20}{9} + \\frac{40}{9} = \\frac{60}{9} = \\frac{20}{3}$$\n\n**Step 2. 방법 2 — 분포의 재생성**\n$X$와 $Y$가 독립이고 같은 $p = \\frac{1}{3}$을 가지므로:\n$$X + Y \\sim B(30, \\frac{1}{3})$$\n$$V(X+Y) = 30 \\times \\frac{1}{3} \\times \\frac{2}{3} = \\frac{60}{9} = \\frac{20}{3}$$\n\n**Step 3. 검증**\n두 방법의 결과가 일치합니다. ✓\n$\\frac{20}{3} \\approx 6.67$이며, 30번 시행에서 성공확률 $\\frac{1}{3}$인 이항분포의 분산으로 합리적입니다.\n\n**∴ 답: ② 20/3**\n\n① $\\frac{40}{9}$는 $V(Y)$만 구한 것이며, ④ $\\frac{70}{9}$는 계산 오류입니다.\n\n**💡 포인트:** 이항분포의 재생성 — 같은 성공 확률 $p$를 가진 독립인 이항분포의 합은 다시 이항분포입니다: $B(n_1, p) + B(n_2, p) = B(n_1 + n_2, p)$.\n\n**보충:** 재생성은 $p$가 같을 때만 성립합니다. $p$가 다르면 합은 이항분포가 되지 않으며, 이 경우에는 개별 분산을 합산하는 방법만 사용해야 합니다.",
