    "explanation": "**[풀이]**\n\n**핵심 개념:** $(X-Y)^2$를 전개하고 독립성을 활용합니다.\n$$E((X-Y)^2) = V(X-Y) + \\{E(X-Y)\\}^2$$\n\n**Step 1. 기댓값 계산**\n$E(X) = 5 \\times \\frac{1}{2} = \\frac{5}{2}$\n$E(Y) = 3 \\times \\frac{1}{2} = \\frac{3}{2}$\n$E(X-Y) = \\frac{5}{2} - \\frac{3}{2} = 1$\n\n**Step 2. 분산 계산**\n$V(X) = 5 \\times \\frac{1}{2} \\times \\frac{1}{2} = \\frac{5}{4}$\n$V(Y) = 3 \\times \\frac{1}{2} \\times \\frac{1}{2} = \\frac{3}{4}$\n$X$와 $Y$가 독립이므로:\n$V(X-Y) = V(X) + V(Y) = \\frac{5}{4} + \\frac{3}{4} = 2$\n\n**Step 3. 결과 합산**\n$$E((X-Y)^2) = V(X-Y) + \\{E(X-Y)\\}^2 = 2 + 1 = 3$$\n\n**Step 4. 검증 — 전개로 확인**\n$E((X-Y)^2) = E(X^2) - 2E(XY) + E(Y^2)$\n독립이므로 $E(XY) = E(X)E(Y) = \\frac{5}{2} \\times \\frac{3}{2} = \\frac{15}{4}$\n$E(X^2) = V(X) + (E(X))^2 = \\frac{5}{4} + \\frac{25}{4} = \\frac{30}{4}$\n$E(Y^2) = V(Y) + (E(Y))^2 = \\frac{3}{4} + \\frac{9}{4} = 3$\n$E((X-Y)^2) = \\frac{30}{4} - 2 \\times \\frac{15}{4} + 3 = \\frac{30}{4} - \\frac{30}{4} + 3 = 3$ ✓\n\n**∴ 답: ③ 3**\n\n**💡 포인트:** $E((X-Y)^2) = V(X-Y) + \\{E(X-Y)\\}^2$을 활용하면 복잡한 전개 없이 빠르게 계산할 수 있습니다. 독립일 때 $V(X \\pm Y) = V(X) + V(Y)$임을 기억하세요.\n\n**보충:** 독립인 확률변수의 차의 분산은 합의 분산과 같습니다: $V(X-Y) = V(X) + (-1)^2 V(Y) = V(X) + V(Y)$. 부호가 바뀌어도 분산은 항상 더해집니다.",
