    "explanation": "**[풀이]**\n\n**핵심 개념:** 확률의 합 = 1 조건으로 상수 $c$를 결정한 후 기댓값을 구합니다.\n\n**Step 1. 상수 $c$ 결정**\n$$\\sum_{k=1}^{4} c \\cdot k^2 = 1$$\n$$c(1^2 + 2^2 + 3^2 + 4^2) = c(1 + 4 + 9 + 16) = 30c = 1$$\n$$c = \\frac{1}{30}$$\n\n**Step 2. 기댓값 계산**\n$$E(X) = \\sum_{k=1}^{4} k \\cdot P(X=k) = \\sum_{k=1}^{4} k \\cdot \\frac{k^2}{30} = \\frac{1}{30}\\sum_{k=1}^{4} k^3$$\n$$= \\frac{1}{30}(1 + 8 + 27 + 64) = \\frac{100}{30} = \\frac{10}{3}$$\n\n**Step 3. 검증**\n확률 검증: $P(1)=\\frac{1}{30}$, $P(2)=\\frac{4}{30}$, $P(3)=\\frac{9}{30}$, $P(4)=\\frac{16}{30}$\n합: $\\frac{1+4+9+16}{30} = \\frac{30}{30} = 1$ ✓\n\n$P(X=4) = \\frac{16}{30}$으로 가장 크므로 기댓값이 4에 가까운 $\\frac{10}{3} \\approx 3.33$은 합리적입니다. ✓\n\n**∴ 답: ④ 10/3**\n\n⑤ $\\frac{100}{30}$은 약분하지 않은 형태이며 ④와 같은 값이지만, 기약분수로 나타내면 $\\frac{10}{3}$입니다.\n\n**💡 포인트:** $\\sum k^2 = \\frac{n(n+1)(2n+1)}{6}$, $\\sum k^3 = \\left(\\frac{n(n+1)}{2}\\right)^2$이라는 공식을 활용하면 더 빠르게 계산할 수 있습니다.\n\n**보충:** $\\sum_{k=1}^{4} k^3 = (1+2+3+4)^2/(기형 아님) = \\left(\\frac{4 \\times 5}{2}\\right)^2 = 100$. 이 공식($\\sum k^3 = (\\sum k)^2$)은 매우 유용합니다.",
