    "explanation": "**[풀이]**\n\n**핵심 개념:** $V(X) = E(X^2) - \\{E(X)\\}^2$\n\n**Step 1. 확률 검증**\n$\\sum_{k=1}^{5} \\frac{k}{15} = \\frac{1+2+3+4+5}{15} = \\frac{15}{15} = 1$ ✓\n\n**Step 2. $E(X)$ 계산**\n$$E(X) = \\sum_{k=1}^{5} k \\cdot \\frac{k}{15} = \\frac{1}{15}\\sum_{k=1}^{5} k^2 = \\frac{1+4+9+16+25}{15} = \\frac{55}{15} = \\frac{11}{3}$$\n\n**Step 3. $E(X^2)$ 계산**\n$$E(X^2) = \\sum_{k=1}^{5} k^2 \\cdot \\frac{k}{15} = \\frac{1}{15}\\sum_{k=1}^{5} k^3 = \\frac{1+8+27+64+125}{15} = \\frac{225}{15} = 15$$\n\n**Step 4. 분산 계산**\n$$V(X) = 15 - \\left(\\frac{11}{3}\\right)^2 = 15 - \\frac{121}{9} = \\frac{135 - 121}{9} = \\frac{14}{9}$$\n\n**Step 5. 기약분수 확인**\n$\\gcd(14, 9) = 1$ → 기약분수\n$p = 14$, $q = 9$\n\n$$p + q = 14 + 9 = 23$$\n\n**Step 6. 검증**\n$V(X) = \\frac{14}{9} \\approx 1.56$, $\\sigma(X) \\approx 1.25$\n$E(X) \\pm \\sigma(X) \\approx 3.67 \\pm 1.25$, 즉 2.42~4.91 범위. 합리적입니다. ✓\n\n**∴ 답: 23**\n\n**💡 포인트:** $P(X=k) = \\frac{k}{c}$ 형태의 확률분포에서는 $\\sum k$, $\\sum k^2$, $\\sum k^3$ 공식이 핵심입니다.\n\n**보충:** $\\sum_{k=1}^{n} k = \\frac{n(n+1)}{2}$, $\\sum k^2 = \\frac{n(n+1)(2n+1)}{6}$, $\\sum k^3 = \\left(\\frac{n(n+1)}{2}\\right)^2$. 이 세 공식은 확률분포 문제에서 필수적입니다.",
