    "problem": "독립인 확률변수 $X_1, X_2, \\ldots, X_9$가 각각 이항분포 $B(4, \\frac{1}{2})$를 따를 때, $Y = X_1 + X_2 + \\cdots + X_9$의 분산을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립인 확률변수의 합의 분산과 이항분포의 재생성\n\n**Step 1. 방법 1 — 분산의 합**\n각 $X_i \\sim B(4, \\frac{1}{2})$이므로:\n$$V(X_i) = 4 \\times \\frac{1}{2} \\times \\frac{1}{2} = 1$$\n\n독립이므로:\n$$V(Y) = \\sum_{i=1}^{9} V(X_i) = 9 \\times 1 = 9$$\n\n**Step 2. 방법 2 — 재생성**\n$X_i$가 독립이고 모두 $p = \\frac{1}{2}$이므로:\n$$Y = \\sum_{i=1}^{9} X_i \\sim B(4 \\times 9, \\frac{1}{2}) = B(36, \\frac{1}{2})$$\n$$V(Y) = 36 \\times \\frac{1}{2} \\times \\frac{1}{2} = 9$$\n\n**Step 3. 검증**\n$E(Y) = 36 \\times \\frac{1}{2} = 18$\n$V(Y) = 9$, $\\sigma(Y) = 3$\n$E(Y) \\pm 2\\sigma(Y) = 18 \\pm 6$, 즉 12~24 범위에 약 95%가 분포. 36번 중 12~24번 성공은 합리적입니다. ✓\n\n**∴ 답: 9**\n\n**💡 포인트:** 같은 $p$를 가진 독립 이항분포의 합은 재생성에 의해 $B(\\sum n_i, p)$를 따릅니다. 이를 활용하면 기댓값과 분산을 한 번에 구할 수 있습니다.\n\n**보충:** $n$개의 독립 동일 분포(i.i.d.) 확률변수 $X_i$의 합 $Y = \\sum X_i$에 대해 $E(Y) = nE(X_i)$, $V(Y) = nV(X_i)$입니다. 이는 중심극한정리의 기초가 되는 성질입니다.",
