    "problem": "확률변수 $X$가 이항분포 $B(n, p)$를 따르고 $E(X) = 8$, $E(X^2) = 68$일 때, $n$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 16,
    "explanation": "**[풀이]**\n\n**핵심 개념:** $V(X) = E(X^2) - \\{E(X)\\}^2$와 이항분포의 성질을 결합합니다.\n\n**Step 1. $V(X)$ 계산**\n$$V(X) = E(X^2) - \\{E(X)\\}^2 = 68 - 64 = 4$$\n\n**Step 2. $p$ 구하기**\n$$\\frac{V(X)}{E(X)} = 1 - p = \\frac{4}{8} = \\frac{1}{2}$$\n$$p = \\frac{1}{2}$$\n\n**Step 3. $n$ 구하기**\n$$E(X) = np = n \\times \\frac{1}{2} = 8$$\n$$n = 16$$\n\n**Step 4. 검증**\n$X \\sim B(16, \\frac{1}{2})$:\n$E(X) = 16 \\times \\frac{1}{2} = 8$ ✓\n$V(X) = 16 \\times \\frac{1}{2} \\times \\frac{1}{2} = 4$ ✓\n$E(X^2) = V(X) + (E(X))^2 = 4 + 64 = 68$ ✓\n\n**∴ 답: 16**\n\n**💡 포인트:** $\\frac{V(X)}{E(X)} = 1-p$는 이항분포의 모수를 구하는 핵심 관계식입니다. $E(X)$와 $E(X^2)$가 주어지면 $V(X)$를 먼저 구한 후 이 관계식을 적용합니다.\n\n**보충:** 이 문제는 $E(X)$와 $E(X^2)$라는 1차, 2차 모멘트로부터 모수 $n$과 $p$를 추정하는 '모멘트 방법(method of moments)'의 기초적인 예시입니다. 통계학에서 중요한 추정 방법 중 하나입니다.",
