    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 표준화 변환\n$$Z = \\frac{X - \\mu}{\\sigma}$$\n\n**Step 1. 모수 확인**\n$X \\sim N(50, 4^2)$이므로: $\\mu = 50$, $\\sigma = 4$\n\n**Step 2. 표준화 계산**\n$$Z = \\frac{58 - 50}{4} = \\frac{8}{4} = 2$$\n\n**Step 3. 의미 해석**\n$Z = 2$는 $X = 58$이 평균에서 표준편차의 2배만큼 오른쪽에 있다는 뜻입니다.\n\n**Step 4. 검증**\n$\\mu + 2\\sigma = 50 + 2 \\times 4 = 58$ ✓\n\n**∴ 답: ③ 2**\n\n② 1.5는 $\\sigma = \\frac{16}{3}$으로 잘못 사용한 경우이며, ① 1은 $X = 54$에 해당하는 표준화 값입니다.\n\n**💡 포인트:** $N(\\mu, \\sigma^2)$에서 분산 $\\sigma^2$이 주어지므로, 표준편차 $\\sigma$를 정확히 구해야 합니다. $N(50, 16)$이면 $\\sigma = 4$이고, $N(50, 4)$이면 $\\sigma = 2$입니다.\n\n**보충:** 정규분포에서 $N(\\mu, \\sigma^2)$의 표기법에 주의하세요. 두 번째 인수가 분산($\\sigma^2$)인 경우가 대부분이며, 표준편차가 직접 주어지는 경우는 문맥에서 명시합니다.",
