    "explanation": "**[풀이]**\n\n**핵심 개념:** 정규분포의 대칭성 — 정규분포 $N(\\mu, \\sigma^2)$는 $X = \\mu$에 대해 좌우 대칭입니다.\n$$P(X \\leq \\mu) = P(X \\geq \\mu) = 0.5$$\n\n**Step 1. 조건 확인**\n$X \\sim N(70, 5^2)$이므로 $\\mu = 70$\n\n**Step 2. 대칭성 적용**\n$$P(X \\leq 70) = P(X \\leq \\mu) = 0.5$$\n\n**Step 3. 표준화로 확인**\n$$P(X \\leq 70) = P\\left(Z \\leq \\frac{70-70}{5}\\right) = P(Z \\leq 0) = 0.5 \\checkmark$$\n\n표준정규분포의 평균이 0이므로 $P(Z \\leq 0) = 0.5$입니다.\n\n**∴ 답: ③ 0.5**\n\n② 0.3413은 $P(0 \\leq Z \\leq 1)$의 값이며, ④ 0.6827은 $P(|Z| \\leq 1)$의 값으로, 모두 다른 구간의 확률입니다.\n\n**💡 포인트:** 정규분포에서 평균 이하(또는 이상)의 확률은 항상 $0.5$입니다. 이는 정규분포의 대칭성에서 비롯되며, 가장 기본적인 성질입니다.\n\n**보충:** 정규분포의 핵심 확률값: $P(\\mu - \\sigma \\leq X \\leq \\mu + \\sigma) \\approx 0.6827$, $P(\\mu - 2\\sigma \\leq X \\leq \\mu + 2\\sigma) \\approx 0.9545$, $P(\\mu - 3\\sigma \\leq X \\leq \\mu + 3\\sigma) \\approx 0.9973$. 이를 68-95-99.7 법칙이라 합니다.",
