    "explanation": "**[풀이]**\n\n**핵심 개념:** 표준화 후 대칭 구간의 확률 계산\n\n**Step 1. 표준화**\n$\\mu = 60$, $\\sigma = 4$\n$X = 52$: $Z = \\frac{52-60}{4} = -2$\n$X = 68$: $Z = \\frac{68-60}{4} = 2$\n\n**Step 2. 확률 계산**\n$$P(52 \\leq X \\leq 68) = P(-2 \\leq Z \\leq 2)$$\n$$= 2 \\times P(0 \\leq Z \\leq 2) = 2 \\times 0.4772 = 0.9544$$\n\n**Step 3. 검증**\n$\\mu \\pm 2\\sigma = 60 \\pm 8 = (52, 68)$ ✓\n68-95-99.7 법칙에서 $\\pm 2\\sigma$ 구간은 약 95.44%입니다. ✓\n\n**∴ 답: ③ 0.9544**\n\n② 0.6827은 $P(-1 \\leq Z \\leq 1)$이며 $\\pm 1\\sigma$ 구간의 확률입니다.\n\n**💡 포인트:** $P(-z \\leq Z \\leq z) = 2P(0 \\leq Z \\leq z)$는 대칭 구간의 확률을 구하는 기본 공식입니다.\n\n**보충:** 주요 대칭 구간 확률: $P(|Z| \\leq 1) = 0.6827$, $P(|Z| \\leq 2) = 0.9545$, $P(|Z| \\leq 3) = 0.9974$. 이 값들을 외워두면 빠르게 답할 수 있습니다.",
