    "answer": 1,
    "explanation": "**[풀이]**\n\n**핵심 개념:** $P(X \\leq a) = P(Z \\leq z_a)$에서 $a < \\mu$인 경우\n\n**Step 1. 표준화**\n$\\mu = 70$, $\\sigma = 10$\n$$Z = \\frac{50 - 70}{10} = -2$$\n\n**Step 2. 확률 계산**\n$$P(X \\leq 50) = P(Z \\leq -2)$$\n\n대칭성을 활용합니다:\n$$P(Z \\leq -2) = P(Z \\geq 2) = 0.5 - P(0 \\leq Z \\leq 2) = 0.5 - 0.4772 = 0.0228$$\n\n**Step 3. 검증**\n$50 = 70 - 2 \\times 10 = \\mu - 2\\sigma$이므로, 평균에서 2 표준편차 아래입니다. $P(Z \\leq -2) \\approx 2.28\\%$는 잘 알려진 값입니다. ✓\n\n**∴ 답: ② 0.0228**\n\n③ 0.1587은 $P(Z \\leq -1)$이며, ① 0.0013은 $P(Z \\leq -3)$입니다.\n\n**💡 포인트:** $P(Z \\leq -a) = P(Z \\geq a) = 0.5 - P(0 \\leq Z \\leq a)$. 음의 $z$값에 대한 확률은 대칭성을 이용하여 양의 $z$값으로 변환합니다.\n\n**보충:** 왼쪽 꼬리 확률: $P(Z \\leq -1) \\approx 0.1587$, $P(Z \\leq -2) \\approx 0.0228$, $P(Z \\leq -3) \\approx 0.0013$. 이들은 각각 '하위 약 16%, 2.3%, 0.1%'에 해당합니다.",
