    "problem": "확률변수 $X$가 정규분포 $N(200, 20^2)$을 따를 때, $P(180 \\leq X \\leq 240)$의 값을 소수 넷째 자리까지 구하시오. (답에 10000을 곱하여 정수로 답하시오.)\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$, $P(0 \\leq Z \\leq 2) = 0.4772$]",
