    "problem": "확률변수 $X$가 정규분포 $N(50, 10^2)$을 따르는 모집단에서 $X$의 값이 70 이상인 비율은 전체의 약 몇 %인가? (정수로 답하시오.)\n\n[표준정규분포표: $P(0 \\leq Z \\leq 2) = 0.4772$]",
