    "explanation": "**[풀이]**\n\n**핵심 개념:** 정규분포에서 특정 값 이상의 비율 구하기\n\n**Step 1. 표준화**\n$\\mu = 50$, $\\sigma = 10$\n$$Z = \\frac{70-50}{10} = 2$$\n\n**Step 2. 확률 계산**\n$$P(X \\geq 70) = P(Z \\geq 2) = 0.5 - P(0 \\leq Z \\leq 2) = 0.5 - 0.4772 = 0.0228$$\n\n**Step 3. 백분율 변환**\n$$0.0228 \\times 100 = 2.28\\%$$\n\n반올림하면 약 $2\\%$\n\n**Step 4. 검증**\n$70 = 50 + 2 \\times 10 = \\mu + 2\\sigma$이므로, 상위 약 2.3%에 해당합니다. 이는 잘 알려진 68-95-99.7 법칙에서 상위 $\\frac{100-95.44}{2} \\approx 2.28\\%$와 일치합니다. ✓\n\n**∴ 답: 2**\n\n**💡 포인트:** $\\mu + 2\\sigma$ 이상인 비율은 약 2.28%, $\\mu + 3\\sigma$ 이상은 약 0.13%입니다. 이 값들은 자주 사용되므로 암기하는 것이 좋습니다.\n\n**보충:** 실생활 응용: 시험 평균 50, 표준편차 10인 정규분포에서 70점 이상은 상위 약 2.3%입니다. 이는 대학 입학 등에서 '상위 2~3%'가 갖는 통계적 의미를 보여줍니다.",
