    "problem": "확률변수 $X$가 정규분포 $N(\\mu, \\sigma^2)$을 따르고, $P(X \\leq 65) = 0.8413$일 때, $\\mu = 50$이면 $\\sigma$의 값을 구하시오.\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$]",
    "answerType": "short",
