    "answer": 15,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 누적확률에서 $z$값을 역산하여 $\\sigma$를 구합니다.\n\n**Step 1. $P(X \\leq 65) = 0.8413$을 변환**\n$$P\\left(Z \\leq \\frac{65-50}{\\sigma}\\right) = 0.8413$$\n\n**Step 2. $z$값 결정**\n$P(Z \\leq z_0) = 0.8413$\n$P(Z \\leq z_0) = 0.5 + P(0 \\leq Z \\leq z_0) = 0.8413$\n$P(0 \\leq Z \\leq z_0) = 0.3413$\n\n표에서 $P(0 \\leq Z \\leq 1) = 0.3413$이므로 $z_0 = 1$\n\n**Step 3. $\\sigma$ 구하기**\n$$\\frac{65-50}{\\sigma} = 1 \\implies \\frac{15}{\\sigma} = 1 \\implies \\sigma = 15$$\n\n**Step 4. 검증**\n$X \\sim N(50, 15^2)$:\n$P(X \\leq 65) = P(Z \\leq 1) = 0.5 + 0.3413 = 0.8413$ ✓\n\n**∴ 답: 15**\n\n**💡 포인트:** $P(Z \\leq z_0) = 0.5 + P(0 \\leq Z \\leq z_0)$으로 변환하면 표의 값과 직접 비교할 수 있습니다. $P(Z \\leq z_0) > 0.5$이면 $z_0 > 0$입니다.\n\n**보충:** 누적확률 $P(Z \\leq z)$의 주요 값: $P(Z \\leq -2) = 0.0228$, $P(Z \\leq -1) = 0.1587$, $P(Z \\leq 0) = 0.5$, $P(Z \\leq 1) = 0.8413$, $P(Z \\leq 2) = 0.9772$.",
