    "problem": "확률변수 $X$가 이항분포 $B(100, 0.5)$를 따를 때, 정규근사를 이용하여 $P(40 \\leq X \\leq 60)$의 값은?\n\n[표준정규분포표: $P(0 \\leq Z \\leq z)$]\n| $z$ | $P(0 \\leq Z \\leq z)$ |\n|---|---|\n| 1.0 | 0.3413 |\n| 2.0 | 0.4772 |",
