    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 정규근사 — $n$이 충분히 크면:\n$$X \\sim B(n, p) \\approx N(np, np(1-p))$$\n\n**Step 1. 이항분포의 기댓값과 분산**\n$$E(X) = np = 100 \\times 0.5 = 50$$\n$$V(X) = np(1-p) = 100 \\times 0.5 \\times 0.5 = 25$$\n$$\\sigma(X) = \\sqrt{25} = 5$$\n\n$n = 100$으로 충분히 크고, $np = 50 \\geq 5$, $n(1-p) = 50 \\geq 5$이므로 정규근사가 적합합니다.\n\n**Step 2. 정규근사 적용**\n$$X \\approx N(50, 5^2)$$\n\n**Step 3. 표준화 및 확률 계산**\n$$P(40 \\leq X \\leq 60) = P\\left(\\frac{40-50}{5} \\leq Z \\leq \\frac{60-50}{5}\\right) = P(-2 \\leq Z \\leq 2)$$\n$$= 2 \\times P(0 \\leq Z \\leq 2) = 2 \\times 0.4772 = 0.9544$$\n\n**Step 4. 검증**\n$40 = 50 - 2 \\times 5 = \\mu - 2\\sigma$, $60 = 50 + 2 \\times 5 = \\mu + 2\\sigma$\n$P(\\mu - 2\\sigma \\leq X \\leq \\mu + 2\\sigma) \\approx 0.9544$는 68-95-99.7 법칙의 약 95%와 일치합니다. ✓\n\n**∴ 답: ③ 0.9544**\n\n① 0.6827은 $P(-1 \\leq Z \\leq 1)$이며 $\\pm 1\\sigma$ 구간의 확률이고, ⑤ 0.4772는 $P(0 \\leq Z \\leq 2)$만 계산한 것입니다.\n\n**💡 포인트:** 이항분포 → 정규근사의 조건: $np \\geq 5$이고 $n(1-p) \\geq 5$이면 근사가 좋습니다. $p = 0.5$일 때 $\\sigma = \\frac{\\sqrt{n}}{2}$이므로 계산이 간편합니다.\n\n**보충:** 동전 100번 던지기에서 앞면이 40~60번 나올 확률이 약 95.44%라는 것은, 대부분 평균(50번) 근처에 결과가 집중된다는 의미입니다. 이것이 큰 수의 법칙의 실제적 의미입니다.",
