    "problem": "확률변수 $X$가 이항분포 $B(450, \\frac{1}{3})$을 따를 때, 정규근사를 이용하여 $P(140 \\leq X \\leq 170)$의 값을 소수 넷째 자리까지 구하면? (답에 10000을 곱하여 정수로 답하시오.)\n\n[표준정규분포표: $P(0 \\leq Z \\leq z)$]\n| $z$ | $P(0 \\leq Z \\leq z)$ |\n|---|---|\n| 1.0 | 0.3413 |\n| 2.0 | 0.4772 |",
    "answerType": "short",
    "choices": null,
    "answer": 8185,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 정규근사\n$$B(n, p) \\approx N(np, np(1-p)) \\quad (n\\text{이 충분히 클 때})$$\n\n**Step 1. 기댓값과 표준편차**\n$$E(X) = 450 \\times \\frac{1}{3} = 150$$\n$$V(X) = 450 \\times \\frac{1}{3} \\times \\frac{2}{3} = 100$$\n$$\\sigma(X) = 10$$\n\n근사 조건: $np = 150 \\geq 5$ ✓, $n(1-p) = 300 \\geq 5$ ✓\n\n**Step 2. 정규근사 적용**\n$$X \\approx N(150, 10^2)$$\n\n**Step 3. 확률 계산**\n$$P(140 \\leq X \\leq 170) = P\\left(\\frac{140-150}{10} \\leq Z \\leq \\frac{170-150}{10}\\right) = P(-1 \\leq Z \\leq 2)$$\n$$= P(0 \\leq Z \\leq 1) + P(0 \\leq Z \\leq 2) = 0.3413 + 0.4772 = 0.8185$$\n\n**Step 4. 답 변환**\n$$0.8185 \\times 10000 = 8185$$\n\n**Step 5. 검증**\n이 구간은 $\\mu - \\sigma$부터 $\\mu + 2\\sigma$까지이며, 전체의 약 81.85%가 포함됩니다. 이는 합리적입니다. ✓\n\n**∴ 답: 8185**\n\n**💡 포인트:** 이항분포를 정규근사할 때는 $E(X) = np$와 $\\sigma = \\sqrt{np(1-p)}$를 구한 후, $N(np, np(1-p))$로 근사합니다.\n\n**보충:** 정규근사의 정확도는 $n$이 클수록, $p$가 $\\frac{1}{2}$에 가까울수록 좋습니다. 일반적으로 $np \\geq 5$이고 $n(1-p) \\geq 5$이면 충분히 정확합니다.",
    "difficulty": "lv3",
