    "_type": "normal_dist",
    "type": "정규분포",
    "problem": "A 회사 직원의 월급은 $N(300, 50^2)$ (단위: 만원), B 회사 직원의 월급은 $N(400, 100^2)$ (단위: 만원)을 따른다. A 회사에서 월급 상위 $2.28\\%$에 해당하는 최소 금액과 B 회사에서 월급 상위 $2.28\\%$에 해당하는 최소 금액의 차이를 구하시오. (단위: 만원)\n\n[표준정규분포표: $P(0 \\leq Z \\leq 2) = 0.4772$]",
    "answerType": "short",
    "choices": null,
    "answer": 200,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 상위 $\\alpha\\%$에 해당하는 값 = $\\mu + z_\\alpha \\sigma$\n\n**Step 1. $z$값 결정**\n상위 $2.28\\% = 0.0228$\n$P(Z \\geq z_0) = 0.0228$\n$P(0 \\leq Z \\leq z_0) = 0.5 - 0.0228 = 0.4772$\n표에서 $z_0 = 2$\n\n**Step 2. A 회사의 상위 2.28% 최소 금액**\n$$k_A = \\mu_A + 2\\sigma_A = 300 + 2 \\times 50 = 400 \\text{ (만원)}$$\n\n**Step 3. B 회사의 상위 2.28% 최소 금액**\n$$k_B = \\mu_B + 2\\sigma_B = 400 + 2 \\times 100 = 600 \\text{ (만원)}$$\n\n**Step 4. 차이 계산**\n$$k_B - k_A = 600 - 400 = 200 \\text{ (만원)}$$\n\n**Step 5. 검증**\nA: $P(X \\geq 400) = P(Z \\geq 2) = 0.0228$ ✓\nB: $P(X \\geq 600) = P(Z \\geq 2) = 0.0228$ ✓\n\n**∴ 답: 200**\n\n**💡 포인트:** 상위 $\\alpha\\%$의 최소 금액은 $\\mu + z_\\alpha \\sigma$이며, 분포에 따라 크게 달라집니다. 평균이 같더라도 표준편차가 다르면 상위 금액의 차이가 커집니다.\n\n**보충:** 분산(표준편차)이 클수록 상위 또는 하위 극단값이 평균에서 더 멀리 떨어집니다. B 회사는 표준편차가 A의 2배이므로, 상위 2.28% 기준이 평균에서 200만원(= $2 \\times 100$) 떨어져 있고, A는 100만원(= $2 \\times 50$) 떨어져 있습니다.",
