    "problem": "확률변수 $X$가 이항분포 $B(1200, \\frac{1}{4})$를 따를 때, 정규근사를 이용하여 $P(X \\leq 285)$의 값을 소수 넷째 자리까지 구하면? (답에 10000을 곱하여 정수로 답하시오.)\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$, $P(0 \\leq Z \\leq 2) = 0.4772$]",
    "answerType": "short",
    "choices": null,
    "answer": 1587,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 정규근사\n\n**Step 1. 기댓값과 표준편차**\n$$E(X) = 1200 \\times \\frac{1}{4} = 300$$\n$$V(X) = 1200 \\times \\frac{1}{4} \\times \\frac{3}{4} = 225$$\n$$\\sigma(X) = \\sqrt{225} = 15$$\n\n근사 조건: $np = 300 \\geq 5$ ✓, $n(1-p) = 900 \\geq 5$ ✓\n\n**Step 2. 정규근사 적용**\n$$X \\approx N(300, 15^2)$$\n\n**Step 3. 확률 계산**\n$$P(X \\leq 285) = P\\left(Z \\leq \\frac{285-300}{15}\\right) = P(Z \\leq -1)$$\n$$= 0.5 - P(0 \\leq Z \\leq 1) = 0.5 - 0.3413 = 0.1587$$\n\n**Step 4. 답 변환**\n$$0.1587 \\times 10000 = 1587$$\n\n**Step 5. 검증**\n$285 = 300 - 15 = \\mu - \\sigma$이므로, 하위 약 15.87%에 해당합니다. ✓\n\n**∴ 답: 1587**\n\n**💡 포인트:** $P(Z \\leq -a) = 0.5 - P(0 \\leq Z \\leq a)$. 음의 $z$값에 대한 누적확률은 대칭성으로 변환합니다.\n\n**보충:** $np = 300 \\gg 5$이고 $n(1-p) = 900 \\gg 5$이므로 정규근사의 정확도가 매우 높습니다. 이항분포에서 $n$이 수백 이상이면 정규근사와 실제값의 차이는 무시할 수 있을 정도로 작습니다.",
