    "type": "정규분포",
    "problem": "독립인 확률변수 $X \\sim N(30, 4^2)$, $Y \\sim N(20, 3^2)$에 대해, $W = X + Y$의 분포와 $P(W \\leq 55)$의 값은?\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$]",
    "answerType": "choice",
