    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립인 정규분포의 합\n$$X \\sim N(\\mu_1, \\sigma_1^2), \\quad Y \\sim N(\\mu_2, \\sigma_2^2) \\implies X + Y \\sim N(\\mu_1 + \\mu_2, \\sigma_1^2 + \\sigma_2^2)$$\n\n**Step 1. $W = X + Y$의 분포**\n$$E(W) = 30 + 20 = 50$$\n$$V(W) = 4^2 + 3^2 = 16 + 9 = 25$$\n$$W \\sim N(50, 25)$$\n즉, $\\sigma(W) = 5$\n\n**Step 2. $P(W \\leq 55)$ 계산**\n$$P(W \\leq 55) = P\\left(Z \\leq \\frac{55-50}{5}\\right) = P(Z \\leq 1)$$\n$$= 0.5 + P(0 \\leq Z \\leq 1) = 0.5 + 0.3413 = 0.8413$$\n\n**Step 3. 검증**\n$W \\sim N(50, 25)$이고 $55 = 50 + 5 = \\mu + \\sigma$이므로, $P(Z \\leq 1) = 0.8413$은 정확합니다. ✓\n\n**∴ 답: ③ $N(50, 25)$, $0.8413$**\n\n① $N(50, 7)$은 분산을 $\\sigma_1 + \\sigma_2 = 7$로 잘못 계산한 것이며, ⑤ $N(50, 49)$는 $\\sigma^2 = 7^2$로 표준편차를 더한 후 제곱한 오답입니다.\n\n**💡 포인트:** 독립인 정규분포의 합에서 **분산이 더해집니다** (표준편차가 아닙니다!). $V(X+Y) = V(X) + V(Y)$이며, $\\sigma(X+Y) \\neq \\sigma(X) + \\sigma(Y)$입니다.\n\n**보충:** 정규분포는 합에 대해 닫혀 있습니다(재생성). 독립인 정규분포의 합은 다시 정규분포가 됩니다. 이 성질은 다른 분포에서는 일반적으로 성립하지 않습니다.",
