    "answer": 1,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립인 정규분포의 차\n$$W = X - Y \\sim N(\\mu_X - \\mu_Y, \\sigma_X^2 + \\sigma_Y^2)$$\n분산은 뺄 때도 **더합니다**!\n\n**Step 1. $W$의 분포**\n$$E(W) = 100 - 80 = 20$$\n$$V(W) = 6^2 + 8^2 = 36 + 64 = 100$$\n$$W \\sim N(20, 100), \\quad \\sigma(W) = 10$$\n\n**Step 2. 확률 계산**\n$$P(W \\geq 30) = P\\left(Z \\geq \\frac{30-20}{10}\\right) = P(Z \\geq 1)$$\n$$= 0.5 - P(0 \\leq Z \\leq 1) = 0.5 - 0.3413 = 0.1587$$\n\n**Step 3. 검증**\n$30 = 20 + 10 = \\mu_W + \\sigma_W$이므로, $P(Z \\geq 1) = 0.1587$은 정확합니다. ✓\n\n**∴ 답: ② 0.1587**\n\n④ 0.5는 $P(W \\geq 20) = P(Z \\geq 0)$이며, ① 0.0228은 $P(Z \\geq 2)$입니다.\n\n**💡 포인트:** $V(X - Y) = V(X) + V(Y)$ (독립일 때)입니다. 차의 분산에서 분산은 항상 **더해집니다**. 이는 $(-1)^2 = 1$이므로 $V(-Y) = V(Y)$이기 때문입니다.\n\n**보충:** 실생활 예: 두 제품의 무게 차이가 정규분포를 따르면, 그 분산은 각 제품 분산의 합입니다. 분산이 더해지므로 차이의 변동은 개별 변동보다 커집니다.",
