    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 정규분포에서 백분위수를 구합니다.\n\n**Step 1. A등급 최저 점수**\n상위 15.87%: $P(Z \\geq z_A) = 0.1587$\n$P(0 \\leq Z \\leq z_A) = 0.5 - 0.1587 = 0.3413$\n표에서 $z_A = 1$\n$$X_A = \\mu + z_A \\sigma = 60 + 1 \\times 10 = 70$$\n\n**Step 2. F등급 최고 점수**\n하위 2.28%: $P(Z \\leq z_F) = 0.0228$\n$P(z_F \\leq Z \\leq 0) = 0.5 - 0.0228 = 0.4772$\n$P(0 \\leq Z \\leq |z_F|) = 0.4772$\n표에서 $|z_F| = 2$, 즉 $z_F = -2$\n$$X_F = \\mu + z_F \\sigma = 60 + (-2) \\times 10 = 40$$\n\n**Step 3. 차이 계산**\n$$X_A - X_F = 70 - 40 = 30$$\n\n**Step 4. 검증**\n$P(X \\geq 70) = P(Z \\geq 1) = 0.1587$ ✓ (상위 15.87%)\n$P(X \\leq 40) = P(Z \\leq -2) = 0.0228$ ✓ (하위 2.28%)\n\n**∴ 답: ③ 30**\n\n② 25는 $z$값을 1과 1.5로 잘못 사용한 경우이며, ④ 35는 $z = 1.5$와 $z = -2$를 사용한 오답입니다.\n\n**💡 포인트:** 등급 기준 문제에서는 (1) 비율 → $z$값 결정, (2) $z$값 → $X$값 역변환의 두 단계로 풀이합니다.\n\n**보충:** 수능 등급제에서는 상위 4%까지 1등급, 상위 11%까지 2등급 등으로 구분합니다. $z$값으로는 $z \\approx 1.75$ (상위 4%), $z \\approx 1.23$ (상위 11%)에 해당합니다.",
