    "problem": "확률변수 $X \\sim N(\\mu, \\sigma^2)$에 대해 $P(X \\leq 20) = 0.1587$이고 $P(X \\leq 40) = 0.8413$일 때, $\\mu$와 $\\sigma$의 값은?\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$, $P(0 \\leq Z \\leq 2) = 0.4772$]",
