    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 두 개의 누적확률 조건으로 연립방정식을 세워 $\\mu$와 $\\sigma$를 구합니다.\n\n**Step 1. $z$값 결정**\n조건 1: $P(X \\leq 20) = 0.1587$\n$P(Z \\leq z_1) = 0.1587 \\implies z_1 = -1$ ($P(Z \\leq -1) = 0.5 - 0.3413 = 0.1587$)\n\n조건 2: $P(X \\leq 40) = 0.8413$\n$P(Z \\leq z_2) = 0.8413 \\implies z_2 = 1$ ($P(Z \\leq 1) = 0.5 + 0.3413 = 0.8413$)\n\n**Step 2. 연립방정식**\n$$\\frac{20 - \\mu}{\\sigma} = -1 \\implies 20 = \\mu - \\sigma \\quad \\cdots ①$$\n$$\\frac{40 - \\mu}{\\sigma} = 1 \\implies 40 = \\mu + \\sigma \\quad \\cdots ②$$\n\n**Step 3. 풀이**\n① + ②: $2\\mu = 60 \\implies \\mu = 30$\n② - ①: $2\\sigma = 20 \\implies \\sigma = 10$\n\n**Step 4. 검증**\n$P(X \\leq 20) = P\\left(Z \\leq \\frac{20-30}{10}\\right) = P(Z \\leq -1) = 0.1587$ ✓\n$P(X \\leq 40) = P\\left(Z \\leq \\frac{40-30}{10}\\right) = P(Z \\leq 1) = 0.8413$ ✓\n\n20과 40은 $\\mu = 30$에 대해 대칭이며, 이는 두 조건의 확률이 합하여 1인 것($0.1587 + 0.8413 = 1$)과도 일치합니다.\n\n**∴ 답: ③ $\\mu = 30, \\sigma = 10$**\n\n② $\\mu = 30, \\sigma = 5$이면 $P(X \\leq 20) = P(Z \\leq -2) = 0.0228 \\neq 0.1587$이므로 오답입니다.\n\n**💡 포인트:** 두 개의 누적확률 조건이 주어지면, 각각을 $z$값으로 변환하여 $\\mu$와 $\\sigma$에 대한 연립방정식을 세웁니다.\n\n**보충:** $P(X \\leq a) = P(Z \\leq z_a)$에서 $a = \\mu + z_a \\sigma$이므로, 두 조건이 있으면 미지수 2개의 연립방정식이 됩니다. 이 유형은 수능에서 자주 출제됩니다. 특히 $P(X \\leq a) + P(X \\leq b) = 1$이면 $a$와 $b$는 $\\mu$에 대해 대칭입니다.",
