    "_type": "normal_dist",
    "type": "정규분포",
    "problem": "독립인 확률변수 $X_1, X_2, X_3, X_4$가 모두 $N(10, 2^2)$을 따를 때, $\\bar{X} = \\frac{X_1+X_2+X_3+X_4}{4}$의 분포는 $N(a, b)$이다. $a + b$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 11,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립인 정규분포의 합과 표본평균의 분포\n$$\\bar{X} = \\frac{1}{n}\\sum X_i \\sim N\\left(\\mu, \\frac{\\sigma^2}{n}\\right)$$\n\n**Step 1. 합의 분포**\n$S = X_1 + X_2 + X_3 + X_4 \\sim N(4 \\times 10, 4 \\times 2^2) = N(40, 16)$\n\n**Step 2. 평균의 분포**\n$$\\bar{X} = \\frac{S}{4} \\sim N\\left(\\frac{40}{4}, \\frac{16}{4^2} \\cdot 4^2\\right)$$\n\n아니요, 직접 공식을 사용합시다:\n$$E(\\bar{X}) = \\mu = 10$$\n$$V(\\bar{X}) = \\frac{\\sigma^2}{n} = \\frac{4}{4} = 1$$\n\n따라서 $\\bar{X} \\sim N(10, 1)$\n\n**Step 3. 답 계산**\n$a = 10$, $b = 1$\n$$a + b = 10 + 1 = 11$$\n\n**Step 4. 검증**\n$E(\\bar{X}) = E\\left(\\frac{X_1+\\cdots+X_4}{4}\\right) = \\frac{4 \\times 10}{4} = 10$ ✓\n$V(\\bar{X}) = V\\left(\\frac{X_1+\\cdots+X_4}{4}\\right) = \\frac{1}{16} \\times V(X_1+\\cdots+X_4) = \\frac{1}{16} \\times 16 = 1$ ✓\n\n**∴ 답: 11**\n\n**💡 포인트:** 표본평균 $\\bar{X}$의 분산은 원래 분산을 표본 크기 $n$으로 나눈 $\\frac{\\sigma^2}{n}$입니다. 표본이 클수록 평균의 변동이 줄어듭니다.\n\n**보충:** 이 결과는 중심극한정리(CLT)의 특수한 경우입니다. 정규분포에서는 $n$의 크기에 관계없이 표본평균이 정확히 정규분포를 따르며, 비정규분포에서는 $n$이 충분히 클 때 근사적으로 정규분포를 따릅니다.",
