    "type": "정규분포",
    "problem": "확률변수 $X \\sim N(\\mu, \\sigma^2)$에 대해 $P(\\mu - 2\\sigma \\leq X \\leq \\mu + \\sigma) = a$이다. $a$의 값을 소수 넷째 자리까지 구하면? (답에 10000을 곱하여 정수로 답하시오.)\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$, $P(0 \\leq Z \\leq 2) = 0.4772$]",
    "answerType": "short",
    "choices": null,
    "answer": 8185,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 표준화를 적용하여 비대칭 구간의 확률을 구합니다.\n\n**Step 1. 표준화**\n$X = \\mu - 2\\sigma$일 때: $Z = \\frac{(\\mu-2\\sigma)-\\mu}{\\sigma} = -2$\n$X = \\mu + \\sigma$일 때: $Z = \\frac{(\\mu+\\sigma)-\\mu}{\\sigma} = 1$\n\n**Step 2. 확률 계산**\n$$P(\\mu - 2\\sigma \\leq X \\leq \\mu + \\sigma) = P(-2 \\leq Z \\leq 1)$$\n$$= P(-2 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 1)$$\n$$= P(0 \\leq Z \\leq 2) + P(0 \\leq Z \\leq 1)$$\n$$= 0.4772 + 0.3413 = 0.8185$$\n\n**Step 3. 답 변환**\n$$0.8185 \\times 10000 = 8185$$\n\n**Step 4. 검증**\n$P(-2 \\leq Z \\leq 1) = P(Z \\leq 1) - P(Z \\leq -2) = 0.8413 - 0.0228 = 0.8185$ ✓\n\n**∴ 답: 8185**\n\n**💡 포인트:** $P(-a \\leq Z \\leq b) = P(0 \\leq Z \\leq a) + P(0 \\leq Z \\leq b)$ ($a, b > 0$). 이 공식은 비대칭 구간의 확률을 구하는 핵심입니다.\n\n**보충:** 이 문제는 $\\mu$와 $\\sigma$의 구체적인 값 없이도 답을 구할 수 있습니다. 이는 정규분포의 확률이 $\\mu$와 $\\sigma$에 대한 상대적 위치(즉, $z$값)에만 의존하기 때문입니다.",
