    "problem": "확률변수 $X \\sim N(50, 10^2)$이고, $Y = 2X + 10$이다. $P(Y \\leq 130)$의 값을 소수 넷째 자리까지 구하면? (답에 10000을 곱하여 정수로 답하시오.)\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$]",
    "answerType": "short",
    "choices": null,
    "answer": 8413,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 정규분포의 선형변환\n$$X \\sim N(\\mu, \\sigma^2) \\implies aX + b \\sim N(a\\mu + b, a^2\\sigma^2)$$\n\n**Step 1. $Y$의 분포 결정**\n$Y = 2X + 10$이고 $X \\sim N(50, 100)$이므로:\n$$E(Y) = 2 \\times 50 + 10 = 110$$\n$$V(Y) = 2^2 \\times 100 = 400$$\n$$Y \\sim N(110, 20^2)$$\n\n**Step 2. 확률 계산**\n$$P(Y \\leq 130) = P\\left(Z \\leq \\frac{130-110}{20}\\right) = P(Z \\leq 1)$$\n$$= 0.5 + P(0 \\leq Z \\leq 1) = 0.5 + 0.3413 = 0.8413$$\n\n**Step 3. 답 변환**\n$$0.8413 \\times 10000 = 8413$$\n\n**Step 4. 검증 — 직접 변환**\n$Y \\leq 130 \\iff 2X + 10 \\leq 130 \\iff X \\leq 60$\n$P(X \\leq 60) = P\\left(Z \\leq \\frac{60-50}{10}\\right) = P(Z \\leq 1) = 0.8413$ ✓\n\n**∴ 답: 8413**\n\n**💡 포인트:** $P(Y \\leq a)$를 구할 때 두 가지 방법이 있습니다: (1) $Y$의 분포를 구한 후 표준화, (2) 부등식을 $X$로 변환하여 직접 계산. 두 방법 모두 같은 결과를 줍니다.\n\n**보충:** 정규분포의 선형변환 성질: $X \\sim N(\\mu, \\sigma^2)$이면 $aX + b \\sim N(a\\mu + b, a^2\\sigma^2)$. 이는 정규분포가 선형변환에 대해 닫혀 있음을 의미합니다. 이 성질은 다른 대부분의 분포에서는 성립하지 않습니다.",
