    "problem": "어느 공장에서 생산되는 제품의 무게는 정규분포 $N(m, 4^2)$을 따른다고 한다. 이 공장에서 생산된 제품 중 64개를 임의추출하여 표본평균을 구했더니 $\\bar{X} = 50$이었다. 모평균 $m$에 대한 신뢰도 95%의 신뢰구간을 구하면? (단, $z_{0.025} = 1.96$)",
