    "explanation": "**[풀이]**\n\n**핵심 개념:** 모표준편차 $\\sigma$가 알려진 정규분포에서 모평균 $m$에 대한 신뢰도 $95\\%$의 신뢰구간은 다음과 같습니다.\n$$\\bar{X} - z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq m \\leq \\bar{X} + z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n**Step 1. 주어진 값 정리**\n- 모표준편차: $\\sigma = 4$\n- 표본 크기: $n = 64$\n- 표본평균: $\\bar{X} = 50$\n- $z_{0.025} = 1.96$\n\n**Step 2. 표준오차 계산**\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{4}{\\sqrt{64}} = \\frac{4}{8} = 0.5$$\n\n**Step 3. 오차한계 계산**\n$$E = z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 1.96 \\times 0.5 = 0.98$$\n\n**Step 4. 신뢰구간 구하기**\n$$50 - 0.98 \\leq m \\leq 50 + 0.98$$\n$$49.02 \\leq m \\leq 50.98$$\n\n**∴ 답: ① 49.02 ≤ m ≤ 50.98**\n\n② 49.51 ≤ m ≤ 50.49는 $\\frac{\\sigma}{\\sqrt{n}} = \\frac{4}{\\sqrt{64}}$를 $\\frac{4}{64} = 0.0625$로 잘못 계산한 후 $1.96 \\times 0.0625 \\approx 0.49$를 구한 오답입니다.\n\n**💡 포인트:** 표준오차는 $\\frac{\\sigma}{\\sqrt{n}}$이며, $\\frac{\\sigma}{n}$이 아닙니다. $\\sqrt{n}$으로 나누는 것을 반드시 기억하세요.\n\n**보충:** 신뢰구간의 폭은 $2E = 2 \\times 0.98 = 1.96$입니다. 표본 크기가 클수록, 모표준편차가 작을수록 신뢰구간이 좁아져 추정의 정밀도가 높아집니다.",
