    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 오차한계(Margin of Error)는 신뢰구간에서 표본평균으로부터의 최대 오차입니다.\n$$E = z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n**Step 1. 주어진 값 정리**\n- 모표준편차: $\\sigma = 12$\n- 표본 크기: $n = 144$\n- $z_{0.025} = 1.96$\n\n**Step 2. 표준오차 계산**\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{12}{\\sqrt{144}} = \\frac{12}{12} = 1$$\n\n**Step 3. 오차한계 계산**\n$$E = 1.96 \\times 1 = 1.96$$\n\n**∴ 답: ③ 1.96**\n\n**💡 포인트:** 표준오차가 1이면 오차한계는 $z$ 값 자체가 됩니다. $\\frac{\\sigma}{\\sqrt{n}} = 1$이 되도록 $\\sigma = \\sqrt{n}$일 때 이런 상황이 발생합니다.\n\n**보충:** 이 문제에서 $\\sigma = 12$이고 $\\sqrt{n} = \\sqrt{144} = 12$이므로 표준오차가 정확히 1이 됩니다. 신뢰구간은 $100 - 1.96 \\leq m \\leq 100 + 1.96$, 즉 $98.04 \\leq m \\leq 101.96$이 됩니다. 오차한계는 신뢰구간 길이의 절반이므로 $\\frac{101.96 - 98.04}{2} = 1.96$으로 검증됩니다.",
