    "explanation": "**[풀이]**\n\n**핵심 개념:** 신뢰구간의 길이가 주어진 값 이하가 되려면 필요한 최소 표본 크기를 구합니다.\n$$L = 2 \\cdot z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq d$$\n\n**Step 1. 주어진 값 정리**\n- 모표준편차: $\\sigma = 8$\n- 신뢰구간 길이 조건: $L \\leq 4$\n- $z_{0.005} = 2.58$ (신뢰도 99%)\n\n**Step 2. 부등식 세우기**\n$$2 \\times 2.58 \\times \\frac{8}{\\sqrt{n}} \\leq 4$$\n$$\\frac{41.28}{\\sqrt{n}} \\leq 4$$\n$$\\sqrt{n} \\geq \\frac{41.28}{4} = 10.32$$\n$$n \\geq (10.32)^2 = 106.5024$$\n\n**Step 3. 올림 적용**\n$n$은 자연수이므로 $n \\geq 107$\n\n**Step 4. 검증**\n$n = 107$일 때: $L = 2 \\times 2.58 \\times \\frac{8}{\\sqrt{107}} = 5.16 \\times 0.7737 = 3.992 \\leq 4$ ✓\n$n = 106$일 때: $L = 5.16 \\times \\frac{8}{\\sqrt{106}} = 5.16 \\times 0.7771 = 4.010 > 4$ ✗\n\n**∴ 답: ② 107**\n\n③ 144는 $\\sqrt{n} = 12$로 깔끔한 값이지만, 필요 이상으로 큰 표본입니다.\n\n**💡 포인트:** '오차한계' 조건과 '신뢰구간 길이' 조건을 구별하세요. 길이 = 2 × 오차한계입니다.\n\n**보충:** 신뢰구간의 길이 조건 문제에서는 먼저 길이와 오차한계의 관계를 명확히 하고, 부등식을 세워 $n$에 대해 풀어야 합니다. 마지막에 올림을 적용하는 것을 잊지 마세요.",
