    "explanation": "**[풀이]**\n\n**핵심 개념:** 동일한 표본 크기에서 신뢰도에 따른 오차한계의 차이를 구합니다.\n$$E = z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n**Step 1. 공통 표준오차 계산**\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{6}{\\sqrt{36}} = \\frac{6}{6} = 1$$\n\n**Step 2. 각 오차한계 계산**\n$$E_1 = z_{0.005} \\times 1 = 2.58 \\times 1 = 2.58$$\n$$E_2 = z_{0.025} \\times 1 = 1.96 \\times 1 = 1.96$$\n\n**Step 3. 차이 계산**\n$$E_1 - E_2 = 2.58 - 1.96 = 0.62$$\n\n**∴ 답: ② 0.62**\n\n**💡 포인트:** 표준오차가 1이 되면 오차한계가 $z$ 값 자체가 됩니다. 이 경우 오차한계의 차이는 두 $z$ 값의 차이와 같습니다.\n\n**보충:** 신뢰도를 99%에서 95%로 낮추면 오차한계가 $0.62$만큼 줄어듭니다. 이는 신뢰도와 정밀도(오차한계) 사이의 트레이드오프를 보여줍니다. 신뢰도를 높이면 모평균을 포함할 확률은 증가하지만, 그만큼 구간이 넓어져 추정의 정밀도는 떨어집니다. 실제 조사에서는 이 두 가지를 적절히 균형 잡아야 합니다.",
