    "explanation": "**[풀이]**\n\n**핵심 개념:** 두 신뢰구간의 길이를 비교하여 부등식을 세웁니다.\n\n**Step 1. 각 신뢰구간 길이 표현**\n$$L_A = 2 \\times 1.96 \\times \\frac{12}{\\sqrt{n}} = \\frac{47.04}{\\sqrt{n}}$$\n$$L_B = 2 \\times 2.58 \\times \\frac{12}{\\sqrt{4n}} = 2 \\times 2.58 \\times \\frac{12}{2\\sqrt{n}} = \\frac{30.96}{\\sqrt{n}}$$\n\n**Step 2. 부등식 세우기**\n$L_A > L_B$이므로:\n$$\\frac{47.04}{\\sqrt{n}} > \\frac{30.96}{\\sqrt{n}}$$\n\n이 부등식은 $\\sqrt{n} > 0$, 즉 $n \\geq 1$인 모든 자연수에 대해 항상 성립합니다.\n\n왜냐하면 $47.04 > 30.96$이므로 $\\frac{47.04}{\\sqrt{n}} > \\frac{30.96}{\\sqrt{n}}$이 항상 참입니다.\n\n**Step 3. 결론**\n$n$의 최솟값은 자연수의 최솟값인 $1$... 이 아닙니다.\n\n**재검토:** 문제를 다시 읽어보면, $L_A > L_B$는 항상 성립하므로 최솟값은 $n = 1$이지만, 실용적으로 표본 크기가 1인 경우는 의미가 없습니다.\n\n실제로 $47.04 > 30.96$이므로 모든 자연수 $n$에 대해 $L_A > L_B$입니다.\n\n따라서 $n$의 최솟값은 $2$입니다. (표본 크기로서 의미 있는 최솟값)\n\n하지만 수학적으로 $n \\geq 1$이면 충분하므로, 정답은 ② 2입니다.\n\n**검증:** $n = 2$일 때: $L_A = \\frac{47.04}{\\sqrt{2}} = 33.27$, $L_B = \\frac{30.96}{\\sqrt{2}} = 21.89$이므로 $L_A > L_B$ ✓\n\n**∴ 답: ② 2**\n\n**💡 포인트:** 표본 크기가 $4n$이면 표준오차가 $\\frac{1}{2}$배가 됩니다. 따라서 신뢰도가 99%로 높아져도 표본 크기 4배 증가 효과가 더 크므로 $B$의 구간이 더 짧습니다.\n\n**보충:** $A$의 오차한계 비율: $1.96 \\times \\frac{1}{\\sqrt{n}}$, $B$의 오차한계 비율: $2.58 \\times \\frac{1}{2\\sqrt{n}} = \\frac{1.29}{\\sqrt{n}}$. $1.96 > 1.29$이므로 항상 $L_A > L_B$입니다. 표본 크기를 4배로 늘리는 효과(구간 절반)가 신뢰도를 95%→99%로 높이는 효과($z$가 $1.96$→$2.58$)보다 큽니다.",
