    "explanation": "**[풀이]**\n\n**핵심 개념:** 같은 표본에서 신뢰도만 다른 두 신뢰구간의 길이 비를 구합니다.\n\n**Step 1. 각 신뢰구간 길이 표현**\n$$L_{95} = 2 \\times 1.96 \\times \\frac{\\sigma}{\\sqrt{n}} = 3.92 \\times \\frac{\\sigma}{\\sqrt{n}}$$\n$$L_{99} = 2 \\times 2.58 \\times \\frac{\\sigma}{\\sqrt{n}} = 5.16 \\times \\frac{\\sigma}{\\sqrt{n}}$$\n\n**Step 2. 비 계산**\n$L_{95} = k \\cdot L_{99}$에서:\n$$k = \\frac{L_{95}}{L_{99}} = \\frac{3.92}{5.16} = \\frac{392}{516} = \\frac{98}{129}$$\n\n약분: $392 = 4 \\times 98$, $516 = 4 \\times 129$이므로\n$$k = \\frac{98}{129}$$\n\n**Step 3. 검증**\n$\\frac{\\sigma}{\\sqrt{n}}$ 부분이 상쇄되므로, $k$는 $\\sigma$나 $n$과 무관합니다.\n$k = \\frac{98}{129} \\approx 0.760$이므로, 95% 신뢰구간이 99% 신뢰구간의 약 76%입니다. ✓\n\n**∴ 답: ② 98/129**\n\n④ 98/258은 $\\frac{1.96}{2.58}$로 $2$를 곱하지 않고 단순히 $z$ 값의 비를 구한 것인데, 실제로 $\\frac{1.96}{2.58} = \\frac{98}{129}$와 같습니다. 하지만 ④는 $\\frac{98}{258}$이므로 분모가 다릅니다.\n\n**💡 포인트:** $\\frac{\\sigma}{\\sqrt{n}}$은 공통 인수이므로 상쇄됩니다. 길이의 비는 $z$ 값의 비와 같습니다.\n\n**보충:** $k = \\frac{z_{0.025}}{z_{0.005}} = \\frac{1.96}{2.58} = \\frac{98}{129}$입니다. 이 비율은 모표준편차와 표본 크기에 무관하게 항상 동일합니다. 신뢰도 95%의 구간은 항상 99% 구간의 약 76%입니다.",
