    "explanation": "**[풀이]**\n\n**핵심 개념:** 두 신뢰구간의 길이가 같으면 $z$ 값과 $\\sqrt{n}$의 비를 통해 $\\frac{n_2}{n_1}$을 구합니다.\n\n**Step 1. 두 신뢰구간 길이가 같은 조건**\n$$L_1 = L_2$$\n$$2 \\times 1.96 \\times \\frac{\\sigma}{\\sqrt{n_1}} = 2 \\times 2.58 \\times \\frac{\\sigma}{\\sqrt{n_2}}$$\n\n**Step 2. 정리**\n$$\\frac{1.96}{\\sqrt{n_1}} = \\frac{2.58}{\\sqrt{n_2}}$$\n$$\\frac{\\sqrt{n_2}}{\\sqrt{n_1}} = \\frac{2.58}{1.96}$$\n$$\\sqrt{\\frac{n_2}{n_1}} = \\frac{2.58}{1.96} = \\frac{129}{98}$$\n\n**Step 3. 양변 제곱**\n$$\\frac{n_2}{n_1} = \\left(\\frac{129}{98}\\right)^2 = \\frac{16641}{9604} \\approx 1.7327$$\n\n소수점 셋째 자리에서 반올림: $\\frac{n_2}{n_1} \\approx 1.73$\n\n**∴ 답: ③ 1.73**\n\n② 1.56은 $\\frac{2.58}{1.96} \\approx 1.316$을 $1.316^2$으로 계산할 때의 중간 오류일 수 있습니다.\n\n**💡 포인트:** 신뢰구간의 길이를 같게 하려면, 신뢰도가 높은 쪽의 표본 크기가 더 커야 합니다. 필요한 배율은 $z$ 값 비의 제곱입니다.\n\n**보충:** $\\frac{n_2}{n_1} = \\left(\\frac{z_{0.005}}{z_{0.025}}\\right)^2 = \\left(\\frac{2.58}{1.96}\\right)^2 \\approx 1.73$입니다. 즉, 99% 신뢰구간의 길이를 95% 신뢰구간과 같게 만들려면 표본 크기를 약 1.73배로 늘려야 합니다. 이는 $\\sqrt{n}$에 반비례하는 성질 때문입니다.",
