    "explanation": "**[풀이]**\n\n**핵심 개념:** 신뢰구간의 길이는 $\\frac{1}{\\sqrt{n}}$에 비례합니다. 길이를 $\\frac{1}{k}$배로 줄이려면 표본 크기를 $k^2$배로 늘려야 합니다.\n\n**Step 1. 비례 관계 설정**\n$$L \\propto \\frac{1}{\\sqrt{n}}$$\n\n길이를 $\\frac{1}{3}$로 줄이려면:\n$$\\frac{L'}{L} = \\frac{1}{3} = \\frac{\\sqrt{n}}{\\sqrt{n'}} = \\sqrt{\\frac{n}{n'}}$$\n\n**Step 2. $n'$ 계산**\n$$\\frac{1}{3} = \\sqrt{\\frac{400}{n'}}$$\n$$\\frac{1}{9} = \\frac{400}{n'}$$\n$$n' = 400 \\times 9 = 3600$$\n\n**Step 3. 검증**\n- 원래: $L = 2 \\times 1.96 \\times \\frac{\\sigma}{\\sqrt{400}} = \\frac{3.92\\sigma}{20} = 0.196\\sigma$\n- 새로운: $L' = 2 \\times 1.96 \\times \\frac{\\sigma}{\\sqrt{3600}} = \\frac{3.92\\sigma}{60} = 0.06533\\sigma$\n- $\\frac{L'}{L} = \\frac{0.06533}{0.196} = \\frac{1}{3}$ ✓\n\n**∴ 답: ④ 3600**\n\n① 1200은 $400 \\times 3$으로 단순히 3배를 한 오답입니다. 길이를 $\\frac{1}{3}$로 줄이려면 $n$을 $3$배가 아니라 $3^2 = 9$배로 늘려야 합니다.\n\n**💡 포인트:** 신뢰구간의 길이를 $\\frac{1}{k}$배로 줄이려면 $n$을 $k^2$배로 늘려야 합니다. $L \\propto \\frac{1}{\\sqrt{n}}$이기 때문입니다.\n\n**보충:** 일반적으로 표본 크기와 신뢰구간 길이의 관계: 길이를 절반으로 → $n$을 4배, 길이를 $\\frac{1}{3}$로 → $n$을 9배, 길이를 $\\frac{1}{10}$로 → $n$을 100배. 이 관계는 통계 실험 설계에서 매우 중요합니다.",
