    "explanation": "**[풀이]**\n\n**핵심 개념:** 동일 표본에서 신뢰도에 따른 신뢰구간 길이 차이를 구합니다.\n\n**Step 1. 공통 표준오차 계산**\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{4}{\\sqrt{64}} = \\frac{4}{8} = 0.5$$\n\n**Step 2. 각 신뢰구간 길이 계산**\n$$L_{95} = 2 \\times 1.96 \\times 0.5 = 1.96$$\n$$L_{99} = 2 \\times 2.58 \\times 0.5 = 2.58$$\n\n**Step 3. 차이 계산**\n$$L_{99} - L_{95} = 2.58 - 1.96 = 0.62$$\n\n**∴ 답: ② 0.62**\n\n**💡 포인트:** 표준오차가 $0.5$이므로, 신뢰구간 길이는 $2 \\times z \\times 0.5 = z$가 됩니다. 따라서 길이의 차이는 $z$ 값의 차이와 같습니다.\n\n**보충:** 일반적으로 $L_{99} - L_{95} = 2(z_{0.005} - z_{0.025}) \\times \\frac{\\sigma}{\\sqrt{n}} = 2(2.58 - 1.96) \\times \\frac{\\sigma}{\\sqrt{n}} = 1.24 \\times \\frac{\\sigma}{\\sqrt{n}}$입니다. 이 문제에서 $\\frac{\\sigma}{\\sqrt{n}} = 0.5$이므로 $1.24 \\times 0.5 = 0.62$입니다. 이 차이는 신뢰도를 4% 높이는 대가로 구간이 얼마나 넓어지는지를 보여줍니다.",
