    "problem": "정규분포 $N(m, 10^2)$을 따르는 모집단에서 크기 $n$인 표본을 임의추출하여 모평균 $m$에 대한 신뢰도 95%의 신뢰구간의 길이를 $L_1$, 크기 $2n$인 표본을 임의추출하여 신뢰도 99%의 신뢰구간의 길이를 $L_2$라 하자. $\\frac{L_1}{L_2} = 1$일 때, $n$의 값을 구하시오. (단, $z_{0.025} = 1.96$, $z_{0.005} = 2.58$, 소수 첫째 자리에서 반올림)",
