    "explanation": "**[풀이]**\n\n**핵심 개념:** 모비율 $p$에 대한 신뢰구간은 표본비율 $\\hat{p}$를 사용하여 다음과 같이 구합니다.\n$$\\hat{p} - z_{\\alpha/2} \\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}} \\leq p \\leq \\hat{p} + z_{\\alpha/2} \\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}}$$\n\n**Step 1. 표본비율 계산**\n$$\\hat{p} = \\frac{240}{400} = 0.6$$\n\n**Step 2. 표준오차 계산**\n$$\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}} = \\sqrt{\\frac{0.6 \\times 0.4}{400}} = \\sqrt{\\frac{0.24}{400}} = \\sqrt{0.0006} = 0.02449$$\n\n**Step 3. 오차한계 계산**\n$$E = 1.96 \\times 0.02449 = 0.04800 \\approx 0.048$$\n\n**Step 4. 신뢰구간 구하기**\n$$0.6 - 0.048 \\leq p \\leq 0.6 + 0.048$$\n$$0.552 \\leq p \\leq 0.648$$\n\n**∴ 답: ① 0.552 ≤ p ≤ 0.648**\n\n④ 0.560 ≤ p ≤ 0.640은 오차한계를 $0.04$로 잘못 계산한 오답입니다. 이는 $\\sqrt{0.0006}$을 잘못 계산했을 때 발생합니다.\n\n**💡 포인트:** 모비율 추정에서 표준오차는 $\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}}$입니다. 모평균 추정의 $\\frac{\\sigma}{\\sqrt{n}}$과 형태가 다릅니다.\n\n**보충:** 모비율 추정에서는 $\\hat{p}(1-\\hat{p})$가 $\\hat{p} = 0.5$일 때 최대값 $0.25$를 가집니다. 따라서 $\\hat{p} = 0.5$일 때 신뢰구간이 가장 넓고, $\\hat{p}$가 0이나 1에 가까울수록 신뢰구간이 좁아집니다. 이 문제에서 $\\hat{p} = 0.6$이므로 $\\hat{p}(1-\\hat{p}) = 0.24 < 0.25$입니다.",
