    "explanation": "**[풀이]**\n\n**핵심 개념:** 모비율의 사전 정보가 없을 때, $\\hat{p}(1-\\hat{p})$가 최대인 $\\hat{p} = 0.5$를 사용하여 최소 표본 크기를 구합니다.\n$$E = z_{\\alpha/2} \\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}} \\leq 0.03$$\n\n**Step 1. 최악의 경우 ($\\hat{p} = 0.5$)**\n$\\hat{p}(1-\\hat{p})$의 최댓값은 $\\hat{p} = 0.5$일 때 $0.25$입니다.\n\n**Step 2. 부등식 세우기**\n$$1.96 \\sqrt{\\frac{0.25}{n}} \\leq 0.03$$\n$$\\sqrt{\\frac{0.25}{n}} \\leq \\frac{0.03}{1.96}$$\n$$\\frac{0.25}{n} \\leq \\left(\\frac{0.03}{1.96}\\right)^2 = \\frac{0.0009}{3.8416} = 0.0002342$$\n\n**Step 3. $n$에 대해 풀기**\n$$n \\geq \\frac{0.25}{0.0002342} = 1067.11$$\n\n올림하면 $n \\geq 1068$\n\n**별해:**\n$$n \\geq \\left(\\frac{z_{\\alpha/2}}{2E}\\right)^2 = \\left(\\frac{1.96}{2 \\times 0.03}\\right)^2 = \\left(\\frac{1.96}{0.06}\\right)^2 = (32.667)^2 = 1067.1$$\n\n올림: $n \\geq 1068$\n\n**∴ 답: ② 1068**\n\n① 849는 $\\hat{p} = 0.3$ 등 특정 비율을 가정했을 때의 값이며, 사전 정보 없이는 $\\hat{p} = 0.5$를 사용해야 합니다.\n\n**💡 포인트:** 모비율에 대한 사전 정보가 없으면 $\\hat{p} = 0.5$를 사용합니다. 이때 $\\hat{p}(1-\\hat{p}) = 0.25$가 최대이므로, 어떤 실제 비율이든 오차한계 조건을 만족합니다.\n\n**보충:** 공식 $n \\geq \\left(\\frac{z_{\\alpha/2}}{2E}\\right)^2$는 $\\hat{p} = 0.5$를 대입한 간략 공식입니다. 만약 사전 정보로 $\\hat{p} \\approx 0.3$을 알고 있다면 $n \\geq \\frac{(1.96)^2 \\times 0.3 \\times 0.7}{(0.03)^2} = 897$로 더 작은 표본이 필요합니다.",
