    "answer": 1,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 같은 표본(같은 $\\bar{X}$)에서 신뢰도만 다른 두 구간의 상한 차이를 이용하여 $\\sigma$를 구합니다.\n\n**Step 1. 각 구간의 상한 표현**\n$$b = \\bar{X} + 1.96 \\times \\frac{\\sigma}{\\sqrt{100}} = \\bar{X} + \\frac{1.96\\sigma}{10}$$\n$$d = \\bar{X} + 2.58 \\times \\frac{\\sigma}{\\sqrt{100}} = \\bar{X} + \\frac{2.58\\sigma}{10}$$\n\n**Step 2. $d - b$ 계산**\n$$d - b = \\frac{2.58\\sigma}{10} - \\frac{1.96\\sigma}{10} = \\frac{(2.58 - 1.96)\\sigma}{10} = \\frac{0.62\\sigma}{10}$$\n\n**Step 3. $\\sigma$ 구하기**\n$$\\frac{0.62\\sigma}{10} = 0.93$$\n$$0.62\\sigma = 9.3$$\n$$\\sigma = \\frac{9.3}{0.62} = 15$$\n\n**Step 4. 검증**\n$\\sigma = 15$일 때:\n$b = \\bar{X} + 1.96 \\times 1.5 = \\bar{X} + 2.94$\n$d = \\bar{X} + 2.58 \\times 1.5 = \\bar{X} + 3.87$\n$d - b = 3.87 - 2.94 = 0.93$ ✓\n\n**∴ 답: ② 15**\n\n① $\\sigma = 10$이면 $d - b = \\frac{0.62 \\times 10}{10} = 0.62 \\neq 0.93$입니다.\n\n**💡 포인트:** 같은 표본에서 신뢰도만 다른 두 구간의 상한(또는 하한) 차이는 $\\frac{(z_2 - z_1)\\sigma}{\\sqrt{n}}$입니다. 표본평균이 상쇄되어 간단해집니다.\n\n**보충:** 마찬가지로 $a - c = d - b = 0.93$입니다. 99% 구간이 95% 구간을 포함하므로 $c < a < b < d$입니다. 두 구간의 '확장폭'은 양쪽 동일하며, 이는 대칭적인 정규분포의 특성 때문입니다.",
