    "problem": "정규분포 $N(m, 8^2)$을 따르는 모집단에서 크기 $n_1 = a$인 표본을 임의추출하여 모평균 $m$에 대한 신뢰도 95%의 신뢰구간을 구한 것의 길이와, 크기 $n_2 = b$인 표본을 임의추출하여 신뢰도 99%의 신뢰구간을 구한 것의 길이가 같다. $b = 2a$일 때, $a$의 값을 구하면? (단, $z_{0.025} = 1.96$, $z_{0.005} = 2.58$, 소수 첫째 자리에서 반올림)",
