    "problem": "어느 회사의 제품 불량률을 조사하기 위해 500개의 제품을 임의추출하여 검사한 결과, 불량품이 40개였다. 모비율 $p$(불량률)에 대한 신뢰도 99%의 신뢰구간의 오차한계를 구하면? (단, $z_{0.005} = 2.58$, 소수점 넷째 자리에서 반올림)",
