    "problem": "정규분포 $N(m, \\sigma^2)$을 따르는 두 모집단 $A$, $B$가 있다. $A$의 모표준편차는 $\\sigma_A = 6$, $B$의 모표준편차는 $\\sigma_B = 9$이다. $A$에서 크기 $n_A$, $B$에서 크기 $n_B$인 표본을 각각 임의추출하여 신뢰도 95%의 신뢰구간을 구할 때, 두 신뢰구간의 길이가 같으려면 $\\frac{n_B}{n_A}$의 값은? (단, $z_{0.025} = 1.96$)",
    "answerType": "choice",
