    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 같은 신뢰도에서 서로 다른 모표준편차를 가진 두 모집단의 신뢰구간 길이를 같게 만드는 표본 크기 비를 구합니다.\n\n**Step 1. 두 신뢰구간 길이가 같은 조건**\n$$L_A = L_B$$\n$$2 \\times 1.96 \\times \\frac{6}{\\sqrt{n_A}} = 2 \\times 1.96 \\times \\frac{9}{\\sqrt{n_B}}$$\n\n$2 \\times 1.96$이 공통이므로 상쇄:\n$$\\frac{6}{\\sqrt{n_A}} = \\frac{9}{\\sqrt{n_B}}$$\n\n**Step 2. 정리**\n$$\\frac{\\sqrt{n_B}}{\\sqrt{n_A}} = \\frac{9}{6} = \\frac{3}{2}$$\n$$\\sqrt{\\frac{n_B}{n_A}} = \\frac{3}{2}$$\n$$\\frac{n_B}{n_A} = \\left(\\frac{3}{2}\\right)^2 = \\frac{9}{4} = 2.25$$\n\n**Step 3. 검증**\n예: $n_A = 100$이면 $n_B = 225$\n$L_A = 2 \\times 1.96 \\times \\frac{6}{10} = 2.352$\n$L_B = 2 \\times 1.96 \\times \\frac{9}{15} = 2.352$ ✓\n\n**∴ 답: ③ 2.25**\n\n**💡 포인트:** 같은 신뢰도에서 신뢰구간 길이를 같게 하려면 표본 크기의 비가 모표준편차 비의 제곱이어야 합니다: $\\frac{n_B}{n_A} = \\left(\\frac{\\sigma_B}{\\sigma_A}\\right)^2$\n\n**보충:** 모표준편차가 큰 모집단에서는 더 많은 표본이 필요합니다. $\\sigma_B = 1.5 \\sigma_A$이므로 $n_B = 1.5^2 \\times n_A = 2.25 n_A$입니다. 이 관계는 실험 설계에서 각 그룹의 표본 크기를 결정할 때 유용합니다.",
