    "problem": "어느 도시의 유권자 중 $n$명을 임의추출하여 특정 후보 지지 여부를 조사했더니 지지자가 $0.4n$명이었다. 모비율 $p$에 대한 신뢰도 95%의 신뢰구간의 오차한계가 $0.04$ 이하가 되도록 하는 $n$의 최솟값을 구하시오. (단, $z_{0.025} = 1.96$)",
    "answerType": "short",
    "choices": null,
    "answer": 577,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 표본비율 $\\hat{p} = 0.4$가 주어진 상태에서 오차한계 조건을 만족하는 최소 $n$을 구합니다.\n\n**Step 1. 표본비율 확인**\n$$\\hat{p} = \\frac{0.4n}{n} = 0.4$$\n\n**Step 2. 오차한계 부등식**\n$$E = 1.96 \\sqrt{\\frac{0.4 \\times 0.6}{n}} \\leq 0.04$$\n\n**Step 3. $n$에 대해 풀기**\n$$\\sqrt{\\frac{0.24}{n}} \\leq \\frac{0.04}{1.96} = 0.020408$$\n$$\\frac{0.24}{n} \\leq (0.020408)^2 = 0.0004165$$\n$$n \\geq \\frac{0.24}{0.0004165} = 576.23$$\n\n더 정확히:\n$$n \\geq \\frac{(1.96)^2 \\times 0.4 \\times 0.6}{(0.04)^2} = \\frac{3.8416 \\times 0.24}{0.0016} = \\frac{0.92198}{0.0016} = 576.24$$\n\n올림: $n \\geq 577$\n\n**Step 4. 검증**\n$n = 577$: $E = 1.96 \\sqrt{\\frac{0.24}{577}} = 1.96 \\times 0.02039 = 0.03997 \\leq 0.04$ ✓\n$n = 576$: $E = 1.96 \\sqrt{\\frac{0.24}{576}} = 1.96 \\times 0.02041 = 0.04000$ (경계)\n\n정확히 $n = 576$일 때 $\\sqrt{\\frac{0.24}{576}} = \\sqrt{0.000416\\overline{6}} = 0.020412$\n$E = 1.96 \\times 0.020412 = 0.040008 > 0.04$ ✗\n\n**∴ 답: 577**\n\n**💡 포인트:** 모비율 추정에서 표본 크기 공식은 $n \\geq \\frac{z^2 \\hat{p}(1-\\hat{p})}{E^2}$입니다. 사전 정보($\\hat{p}$)가 있으면 이를 사용하고, 없으면 $\\hat{p} = 0.5$를 사용합니다.\n\n**보충:** $\\hat{p} = 0.4$를 사용하면 $n = 577$이지만, 사전 정보 없이 $\\hat{p} = 0.5$를 사용하면 $n \\geq \\frac{(1.96)^2 \\times 0.25}{(0.04)^2} = \\frac{0.9604}{0.0016} = 600.25$이므로 $n \\geq 601$이 필요합니다. 사전 정보를 활용하면 표본 크기를 줄일 수 있습니다.",
    "difficulty": "lv4",
