    "problem": "6명의 학생 중에서 3명을 선택하여 일렬로 세우는 경우의 수를 $a$, 6명 중 3명을 선택하는 조합의 수를 $b$라 하자. 이 $b$명을 한 모둠으로 만들어 각 모둠에서 대표 1명을 뽑을 때, 대표가 될 확률이 $\\frac{1}{b}$인 특정 학생이 대표로 뽑히지 않을 확률은?",
    "answerType": "choice",
    "choices": [
      "① $\\frac{14}{20}$",
      "② $\\frac{16}{20}$",
      "③ $\\frac{17}{20}$",
      "④ $\\frac{18}{20}$",
      "⑤ $\\frac{19}{20}$"
    ],
    "answer": 4,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 순열과 조합의 관계, 여사건의 확률\n\n**Step 1. $a$와 $b$ 계산**\n$a = {}_6P_3 = 6 \\times 5 \\times 4 = 120$\n$b = {}_6C_3 = \\frac{6!}{3!3!} = 20$\n\n순열과 조합의 관계를 확인하면:\n$$a = b \\times 3! = 20 \\times 6 = 120 \\checkmark$$\n\n**Step 2. 문제 해석**\n$b = 20$이므로 20명을 한 모둠으로 구성합니다. 특정 학생이 대표가 될 확률이 $\\frac{1}{b} = \\frac{1}{20}$입니다.\n\n**Step 3. 여사건 활용**\n대표로 뽑히지 않을 확률은:\n$$P(\\text{뽑히지 않음}) = 1 - P(\\text{뽑힘}) = 1 - \\frac{1}{20} = \\frac{19}{20}$$\n\n**Step 4. 검증**\n$\\frac{19}{20} = 0.95$로, 20명 중 1명이 뽑힐 확률의 여사건이므로 합리적입니다. ✓\n\n**∴ 답: ⑤ $\\frac{19}{20}$**\n\n순열($a$)과 조합($b$)의 관계 $P_r = C_r \\times r!$을 통해 $b$의 값을 구한 후, 여사건의 확률을 활용하는 기초 융합 문제입니다. 순열·조합이 확률의 전제 조건을 결정하는 구조를 이해하는 것이 핵심입니다.\n\n**💡 포인트:** 순열과 조합의 관계를 먼저 파악한 뒤, 구한 값을 확률 계산에 활용하는 2단계 사고가 필요합니다.",
