    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 순열과 확률의 융합 — 조건부 배열 문제\n\n**Step 1. 전체 경우의 수**\n5개에서 3개를 골라 일렬로 배열:\n$${}_5P_3 = 5 \\times 4 \\times 3 = 60$$\n\n**Step 2. 짝수가 되려면**\n일의 자리가 짝수(2 또는 4)여야 합니다.\n\n**(i) 일의 자리가 2인 경우:**\n나머지 두 자리에 {1,3,4,5}에서 2개를 순서대로 배열:\n$${}_4P_2 = 12$$\n\n**(ii) 일의 자리가 4인 경우:**\n나머지 두 자리에 {1,2,3,5}에서 2개를 순서대로 배열:\n$${}_4P_2 = 12$$\n\n**Step 3. 확률 계산**\n짝수인 경우의 수: $12 + 12 = 24$가 아닌... 아, 문제 없습니다.\n$$P = \\frac{24}{60} = \\frac{2}{5}$$\n\n다시 선택지를 확인하면 $\\frac{2}{5}$는 ③번입니다.\n\n하지만 짝수 숫자 개수/전체 숫자 개수 = 2/5로도 바로 구할 수 있습니다. 일의 자리에 올 수 있는 5개 숫자 중 짝수는 2개이므로, 대칭성에 의해 $P = \\frac{2}{5}$입니다.\n\n**∴ 답: ③ $\\frac{2}{5}$**\n\n순열의 경우의 수를 구한 후 특정 조건(짝수)을 만족하는 경우를 세어 확률을 구하는 융합 문제입니다. 대칭성을 이용하면 빠르게 풀 수 있습니다.\n\n**💡 포인트:** 각 숫자가 특정 자리에 올 확률은 동일(대칭성)하므로, 일의 자리 관점에서만 보면 됩니다.",
