    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 원순열 + 확률 기초 융합\n\n**Step 1. A가 이길 확률 $p$ 계산**\n가위바위보에서 A, B 각각 3가지를 내므로 전체 경우: $3 \\times 3 = 9$\nA가 이기는 경우: (가위,보), (바위,가위), (보,바위) → 3가지\n$$p = \\frac{3}{9} = \\frac{1}{3}$$\n\n**Step 2. 원순열 $n$ 계산**\n5명이 원형으로 앉는 경우의 수:\n$$n = (5-1)! = 4! = 24$$\n\n**Step 3. $n \\times p$ 계산**\n$$n \\times p = 24 \\times \\frac{1}{3} = 8$$\n\n**Step 4. 검증**\n원순열 공식 $(n-1)!$에서 $n=5$이면 $24$, 가위바위보 승리 확률 $\\frac{1}{3}$은 기본 지식. $24 \\times \\frac{1}{3} = 8$ ✓\n\n**∴ 답: ③ 8**\n\n서로 다른 영역(원순열과 확률)의 기본 공식을 결합하여 하나의 답을 도출하는 기초 융합 문제입니다. 각 개념을 정확히 알고 있으면 쉽게 풀 수 있지만, 하나라도 모르면 풀 수 없는 구조입니다.\n\n**💡 포인트:** 복합 문제에서는 각 개념을 독립적으로 계산한 후 결합하는 전략이 효과적입니다.",
