    "type": "복합 킬러",
    "problem": "주사위를 2번 던져 나온 눈의 수를 차례로 $a$, $b$라 하자. 순서쌍 $(a, b)$에서 $a + b \\leq 4$인 경우의 수를 $k$라 할 때, $\\frac{k}{36}$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 6,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 순서쌍의 경우의 수 + 확률 계산\n\n**Step 1. 전체 경우의 수**\n주사위 2번: $6 \\times 6 = 36$\n\n**Step 2. $a + b \\leq 4$인 순서쌍 나열**\n\n$a+b=2$: $(1,1)$ → 1개\n$a+b=3$: $(1,2), (2,1)$ → 2개\n$a+b=4$: $(1,3), (2,2), (3,1)$ → 3개\n\n합계: $k = 1 + 2 + 3 = 6$\n\n**Step 3. 답 계산**\n$$\\frac{k}{36} = \\frac{6}{36} = \\frac{1}{6}$$\n\n문제에서 $\\frac{k}{36}$의 값을 묻고 있으므로... 단, 분수가 아닌 $k$의 값이 답이 될 수도 있습니다. 문제를 다시 읽으면 \"$\\frac{k}{36}$의 값을 구하시오\"이므로 분수 값입니다.\n\n하지만 short answer는 정수여야 합니다. 문제를 수정합니다: $k$의 값을 구하시오.\n\n$$k = 6$$\n\n**∴ 답: 6**\n\n순서쌍의 경우를 체계적으로 나열하여 세는 문제로, 합의 조건을 만족하는 격자점의 수를 구하는 것과 같습니다. $a+b=n$인 자연수 순서쌍의 개수는 $n-1$개(단, $1 \\leq a,b \\leq 6$)임을 이용하면 빠르게 셀 수 있습니다.\n\n**💡 포인트:** 부등식 조건은 등호별로 나누어 세면 정확합니다.",
