    "explanation": "**[풀이]**\n\n**핵심 개념:** 조합의 분할 (같은 크기 그룹으로 나누기)\n\n**Step 1. 기본 선택**\n6명에서 2명 선택 → 나머지 4명에서 2명 선택 → 나머지 2명 자동 결정:\n$${}_6C_2 \\times {}_4C_2 \\times {}_2C_2 = 15 \\times 6 \\times 1 = 90$$\n\n**Step 2. 중복 제거**\n3개 조의 크기가 모두 같으므로(2명씩), 조 사이의 순서는 의미가 없습니다.\n따라서 $3! = 6$으로 나누어야 합니다.\n$$\\frac{90}{3!} = \\frac{90}{6} = 15$$\n\n**Step 3. 검증**\n구체적으로 확인: 학생을 A,B,C,D,E,F라 하면\nA와 짝이 될 수 있는 학생: 5명\n각 경우에 나머지 4명에서 2명씩 나누는 수: $\\frac{{}_4C_2}{2!} = 3$\n총: $5 \\times 3 = 15$ ✓\n\n**∴ 답: 15**\n\n같은 크기 그룹으로의 분할 문제는 순열과 조합이 결합되는 대표적 융합 유형입니다. 핵심은 '같은 크기 그룹의 순서는 구분하지 않는다'는 점에서 그룹 수의 팩토리얼로 나누는 것입니다.\n\n**💡 포인트:** 같은 크기 $k$개 조로 나눌 때 $k!$로 나누는 것을 잊지 마세요. 조의 크기가 다르면 나눌 필요 없습니다.",
