    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포 + 여사건 + 조합\n\n불량품 수를 확률변수 $X$라 하면 $X \\sim B(10, 0.1)$\n\n**Step 1. 여사건 활용**\n$$P(X \\geq 2) = 1 - P(X=0) - P(X=1)$$\n\n**Step 2. 각 항 계산**\n$$P(X=0) = \\left(\\frac{9}{10}\\right)^{10} \\approx 0.349$$\n\n$$P(X=1) = {}_{10}C_1 \\cdot \\frac{1}{10} \\cdot \\left(\\frac{9}{10}\\right)^{9} = 10 \\times 0.1 \\times 0.387 = 0.387$$\n\n**Step 3. $P$ 계산**\n$$P = 1 - 0.349 - 0.387 = 0.264$$\n\n**Step 4. 검증**\n$0.349 + 0.387 = 0.736$이고, $1 - 0.736 = 0.264$ ✓\n\n불량품이 2개 이상일 확률이 약 26.4%로, 불량률 10%에서 10개 중 2개 이상이 불량일 확률로서 합리적입니다.\n\n**∴ 답: ④ 0.264**\n\n이항분포에서 '이상' 조건의 확률을 여사건으로 구하는 대표적 융합 문제입니다. 직접 $P(X=2) + P(X=3) + \\cdots$를 구하는 것보다 여사건이 훨씬 효율적입니다.\n\n**💡 포인트:** $P(X \\geq k)$는 여사건 $1 - \\sum_{i=0}^{k-1} P(X=i)$로 구하는 것이 정석입니다.",
