    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건부확률의 정의와 합집합\n\n**Step 1. 사건 파악**\n$A = \\{2, 4, 6, 8, 10\\}$, $|A| = 5$\n$B = \\{3, 6, 9\\}$, $|B| = 3$\n$A \\cap B = \\{6\\}$, $|A \\cap B| = 1$\n\n**Step 2. 조건부확률 계산**\n$$P(A|B) = \\frac{P(A \\cap B)}{P(B)} = \\frac{1/10}{3/10} = \\frac{1}{3}$$\n\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)} = \\frac{1/10}{5/10} = \\frac{1}{5}$$\n\n**Step 3. 합 계산**\n$$P(A|B) + P(B|A) = \\frac{1}{3} + \\frac{1}{5} = \\frac{5+3}{15} = \\frac{8}{15}$$\n\n**Step 4. 검증**\n두 조건부확률 모두 0과 1 사이이고, 합도 1 이하이므로 합리적입니다. ✓\n\n**∴ 답: ② $\\frac{8}{15}$**\n\n조건부확률의 정의를 두 방향으로 적용하는 문제입니다. $P(A|B)$와 $P(B|A)$는 일반적으로 다르다는 것을 이해하는 것이 핵심입니다. 분모가 달라지므로 값이 달라집니다.\n\n**💡 포인트:** $P(A|B) \\neq P(B|A)$가 일반적입니다. 베이즈 정리로 둘의 관계를 표현할 수 있습니다: $P(A|B) = \\frac{P(B|A) \\cdot P(A)}{P(B)}$.",
