    "explanation": "**[풀이]**\n\n**핵심 개념:** 비복원추출에서의 조건부확률\n\n**Step 1. $P_1$ 계산 (첫 번째 흰 → 두 번째 흰)**\n첫 번째에 흰 공을 꺼냈으면 남은 공: 흰 4개, 검은 3개 = 총 7개\n$$P_1 = \\frac{4}{7}$$\n\n**Step 2. $P_2$ 계산 (첫 번째 검은 → 두 번째 흰)**\n첫 번째에 검은 공을 꺼냈으면 남은 공: 흰 5개, 검은 2개 = 총 7개\n$$P_2 = \\frac{5}{7}$$\n\n**Step 3. 합 계산**\n$$P_1 + P_2 = \\frac{4}{7} + \\frac{5}{7} = \\frac{9}{7}$$\n\n**Step 4. 검증**\n$P_1 = \\frac{4}{7} \\approx 0.571$, $P_2 = \\frac{5}{7} \\approx 0.714$\n합이 1을 초과하지만, 이는 두 개의 서로 다른 조건부확률의 합이므로 문제없습니다. ✓\n\n**∴ 답: ③ $\\frac{9}{7}$**\n\n비복원추출에서 조건에 따라 표본공간이 달라지는 것을 이해하는 것이 핵심입니다. 복원추출이라면 $P_1 = P_2 = \\frac{5}{8}$이 되지만, 비복원이므로 첫 번째 결과에 따라 두 번째 확률이 변합니다.\n\n**💡 포인트:** 비복원추출의 조건부확률은 '남은 공'의 구성으로 계산합니다.",
