    "problem": "확률변수 $X$가 이항분포 $B(8, p)$를 따르고, $P(X=2) = P(X=6)$일 때, $V(X)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 확률 대칭성 → 분산 계산\n\n**Step 1. 조건 분석**\n$X \\sim B(8, p)$에서\n$$P(X=2) = {}_8C_2 \\, p^2(1-p)^6$$\n$$P(X=6) = {}_8C_6 \\, p^6(1-p)^2$$\n\n${}_8C_2 = {}_8C_6 = 28$이므로:\n$$p^2(1-p)^6 = p^6(1-p)^2$$\n\n**Step 2. $p$ 결정**\n양변을 $p^2(1-p)^2$으로 나누면 ($0 < p < 1$):\n$$(1-p)^4 = p^4$$\n$$\\left(\\frac{1-p}{p}\\right)^4 = 1$$\n$$\\frac{1-p}{p} = 1 \\quad (\\because 0 < p < 1)$$\n$$1 - p = p \\implies p = \\frac{1}{2}$$\n\n**Step 3. 분산 계산**\n$$V(X) = np(1-p) = 8 \\times \\frac{1}{2} \\times \\frac{1}{2} = 2$$\n\n**Step 4. 검증**\n$p = \\frac{1}{2}$이면 이항분포 $B(8, \\frac{1}{2})$는 $X = 4$에 대해 대칭이므로 $P(X=2) = P(X=6)$은 당연히 성립합니다. ✓\n$V(X) = 8 \\times 0.25 = 2$ ✓\n\n**∴ 답: 2**\n\n이항분포에서 대칭이 되는 $p$ 값을 구하는 것이 핵심입니다. $P(X=k) = P(X=n-k)$이면 $p = \\frac{1}{2}$라는 성질을 알면 빠르게 풀 수 있습니다.\n\n**💡 포인트:** 이항분포 $B(n,p)$에서 $P(X=k) = P(X=n-k)$는 $p = \\frac{1}{2}$의 필요충분조건입니다.",
