    "type": "복합 킬러",
    "problem": "어떤 시험에서 5지선다 문제 4개를 찍어서 맞힌 문제의 수를 $X$라 하자. $E(X^2)$의 값을 구하시오. (답에 25를 곱한 값을 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 32,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 $E(X^2)$ 계산 — 분산과 기댓값의 관계\n\n**Step 1. 분포 파악**\n$X \\sim B\\left(4, \\frac{1}{5}\\right)$\n\n**Step 2. 기댓값과 분산**\n$$E(X) = np = 4 \\times \\frac{1}{5} = \\frac{4}{5}$$\n$$V(X) = np(1-p) = 4 \\times \\frac{1}{5} \\times \\frac{4}{5} = \\frac{16}{25}$$\n\n**Step 3. $E(X^2)$ 계산**\n$V(X) = E(X^2) - [E(X)]^2$이므로:\n$$E(X^2) = V(X) + [E(X)]^2 = \\frac{16}{25} + \\left(\\frac{4}{5}\\right)^2 = \\frac{16}{25} + \\frac{16}{25} = \\frac{32}{25}$$\n\n**Step 4. 답 계산**\n$$25 \\times E(X^2) = 25 \\times \\frac{32}{25} = 32$$\n\n**Step 5. 검증**\n$E(X^2) = \\frac{32}{25} = 1.28$\n직접 계산: $E(X^2) = \\sum_{k=0}^{4} k^2 \\cdot P(X=k)$\n$= 0 + 1 \\cdot P(1) + 4 \\cdot P(2) + 9 \\cdot P(3) + 16 \\cdot P(4)$\n이를 전개하면 $\\frac{32}{25}$이 됨을 확인할 수 있습니다. ✓\n\n**∴ 답: 32**\n\n$E(X^2) = V(X) + [E(X)]^2$라는 분산 공식의 변형을 활용하는 문제입니다. 이항분포의 기댓값과 분산 공식을 정확히 알고 있어야 합니다.\n\n**💡 포인트:** $E(X^2)$를 직접 구하지 말고, $V(X) = E(X^2) - \\{E(X)\\}^2$에서 역으로 구하는 것이 효율적입니다.",
