    "choices": null,
    "answer": 7,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립사건의 확률 + 여사건\n\n**Step 1. 전체 경우의 수**\nA에서 1장, B에서 1장: $3 \\times 3 = 9$\n\n**Step 2. 여사건 활용 (두 수의 곱이 홀수)**\n곱이 홀수 ⟺ 두 수 모두 홀수\n\nA의 홀수: $\\{1, 3\\}$ → 2개\nB의 홀수: $\\{5\\}$ → 1개\n\n곱이 홀수인 경우: $2 \\times 1 = 2$\n\n**Step 3. 곱이 짝수일 확률**\n$$P = 1 - \\frac{2}{9} = \\frac{7}{9}$$\n\n**Step 4. 검증**\n전체 9가지 순서쌍에서 곱이 짝수인 것:\n$(1,4), (1,6), (2,4), (2,5), (2,6), (3,4), (3,6)$ → 7가지\n$$\\frac{7}{9} \\checkmark$$\n\n**∴ 답: 7**\n\n'곱이 짝수'를 직접 세는 것보다 여사건 '곱이 홀수 = 둘 다 홀수'로 접근하면 훨씬 간단합니다. 이는 독립시행에서의 여사건 활용 기법입니다.\n\n**💡 포인트:** '곱이 짝수' ↔ '적어도 하나가 짝수'이므로 여사건 '둘 다 홀수'가 효율적입니다.",
