    "type": "복합 킬러",
    "problem": "주머니에 1부터 9까지의 자연수가 적힌 카드 9장이 있다. 이 중 4장을 동시에 꺼낼 때, 꺼낸 카드에 적힌 수의 합이 짝수이고 최댓값이 8 이상일 확률은?",
