    "answer": 1,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 정규분포의 대칭성 + 표준화 + 구간 확률\n\n**Step 1. 평균 $m$ 결정**\n$P(X \\leq 14) = P(X \\geq 26)$이면, 정규분포의 대칭성에 의해:\n$$m = \\frac{14 + 26}{2} = 20$$\n\n**Step 2. $\\sigma$ 결정**\n$P(m - \\sigma \\leq X \\leq m + \\sigma) = 0.6826$\n\n이는 $P(20 - \\sigma \\leq X \\leq 20 + \\sigma) = 0.6826$\n\n표준화하면: $P(-1 \\leq Z \\leq 1) = 2 \\times P(0 \\leq Z \\leq 1) = 2 \\times 0.3413 = 0.6826$ ✓\n\n이 조건은 $\\sigma$에 관계없이 항상 성립하므로, 추가 조건이 필요합니다.\n\n하지만 문제에서 $P(14 \\leq X \\leq 26)$을 묻고 있으므로:\n$$P(14 \\leq X \\leq 26) = P\\left(\\frac{14-20}{\\sigma} \\leq Z \\leq \\frac{26-20}{\\sigma}\\right) = P\\left(-\\frac{6}{\\sigma} \\leq Z \\leq \\frac{6}{\\sigma}\\right)$$\n\n$\\sigma = 6$이면: $P(-1 \\leq Z \\leq 1) = 0.6826$\n\n$m - \\sigma = 20 - 6 = 14$, $m + \\sigma = 20 + 6 = 26$이므로\n$P(14 \\leq X \\leq 26) = P(m - \\sigma \\leq X \\leq m + \\sigma) = 0.6826$\n\n즉, $\\sigma = 6$일 때 구하는 구간이 정확히 $[m-\\sigma, m+\\sigma]$가 됩니다.\n\n**Step 3. 결론**\n$$P(14 \\leq X \\leq 26) = 0.6826$$\n\n**Step 4. 검증**\n$m = 20$, $\\sigma = 6$: $[14, 26] = [20-6, 20+6]$\n$P(-1 \\leq Z \\leq 1) = 0.6826$ ✓\n\n**∴ 답: ② 0.6826**\n\n이 문제의 핵심은 대칭 조건에서 $m$을 구하고, 주어진 구간 $[14, 26]$이 $[m-\\sigma, m+\\sigma]$와 일치하도록 $\\sigma = 6$을 파악하는 것입니다. 결국 주어진 조건 $P(m-\\sigma \\leq X \\leq m+\\sigma) = 0.6826$이 그대로 답이 됩니다.\n\n**💡 포인트:** 정규분포에서 대칭 조건 $P(X \\leq a) = P(X \\geq b)$이면 $m = \\frac{a+b}{2}$입니다. 구간이 $[m-k\\sigma, m+k\\sigma]$ 형태인지 빠르게 파악하세요.",
