    "explanation": "**[풀이]**\n\n**핵심 개념:** 베이즈 정리 (조건부확률의 역방향)\n\n**Step 1. 사건 정의**\n$M$: 남학생, $F$: 여학생, $G$: 안경 착용\n$P(M) = 0.6$, $P(F) = 0.4$\n$P(G|M) = 0.4$, $P(G|F) = 0.3$\n\n**Step 2. 전체 안경 착용 확률 (전확률 공식)**\n$$P(G) = P(G|M) \\cdot P(M) + P(G|F) \\cdot P(F)$$\n$$= 0.4 \\times 0.6 + 0.3 \\times 0.4 = 0.24 + 0.12 = 0.36$$\n\n**Step 3. 베이즈 정리 적용**\n$$P(M|G) = \\frac{P(G|M) \\cdot P(M)}{P(G)} = \\frac{0.24}{0.36} = \\frac{24}{36} = \\frac{2}{3}$$\n\n**Step 4. 검증**\n1000명 기준: 남 600명(안경 240명), 여 400명(안경 120명)\n전체 안경: 360명, 그 중 남: 240명\n$P(M|G) = \\frac{240}{360} = \\frac{2}{3}$ ✓\n\n**∴ 답: ④ $\\frac{2}{3}$**\n\n베이즈 정리는 조건부확률의 방향을 뒤집는 핵심 도구입니다. '안경을 쓴 사람이 남학생일 확률'을 구하기 위해 '남학생이 안경을 쓸 확률'과 사전확률을 결합합니다. 분모의 전확률을 정확히 계산하는 것이 관건입니다.\n\n**💡 포인트:** 베이즈 정리 문제는 구체적 숫자(예: 1000명)를 가정하면 직관적으로 풀 수 있습니다.",
