    "explanation": "**[풀이]**\n\n**핵심 개념:** 조합 + 부등식 조건 + 연속성 제한 (다중 제약 조건)\n\n**Step 1. 전체 경우의 수**\n$${}_7C_3 = 35$$\n\n**Step 2. 연속하는 두 수가 포함되지 않는 3원소 부분집합**\n$\\{1,...,7\\}$에서 연속하지 않는 3개 선택:\n원소를 $a < b < c$로 놓으면 $b \\geq a+2$, $c \\geq b+2$.\n\n치환: $a' = a$, $b' = b-1$, $c' = c-2$로 놓으면 $1 \\leq a' < b' < c' \\leq 5$\n경우의 수: ${}_5C_3 = 10$\n\n구체적으로 나열:\n$\\{1,3,5\\}, \\{1,3,6\\}, \\{1,3,7\\}, \\{1,4,6\\}, \\{1,4,7\\}, \\{1,5,7\\},$\n$\\{2,4,6\\}, \\{2,4,7\\}, \\{2,5,7\\}, \\{3,5,7\\}$\n\n**Step 3. 합이 12 이상인 것 선별**\n각 집합의 합:\n$\\{1,3,5\\}$: 9, $\\{1,3,6\\}$: 10, $\\{1,3,7\\}$: 11, $\\{1,4,6\\}$: 11,\n$\\{1,4,7\\}$: 12 ✓, $\\{1,5,7\\}$: 13 ✓,\n$\\{2,4,6\\}$: 12 ✓, $\\{2,4,7\\}$: 13 ✓, $\\{2,5,7\\}$: 14 ✓, $\\{3,5,7\\}$: 15 ✓\n\n합 ≥ 12인 것: 6개\n\n**Step 4. 확률 계산**\n$$P = \\frac{6}{35}$$\n\n**Step 5. 검증**\n10개의 비연속 집합 중 6개가 합 ≥ 12를 만족. ✓\n\n**∴ 답: ④ $\\frac{6}{35}$**\n\n이 문제는 (1) 비연속 조건으로 후보를 제한하고, (2) 합 조건으로 다시 필터링하는 수능 30번급 다조건 조합 문제입니다. 치환 기법으로 비연속 조건의 경우의 수를 체계적으로 세는 것이 핵심입니다.\n\n**💡 포인트:** 연속하지 않는 $k$개 선택 = 치환 후 ${n-k+1 \\choose k}$ 공식을 외워두세요.",
