    "explanation": "**[풀이]**\n\n**핵심 개념:** 이항분포의 정규근사 + 표준화 → 모수 결정\n\n**Step 1. 정규근사 조건**\n$X \\sim B(100, p)$를 $X \\approx N(100p, 100p(1-p))$로 근사.\n\n**Step 2. 표준화**\n$$P(X \\geq 55) = P\\left(Z \\geq \\frac{55 - 100p}{\\sqrt{100p(1-p)}}\\right) = P(Z \\geq 1)$$\n\n따라서:\n$$\\frac{55 - 100p}{10\\sqrt{p(1-p)}} = 1$$\n\n$$55 - 100p = 10\\sqrt{p(1-p)} \\quad \\cdots (*)$$\n\n**Step 3. $p$ 결정**\n$(*)$에서 좌변이 양수이므로 $55 - 100p > 0$, 즉 $p < 0.55$.\n\n양변을 제곱:\n$$(55 - 100p)^2 = 100p(1-p)$$\n$$3025 - 11000p + 10000p^2 = 100p - 100p^2$$\n$$10100p^2 - 11100p + 3025 = 0$$\n\n판별식: $D = 11100^2 - 4 \\times 10100 \\times 3025$\n$= 123210000 - 122210000 = 1000000$\n$\\sqrt{D} = 1000$\n\n$$p = \\frac{11100 \\pm 1000}{20200}$$\n$$p = \\frac{12100}{20200} = \\frac{121}{202} = 0.599... \\quad \\text{또는} \\quad p = \\frac{10100}{20200} = \\frac{1}{2} = 0.5$$\n\n$p < 0.55$ 조건에서 $p = 0.5$.\n\n**Step 4. 분산 계산**\n$$V(X) = 100 \\times 0.5 \\times 0.5 = 25$$\n\n**Step 5. 검증**\n$p = 0.5$일 때: $\\frac{55-50}{\\sqrt{25}} = \\frac{5}{5} = 1$ ✓\n$P(X \\geq 55) = P(Z \\geq 1)$ ✓\n\n**∴ 답: ④ 25**\n\n이항분포를 정규분포로 근사한 뒤, 표준화 결과를 연립방정식으로 풀어 모수를 결정하는 고난도 융합 문제입니다. 이차방정식을 정확히 풀고, 부등식 조건으로 근을 선택하는 것이 핵심입니다.\n\n**💡 포인트:** 표준화 공식 $Z = \\frac{X - \\mu}{\\sigma}$를 정확히 세운 뒤, 연립방정식으로 모수를 구합니다.",
