    "type": "복합 킬러",
    "problem": "두 사건 $A$, $B$가 독립이고 $P(A) = \\frac{1}{3}$, $P(A \\cup B) = \\frac{3}{5}$일 때, $P(B)$의 값을 구한 후, $30 \\times P(A^c \\cap B)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 8,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 독립사건 + 합사건 공식 + 여사건\n\n**Step 1. $P(B)$ 결정**\n독립이므로 $P(A \\cap B) = P(A) \\cdot P(B) = \\frac{1}{3} P(B)$\n\n합사건 공식:\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n$$\\frac{3}{5} = \\frac{1}{3} + P(B) - \\frac{1}{3}P(B)$$\n$$\\frac{3}{5} - \\frac{1}{3} = \\frac{2}{3}P(B)$$\n$$\\frac{9-5}{15} = \\frac{2}{3}P(B)$$\n$$\\frac{4}{15} = \\frac{2}{3}P(B)$$\n$$P(B) = \\frac{4}{15} \\times \\frac{3}{2} = \\frac{2}{5}$$\n\n**Step 2. $P(A^c \\cap B)$ 계산**\n$$P(A^c \\cap B) = P(B) - P(A \\cap B) = \\frac{2}{5} - \\frac{1}{3} \\times \\frac{2}{5} = \\frac{2}{5}\\left(1 - \\frac{1}{3}\\right) = \\frac{2}{5} \\times \\frac{2}{3} = \\frac{4}{15}$$\n\n또는 독립이므로: $P(A^c \\cap B) = P(A^c) \\cdot P(B) = \\frac{2}{3} \\times \\frac{2}{5} = \\frac{4}{15}$\n\n**Step 3. 답 계산**\n$$30 \\times P(A^c \\cap B) = 30 \\times \\frac{4}{15} = 8$$\n\n**Step 4. 검증**\n$P(A \\cup B) = \\frac{1}{3} + \\frac{2}{5} - \\frac{2}{15} = \\frac{5+6-2}{15} = \\frac{9}{15} = \\frac{3}{5}$ ✓\n\n**∴ 답: 8**\n\n독립사건의 성질 $P(A \\cap B) = P(A)P(B)$를 합사건 공식에 대입하여 미지수를 구하고, 여사건과의 교집합을 독립성으로 간단히 처리하는 다단계 문제입니다.\n\n**💡 포인트:** $A$와 $B$가 독립이면 $A^c$와 $B$도 독립입니다. 이 성질을 활용하면 계산이 간결해집니다.",
