    "explanation": "**[풀이]**\n\n**핵심 개념:** 주사위 합의 분포 (생성함수 또는 직접 계수)\n\n**Step 1. 전체 경우의 수**\n주사위 3번: $6^3 = 216$\n\n**Step 2. $S_3 = 10$인 경우의 수**\n$x_1 + x_2 + x_3 = 10$ ($1 \\leq x_i \\leq 6$)\n\n$y_i = x_i - 1$로 치환: $y_1 + y_2 + y_3 = 7$ ($0 \\leq y_i \\leq 5$)\n\n제한 없는 경우: ${}_9C_2 = 36$\n\n$y_i \\geq 6$인 경우 제외:\n$y_i \\geq 6$이면 $z_i = y_i - 6$으로 치환, 나머지 두 변수의 합 = $7 - 6 = 1$.\n각 $i$에 대해: ${}_3C_2 = 3$가지. 3명 중 택 1이므로: $3 \\times 3 = 9$.\n\n2개 이상이 6 이상이면: 합 ≥ 12 > 7이므로 불가.\n\n포함-배제: $36 - 9 = 27$\n\n잠깐, 제한 없는 비음정수해를 다시 계산합니다.\n$y_1+y_2+y_3 = 7$의 비음정수해: ${}_{7+3-1}C_{3-1} = {}_9C_2 = 36$ ✓\n\n$y_i \\geq 6$: $y_i' = y_i - 6$으로 치환하면 나머지 합 = 1.\n$y_i' + y_j + y_k = 1$의 비음정수해: ${}_3C_2 = 3$\n3명 중 누가 6 이상인지: $3 \\times 3 = 9$\n\n27/216. 하지만 직접 세서 확인합니다.\n\n$(x_1, x_2, x_3)$에서 합 = 10:\n$(1,3,6)$: $3! = 6$, $(1,4,5)$: $3! = 6$\n$(2,2,6)$: $3!/2! = 3$, $(2,3,5)$: $3! = 6$, $(2,4,4)$: $3!/2! = 3$\n$(3,3,4)$: $3!/2! = 3$\n$(4,5,1)$: 이미 셈.\n\n합: $6 + 6 + 3 + 6 + 3 + 3 = 27$ ✓\n\n하지만 답이 25... 아, $(1,3,6)$ 자리바꿈 6개, $(1,4,5)$ 6개, $(2,2,6)$ 3개, $(2,3,5)$ 6개, $(2,4,4)$ 3개, $(3,3,4)$ 3개.\n$6+6+3+6+3+3 = 27$이 맞습니다.\n\n선택지에서 ③ 27이 답입니다.\n\n**Step 3. $216 \\times P(S_3 = 10)$ 계산**\n$$216 \\times \\frac{27}{216} = 27$$\n\n**∴ 답: ③ 27**\n\n주사위 3개의 합이 특정 값이 되는 경우의 수를 구하는 문제로, (1) 치환으로 비음정수해 문제로 변환, (2) 포함-배제로 상한 조건 처리라는 2단계를 거칩니다. 직접 나열하여 검증하는 습관이 중요합니다.\n\n**💡 포인트:** 주사위 합 문제는 $y_i = x_i - 1$ 치환 후 상한 조건에 포함-배제를 적용합니다.",
