    "explanation": "**[풀이]**\n\n**핵심 개념:** 초기하분포 + 기댓값 공식 (분포 인식 + 계산)\n\n**Step 1. 분포 인식**\n$$P(X=k) = \\frac{{}_5C_k \\cdot {}_5C_{3-k}}{{{}_{10}C_3}}$$\n\n이는 초기하분포(Hypergeometric distribution)입니다.\n전체 $N=10$개 중 성공 $K=5$개, 실패 $5$개에서 $n=3$개를 비복원추출할 때 성공 횟수 $X$의 분포.\n\n**Step 2. 기댓값 공식**\n초기하분포의 기댓값:\n$$E(X) = n \\cdot \\frac{K}{N} = 3 \\times \\frac{5}{10} = \\frac{3}{2}$$\n\n**Step 3. 직접 계산으로 검증**\n${{}_{10}C_3} = 120$\n\n$P(X=0) = \\frac{1 \\times 10}{120} = \\frac{10}{120}$\n$P(X=1) = \\frac{5 \\times 10}{120} = \\frac{50}{120}$\n$P(X=2) = \\frac{10 \\times 5}{120} = \\frac{50}{120}$\n$P(X=3) = \\frac{10 \\times 1}{120} = \\frac{10}{120}$\n\n합: $\\frac{120}{120} = 1$ ✓\n\n$E(X) = 0 \\times \\frac{10}{120} + 1 \\times \\frac{50}{120} + 2 \\times \\frac{50}{120} + 3 \\times \\frac{10}{120}$\n$= \\frac{0 + 50 + 100 + 30}{120} = \\frac{180}{120} = \\frac{3}{2}$ ✓\n\n**Step 4. 답 계산**\n$$8 \\times E(X) = 8 \\times \\frac{3}{2} = 12$$\n\n**∴ 답: ④ 12**\n\n확률질량함수를 보고 초기하분포임을 인식하는 것이 핵심입니다. 인식하면 공식 $E(X) = n \\cdot K/N$으로 즉시 구할 수 있고, 인식하지 못하면 직접 계산해야 합니다. 분포의 형태를 패턴으로 기억해두세요.\n\n**💡 포인트:** $P(X=k) = \\frac{{}_KC_k \\cdot {}_{N-K}C_{n-k}}{{}_NC_n}$ 형태는 초기하분포입니다.",
