    "explanation": "**[풀이]**\n\n**핵심 개념:** 같은 것이 있는 순열에서 $n$개의 문자 중 같은 것이 각각 $p$개, $q$개, $r$개, …일 때 나열하는 경우의 수는\n$$\\frac{n!}{p!\\,q!\\,r!\\,\\cdots}$$\n\n**Step 1. 문자 확인**\n$x$가 2개, $y$가 2개, $z$가 1개로 총 5개입니다.\n\n**Step 2. 같은 것이 있는 순열 공식 적용**\n$$\\frac{5!}{2!\\times 2!\\times 1!} = \\frac{120}{2\\times 2\\times 1} = \\frac{120}{4} = 30$$\n\n**Step 3. 검증**\n5개를 모두 다른 것으로 보면 $5!=120$가지이고, $x$ 2개의 중복 $2!=2$, $y$ 2개의 중복 $2!=2$를 나누면 $120/4=30$. ✓\n\n**∴ 답: ② 30**\n\n**💡 포인트:** 같은 것이 있는 순열은 전체 $n!$을 같은 것의 개수의 팩토리얼로 나누면 됩니다. 수능 기본 문제로 반드시 공식을 숙지하세요.",
