    "explanation": "**[풀이]**\n\n**핵심 개념:** 원순열에서 특정 조건을 만족하지 않는 배열의 수를 구합니다. 곱이 12가 되는 이웃 쌍을 찾아 여사건을 활용합니다.\n\n**Step 1. 곱이 12인 쌍 찾기**\n1~6에서 두 수의 곱이 12인 쌍: $(2,6)$과 $(3,4)$입니다.\n- $2\\times 6=12$, $3\\times 4=12$\n\n**Step 2. 전체 원순열**\n6개의 의자에 6명을 원형으로 배열: $(6-1)!=5!=120$\n\n**Step 3. 여사건 — 곱12인 이웃 존재하는 경우**\n$A$: 2와 6이 이웃, $B$: 3과 4가 이웃\n\n$|A|$: 2,6을 묶어 원순열 $(5-1)!\\times 2!=4!\\times 2=48$\n$|B|$: 3,4를 묶어 원순열 $4!\\times 2=48$\n$|A\\cap B|$: 2,6 묶음 + 3,4 묶음 → 4개 원순열 $(4-1)!\\times 2!\\times 2!=3!\\times 4=24$\n\n$|A\\cup B|=48+48-24=72$\n\n**Step 4. 답 계산**\n$$120-72=48$$\n\n**∴ 답: 48**\n\n**💡 포인트:** 원순열에서 '~가 아닌' 조건은 여사건(포함-배제)으로 푸는 것이 효율적입니다.",
