    "explanation": "**[풀이]**\n\n**핵심 개념:** 원순열에서 특정인이 특정인과 이웃할 확률. 여사건 활용이 효율적입니다.\n\n**Step 1. 전체 원순열**\n7명의 원순열: $(7-1)!=6!=720$\n\n**Step 2. 여사건 — A가 B와도 C와도 이웃하지 않는 경우**\nA를 고정합니다. A 양옆 2자리에 B, C가 모두 오지 않아야 합니다.\nA 고정 후 나머지 6자리 중 A의 양옆 2자리에 B, C를 제외한 4명 중 2명 배열: $P(4,2)=4\\times 3=12$\n나머지 4자리에 B, C 포함 4명 배열: $4!=24$\n여사건 수: $12\\times 24=288$\n\n**Step 3. 확률 계산**\nA가 B 또는 C와 이웃할 확률:\n$$1-\\frac{288}{720}=1-\\frac{2}{5}=\\frac{3}{5}$$\n\n**∴ 답: ① 3/5**\n\n**💡 포인트:** '~또는~'이 이웃할 확률은 여사건('둘 다 이웃하지 않음')으로 접근하세요.",
