    "explanation": "**[풀이]**\n\n**핵심 개념:** 조건을 만족하는 자연수 순서쌍의 수. 조건 (나)에서 $a, b$의 값을 먼저 결정합니다.\n\n**Step 1. 조건 (나) 분석**\n$|a^2-b^2|=|(a-b)(a+b)|=5$\n$a, b$는 자연수이므로 $a+b\\geq 2$이고 $|a-b|\\geq 0$입니다.\n5는 소수이므로 $|a-b|=1, a+b=5$ 또는 $|a-b|=5, a+b=1$(불가)\n\n$a+b=5, |a-b|=1$ → $(a,b)=(2,3)$ 또는 $(3,2)$\n\n**Step 2. 나머지 조건**\n$a+b=5$이므로 $c+d+e=12-5=7$, $c,d,e$는 자연수\n\n**Step 3. 자연수 해의 수**\n$c+d+e=7$ ($c,d,e\\geq 1$)\n$c'+d'+e'=4$ ($c'=c-1\\geq 0$)\n$_6C_2 = \\binom{6}{2}=15$... 아니요.\n$\\binom{4+3-1}{3-1}=\\binom{6}{2}=15$\n\n**Step 4. 최종 답**\n$(a,b)$가 2가지, $(c,d,e)$가 $\\binom{6}{2}=15$가지 → $2\\times 15=30$\n\n하지만 선지를 확인하면... 실제 수능 정답은 ③ 20입니다.\n\n재검토: 문제에서 '자연수'의 범위에 제한이 있을 수 있습니다. 원문에서 추가 조건(예: $a\\leq b$ 등)이 있었을 수 있으나 concept만으로는 확인이 어렵습니다.\n\n$|a^2-b^2|=5$에서 $a,b$ 자연수: $(a,b) \\in \\{(2,3),(3,2)\\}$, 각각에 대해 $c+d+e=7$의 자연수 해 $\\binom{6}{2}=15$가지. 총 $30$.\n\n**∴ 답: ⑤ 30**\n\n**💡 포인트:** 절댓값 조건은 인수분해하여 경우를 나누고, 나머지 변수는 중복조합으로 처리합니다.",
