    "explanation": "**[풀이]**\n\n**핵심 개념:** 부등식 조건을 만족하는 순서쌍의 수를 $c, d$의 값을 고정하며 세어갑니다.\n\n**Step 1. 조건 정리**\n- $1\\leq a\\leq c\\leq d\\leq 6$\n- $1\\leq b\\leq c\\leq d\\leq 6$\n- $a$와 $b$는 독립적으로 $c$ 이하\n\n**Step 2. $c, d$ 고정 시 $a, b$ 선택**\n$c\\leq d$인 쌍 $(c,d)$를 고정하면:\n- $a$는 $1$부터 $c$까지 → $c$가지\n- $b$는 $1$부터 $c$까지 → $c$가지\n따라서 $(a,b)$의 수: $c^2$\n\n**Step 3. $(c,d)$ 쌍 열거**\n$1\\leq c\\leq d\\leq 6$인 모든 쌍:\n\n| $c$ | $d$의 범위 | $d$의 개수 | $c^2 \\times$ 개수 |\n|-----|-----------|-----------|-------------------|\n| 1 | 1~6 | 6 | $1\\times 6=6$ |\n| 2 | 2~6 | 5 | $4\\times 5=20$ |\n| 3 | 3~6 | 4 | $9\\times 4=36$ |\n| 4 | 4~6 | 3 | $16\\times 3=48$ |\n| 5 | 5~6 | 2 | $25\\times 2=50$ |\n| 6 | 6 | 1 | $36\\times 1=36$ |\n\n**Step 4. 합산**\n$$6+20+36+48+50+36=196$$\n\n**∴ 답: 196**\n\n**💡 포인트:** 부등식 순서쌍은 하나의 변수를 기준으로 고정하고 나머지의 선택 수를 세는 것이 핵심입니다.",
