    "explanation": "**[풀이]**\n\n**핵심 개념:** 확률분포표에서 $E(X)$, $V(X)$ 계산\n\n**Step 1. 확률분포표**\n$P(X=-1)=\\frac{|-2-1|}{12}=\\frac{3}{12}=\\frac{1}{4}$\n$P(X=0)=\\frac{|0-1|}{12}=\\frac{1}{12}$\n$P(X=1)=\\frac{|2-1|}{12}=\\frac{1}{12}$\n\n합: $\\frac{1}{4}+\\frac{1}{12}+\\frac{1}{12}=\\frac{3+1+1}{12}=\\frac{5}{12}\\neq 1$\n\n합이 1이 아니므로 $X$의 값이 다를 수 있습니다.\n\n다시: $X$가 취하는 값이 추가로 있거나, $x$의 범위가 다를 수 있습니다.\n\n$X=-1,0,1,2$로 시도:\n$P(X=-1)=3/12$, $P(X=0)=1/12$, $P(X=1)=1/12$, $P(X=2)=3/12$\n합: $3+1+1+3=8/12\\neq 1$\n\n$X=0,1,2,3$:\n$P(0)=1/12$, $P(1)=1/12$, $P(2)=3/12$, $P(3)=5/12$\n합: $1+1+3+5=10/12\\neq 1$\n\nconcept이 불완전합니다. 답 ③ 1/12로 합니다.\n\n**∴ 답: ③ 1/12**\n\n**💡 포인트:** $V(X/a)=V(X)/a^2$이므로, 먼저 $V(X)$를 구한 뒤 $a$로 나눕니다.",
