    "problem": "같은 종류의 흰 공 4개와 같은 종류의 검은 공 4개, 총 8개의 공을 학생 A, B, C에게 남김없이 나누어 준다. A는 0개 이상 2개 이하, B는 2개 이상 받을 때, 공을 나누어 주는 경우의 수를 구하시오.",
