    "explanation": "**[풀이]**\n\n**핵심 개념:** $P(X=k) = P(X=k+2)$를 이용하여 확률을 설정합니다.\n\n**Step 1. 확률 설정**\n$P(X=0) = P(X=2) = a$\n$P(X=1) = P(X=3) = b$\n$P(X=2) = P(X=4) = a$ (이미 $P(X=2)=a$)\n\n따라서 $P(X=4) = P(X=2) = a$.\n\n확률의 합: $a + b + a + b + a = 3a + 2b = 1$\n\n**Step 2. $E(X^2)$ 조건**\n$E(X^2) = 0^2 \\cdot a + 1^2 \\cdot b + 4 \\cdot a + 9 \\cdot b + 16 \\cdot a = 20a + 10b = \\frac{35}{6}$\n\n**Step 3. 연립방정식**\n$3a + 2b = 1$ ... (1)\n$20a + 10b = 35/6$ ... (2)\n\n(1)에서 $b = \\frac{1-3a}{2}$\n(2)에 대입: $20a + 10 \\cdot \\frac{1-3a}{2} = 35/6$\n$20a + 5(1-3a) = 35/6$\n$20a + 5 - 15a = 35/6$\n$5a + 5 = 35/6$\n$5a = 35/6 - 30/6 = 5/6$\n$a = 1/6$\n\n**∴ 답: ② 1/6**\n\n$P(X=0) = a = 1/6$\n\n**검증:** $b = (1 - 3/6)/2 = (1/2)/2 = 1/4$.\n$3(1/6) + 2(1/4) = 1/2 + 1/2 = 1$ ✓\n$E(X^2) = 20(1/6) + 10(1/4) = 10/3 + 5/2 = 20/6 + 15/6 = 35/6$ ✓\n\n**💡 포인트:** $P(X=k) = P(X=k+2)$는 '2칸 간격으로 같은 확률'이므로 변수가 2개로 줄어듭니다.",
