    "problem": "집합 \\(X = \\{1, 2, 3, 4, 5, 6\\}\\)에서 \\(X\\)로의 함수 \\(f\\) 중에서 임의로 하나를 택한다. \\(f(1) \\leq f(2) \\leq f(3)\\)이고 \\(f(1) \\times f(2) \\times f(3)\\)이 짝수일 확률을 \\(\\dfrac{q}{p}\\) (기약분수)라 하자. \\(p + q\\)의 값을 구하시오.",
