    "explanation": "**[풀이]**\n\n**핵심 개념:** 세 수의 합이 짝수가 되려면 (짝+짝+짝) 또는 (짝+홀+홀)이어야 합니다.\n\n**Step 1. 전체 경우의 수**\n8장 중 3장을 뽑는 경우의 수는\n$$_8C_3 = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1} = 56$$\n\n**Step 2. 홀수와 짝수 파악**\n1~8 중 홀수: 1, 3, 5, 7 → 4개\n짝수: 2, 4, 6, 8 → 4개\n\n**Step 3. 합이 짝수인 경우**\n(1) 짝수 3장: $_4C_3 = 4$\n(2) 짝수 1장 + 홀수 2장: $_4C_1 \\times _4C_2 = 4 \\times 6 = 24$\n합이 짝수인 경우: $4 + 24 = 28$\n\n**Step 4. 확률 계산**\n$$P = \\frac{28}{56} = \\frac{1}{2}$$\n\n**∴ 답: ③ $\\frac{1}{2}$**\n\n① $\\frac{5}{14}$는 홀수 3장만 센 경우, ⑤ $\\frac{9}{14}$는 합이 홀수인 경우의 확률입니다.\n\n**💡 포인트:** 합의 홀짝은 홀수 개수로 결정됩니다. 홀수가 0개 또는 2개이면 합이 짝수입니다.",
